insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('4', '0.68', '2026-07-10 14:07:52.02522+00', '1536', 'text-embedding-3-small', 'v2', 'The founder seeks feedback only from people likely to support the idea. Contradictory signals are unconsciously filtered out or rationalized away.', '["all"]', 'external', 'Stage 0', '1', 'Psychological', 'RC-004', 'Confirmation Bias', '2026-08-03 03:11:45.313913+00') on conflict do nothing;
