insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('665', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The team has no metrics or alerts that signal when a process is under stress. Problems are only discovered after they have already caused visible damage.', '["all"]', 'external', 'Stage 1→10+', '47', 'Operational', 'RC-665', 'No Early Warning Systems Built', '2026-08-03 03:12:14.376947+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('666', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Processes only worked because the founder was personally managing them. When they stepped back, the process failed — revealing it was never really a process, just founder oversight.', '["all"]', 'external', 'Stage 1→10+', '47', 'Behavioural', 'RC-666', 'Founder Removal Exposed Process Fragility', '2026-08-03 03:11:30.572732+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('667', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Founders and early team members view documentation as bureaucratic overhead. Knowledge stays in people heads because writing it down never feels urgent until someone leaves.', '["all"]', 'external', 'Stage 1→10+', '48', 'Behavioural', 'RC-667', 'Documentation Treated as Low Priority', '2026-08-03 03:11:30.76418+00') on conflict do nothing;
