insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('669', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The team moves so fast that pausing to document feels like slowing down. A culture of speed without structure means the same problems are solved repeatedly from scratch.', '["all"]', 'external', 'Stage 1→10+', '48', 'Behavioural', 'RC-669', 'Speed Culture Discourages Documentation', '2026-08-03 03:11:31.41053+00') on conflict do nothing;
