insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('678', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder assumes team members have context that was never explicitly shared. What is obvious to the founder is invisible to team members who were not in early conversations.', '["all"]', 'external', 'Stage 1→10+', '51', 'Psychological', 'RC-678', 'Founder Assumption That Team Has Same Context', '2026-08-03 03:11:45.10512+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('679', '0.82', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Onboarding was never designed as a system. New hires learn from whoever has time — creating inconsistent understanding of how the company actually works.', '["all"]', 'external', 'Stage 1→10+', '52', 'Operational', 'RC-679', 'No Structured Onboarding Programme Built', '2026-08-03 03:12:14.524958+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('680', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'When the company is growing fast, onboarding gets squeezed out by operational urgency. The cost of poor onboarding — slow ramp, inconsistent quality — compounds over time.', '["all"]', 'external', 'Stage 1→10+', '52', 'Behavioural', 'RC-680', 'Onboarding Deprioritised During Growth', '2026-08-03 03:11:31.503369+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('681', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Generic onboarding materials exist but role-specific knowledge transfer was never built. Each new hire figures out their specific job largely on their own.', '["all"]', 'external', 'Stage 1→10+', '52', 'Operational', 'RC-681', 'No Role-Specific Onboarding Materials', '2026-08-03 03:12:14.671901+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('682', '0.82', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Quality was maintained by founder oversight when the team was small. No formal QA process, standards, or review mechanism was built before the founder stepped back.', '["all"]', 'external', 'Stage 1→10+', '53', 'Operational', 'RC-682', 'No Formal Quality Management System', '2026-08-03 03:12:14.62285+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('683', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'What constitutes good quality exists only in the founder head. Without documented standards, team members work to different definitions of acceptable output.', '["all"]', 'external', 'Stage 1→10+', '53', 'Knowledge', 'RC-683', 'Standards Implicit Rather Than Documented', '2026-08-03 03:11:31.641554+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('684', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Quality checking resources did not scale with output volume. The same number of people checking a much larger amount of work means more errors slip through.', '["all"]', 'external', 'Stage 1→10+', '53', 'Operational', 'RC-684', 'Insufficient QA Resources for Increased Volume', '2026-08-03 03:12:14.775026+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('685', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Manager roles were created but the boundaries of their decision-making authority were never explicitly defined. Managers do not know what they can decide independently.', '["all"]', 'external', 'Stage 1→10+', '54', 'Strategic', 'RC-685', 'Management Roles Defined Without Clarity on Authority', '2026-08-03 03:11:30.809314+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('686', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder regularly overrides manager decisions in front of the team. This undermines manager credibility and teaches the team to escalate everything to the founder.', '["all"]', 'external', 'Stage 1→10+', '54', 'Behavioural', 'RC-686', 'Founder Overriding Managers Publicly', '2026-08-03 03:11:31.686896+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('687', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Newly promoted managers have no training for their new role. They were excellent individual contributors but managing people is a different skill that was never developed.', '["all"]', 'external', 'Stage 1→10+', '54', 'Knowledge', 'RC-687', 'No Management Training or Development Programme', '2026-08-03 03:12:14.720181+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('688', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Decision processes that required one person now require multiple stakeholders. No work was done to define which decisions are routine and can be made quickly by one person.', '["all"]', 'external', 'Stage 1→10+', '55', 'Operational', 'RC-688', 'Too Many People Required to Make Routine Decisions', '2026-08-03 03:11:31.550156+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('689', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'As more is at stake, managers become more conservative and escalate more decisions upward. A culture of caution replaces the startup original bias toward speed.', '["all"]', 'external', 'Stage 1→10+', '55', 'Psychological', 'RC-689', 'Risk Aversion Increasing as Company Grows', '2026-08-03 03:12:14.876795+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('690', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'No documented principles exist for how decisions should be made at different levels. Without this, every decision gets made differently depending on who is involved.', '["all"]', 'external', 'Stage 1→10+', '55', 'Strategic', 'RC-690', 'No Decision-Making Framework or Principles Defined', '2026-08-03 03:12:14.82427+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('691', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder sense of value and contribution is tied to doing work rather than enabling others. Stepping back from execution feels like becoming less important.', '["all"]', 'external', 'Stage 1→10+', '56', 'Psychological', 'RC-691', 'Identity Tied to Hands-On Contribution', '2026-08-03 03:11:31.735038+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('692', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Deep down the founder does not believe the team can do the work to the required standard without their involvement. This belief — often unconscious — prevents real delegation.', '["all"]', 'external', 'Stage 1→10+', '56', 'Psychological', 'RC-692', 'Lack of Trust in Team Capability', '2026-08-03 03:11:20.176531+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('693', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'No deliberate plan was made for how the founder would shift from doing to leading. The transition was assumed to happen naturally rather than being designed.', '["all"]', 'external', 'Stage 1→10+', '56', 'Strategic', 'RC-693', 'No Transition Plan from Operator to Leader', '2026-08-03 03:11:26.969504+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('694', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Financial systems were built for one revenue model and were never restructured as new streams were added. Consolidated reporting requires manual work to produce.', '["all"]', 'external', 'Stage 1→10+', '57', 'Operational', 'RC-694', 'No Unified Financial Reporting Across Streams', '2026-08-03 03:11:44.751356+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('695', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Separate billing systems for different revenue streams create reconciliation challenges, payment timing mismatches, and visibility gaps.', '["all"]', 'external', 'Stage 1→10+', '57', 'Operational', 'RC-695', 'Different Billing Systems Not Integrated', '2026-08-03 03:11:29.872336+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('696', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'New revenue streams were launched without building the financial management infrastructure to support them. Growth outpaced the company financial operational capability.', '["all"]', 'external', 'Stage 1→10+', '57', 'Strategic', 'RC-696', 'Revenue Model Complexity Added Without Finance Infrastructure', '2026-08-03 03:11:44.802109+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('697', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Pricing was set for one customer type and never updated as the company began serving enterprises, SMBs, and different verticals with very different willingness to pay.', '["all"]', 'external', 'Stage 1→10+', '58', 'Strategic', 'RC-697', 'No Formal Pricing Strategy for Different Customer Segments', '2026-08-03 03:11:29.687195+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('698', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'No formal discount policy exists. Salespeople use their own judgment on pricing, creating wide variance in deal terms and eroding pricing integrity.', '["all"]', 'external', 'Stage 1→10+', '58', 'Operational', 'RC-698', 'Sales Team Empowered to Discount Without Framework', '2026-08-03 03:11:45.003584+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('699', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The pricing model was designed when the founder had limited understanding of different customer segments. It was never revisited as segment clarity improved.', '["all"]', 'external', 'Stage 1→10+', '58', 'Knowledge', 'RC-699', 'Original Pricing Set Without Segmentation Analysis', '2026-08-03 03:11:45.053519+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('700', '0.82', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Subscription renewals are not tracked proactively. The team discovers churn only after it happens rather than managing accounts toward renewal.', '["all"]', 'external', 'Stage 1→10+', '59', 'Operational', 'RC-700', 'No Renewal Tracking System Built', '2026-08-03 03:12:09.679404+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('701', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'No system exists to identify which customers are at risk before they cancel. Without leading indicators, the team cannot intervene before it is too late.', '["all"]', 'external', 'Stage 1→10+', '59', 'Operational', 'RC-701', 'No Customer Health Scoring System', '2026-08-03 03:11:31.782391+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('702', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Customer success is seen as a support function rather than a revenue function. The connection between retention work and revenue impact is not tracked.', '["all"]', 'external', 'Stage 1→10+', '59', 'Strategic', 'RC-702', 'Customer Success Not Treated as a Revenue Function', '2026-08-03 03:12:14.925022+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('703', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Sales compensation, marketing budgets, and leadership attention are all focused on acquiring new customers. Retention receives minimal resource allocation.', '["all"]', 'external', 'Stage 1→10+', '60', 'Operational', 'RC-703', 'Incentives Aligned Entirely to New Customer Acquisition', '2026-08-03 03:12:14.973803+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('704', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'NRR, churn rate, and expansion revenue are not measured or reported alongside acquisition metrics. What is not measured does not get managed.', '["all"]', 'external', 'Stage 1→10+', '60', 'Operational', 'RC-704', 'Retention Metrics Not Tracked or Reported', '2026-08-03 03:12:15.072216+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('705', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The investment in post-sale customer success is a fraction of pre-sale sales and marketing. This structural imbalance makes churn mathematically inevitable at scale.', '["all"]', 'external', 'Stage 1→10+', '60', 'Strategic', 'RC-705', 'Customer Success Team Underfunded Relative to Sales', '2026-08-03 03:11:31.972368+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('706', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Sales pipeline data is incomplete, inconsistently updated, and insufficiently detailed to produce reliable revenue forecasts.', '["all"]', 'external', 'Stage 1→10+', '61', 'Operational', 'RC-706', 'Pipeline Tracking Not Disciplined Enough for Forecasting', '2026-08-03 03:11:32.019508+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('707', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'As the customer base shifts toward enterprise, sales cycles lengthen significantly. Forecasting models built on SMB cycle times are no longer accurate.', '["all"]', 'external', 'Stage 1→10+', '61', 'Strategic', 'RC-707', 'Sales Cycle Lengthening as Enterprise Mix Increases', '2026-08-03 03:11:31.82971+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('708', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Salespeople consistently overestimate deal probability and close timing. Without a disciplined review process that adjusts for this, forecasts are systematically inflated.', '["all"]', 'external', 'Stage 1→10+', '61', 'Psychological', 'RC-708', 'Optimism Bias in Sales Team Reporting', '2026-08-03 03:11:30.855082+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('709', '0.82', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Spending authority was never formally limited as the team grew. Team members continue to spend at the discretion they had when the company was smaller.', '["all"]', 'external', 'Stage 1→10+', '62', 'Operational', 'RC-709', 'No Budget Approval Process as Company Scaled', '2026-08-03 03:12:15.122697+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('710', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The finance team remained small while the company grew, leaving insufficient capacity to monitor, forecast, and control spending across a larger organisation.', '["all"]', 'external', 'Stage 1→10+', '62', 'Operational', 'RC-710', 'Finance Function Not Scaled with Company', '2026-08-03 03:12:15.023783+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('711', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Pressure to hit growth targets creates a culture where spending is justified by growth intent rather than measured against financial capacity or plan.', '["all"]', 'external', 'Stage 1→10+', '62', 'Behavioural', 'RC-711', 'Growth Pressure Overriding Financial Discipline', '2026-08-03 03:12:15.172889+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('712', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Enterprise customers demand longer payment terms as a condition of signing. The founder agrees to win the deal without fully modelling the working capital impact.', '["all"]', 'external', 'Stage 1→10+', '63', 'Strategic', 'RC-712', 'Payment Terms Extended to Win Enterprise Deals', '2026-08-03 03:12:15.267726+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('713', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'For product businesses, inventory is ordered well in advance of need, trapping cash. No inventory optimisation system was built to reduce working capital requirements.', '["all"]', 'external', 'Stage 1→10+', '63', 'Operational', 'RC-713', 'Inventory Levels Not Optimised for Cash Efficiency', '2026-08-03 03:11:32.068774+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('714', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder monitors P and L profitability but does not model cash flow separately. A profitable business on paper can run out of cash due to timing differences.', '["all"]', 'external', 'Stage 1→10+', '63', 'Knowledge', 'RC-714', 'Cash Flow Not Modelled Separately from P and L', '2026-08-03 03:11:32.116192+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('715', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The incremental cost of serving large enterprise customers — more support, more customisation, more compliance — was never calculated. Margins erode invisibly.', '["all"]', 'external', 'Stage 1→10+', '64', 'Knowledge', 'RC-715', 'Cost to Serve Enterprise Customers Not Modelled', '2026-08-03 03:11:31.877017+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('716', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Overall gross margin is tracked but not broken down by customer type, product line, or channel. Margin erosion in specific segments is invisible until it affects the total.', '["all"]', 'external', 'Stage 1→10+', '64', 'Operational', 'RC-716', 'No Gross Margin Tracking by Customer Segment', '2026-08-03 03:11:30.914114+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('717', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'As the company grows, operational costs — headcount, tools, infrastructure — are growing faster than revenue. No process exists to regularly benchmark this ratio.', '["all"]', 'external', 'Stage 1→10+', '64', 'Operational', 'RC-717', 'Operational Costs Scaling Faster Than Revenue', '2026-08-03 03:12:15.220006+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('718', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Commission structures reward behaviours — volume, new logos — that are not aligned with what the business actually needs — margin, retention, strategic accounts.', '["all"]', 'external', 'Stage 1→10+', '65', 'Strategic', 'RC-718', 'Sales Compensation Not Aligned with Business Priorities', '2026-08-03 03:12:15.317485+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('719', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The compensation plan has too many variables and exceptions. Sales reps cannot quickly calculate their own earnings, reducing the motivational effect of the incentive.', '["all"]', 'external', 'Stage 1→10+', '65', 'Operational', 'RC-719', 'Commission Plan Too Complex to Be Motivating', '2026-08-03 03:11:20.690576+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('720', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The sales compensation plan was set once and never formally reviewed. As the business model evolved, the incentives became increasingly misaligned.', '["all"]', 'external', 'Stage 1→10+', '65', 'Operational', 'RC-720', 'No Regular Review of Commission Structure Effectiveness', '2026-08-03 03:11:27.177006+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('721', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The accounting treatment of revenue was appropriate for the original business model but was never revisited as new revenue streams, contract structures, and geographies were added.', '["all"]', 'external', 'Stage 1→10+', '66', 'Knowledge', 'RC-721', 'Revenue Recognition Not Reviewed as Model Scaled', '2026-08-03 03:12:15.365485+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('722', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The accounting and billing system was built for one revenue type and cannot correctly handle deferred revenue, multi-year contracts, or usage-based billing.', '["all"]', 'external', 'Stage 1→10+', '66', 'Operational', 'RC-722', 'No Finance System to Handle Multi-Stream Revenue Correctly', '2026-08-03 03:11:32.210818+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('723', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founding finance team has strong bookkeeping skills but lacks expertise in complex revenue recognition standards required at this stage.', '["all"]', 'external', 'Stage 1→10+', '66', 'Knowledge', 'RC-723', 'Finance Team Skill Gap in Complex Revenue Accounting', '2026-08-03 03:11:32.163336+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('724', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Churn is reported as a percentage of users or accounts rather than revenue. This masks the disproportionate financial impact of losing high-value customers.', '["all"]', 'external', 'Stage 1→10+', '67', 'Operational', 'RC-724', 'Churn Measured at User Level Not Revenue Level', '2026-08-03 03:11:32.354559+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('725', '0.82', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Without customer health scoring or proactive outreach, churn is only discovered at renewal — when it is already too late to save the account.', '["all"]', 'external', 'Stage 1→10+', '67', 'Operational', 'RC-725', 'No Early Warning System for At-Risk Accounts', '2026-08-03 03:11:31.924611+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('726', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'LTV models were built on early customer cohort data when retention was higher. As churn increases, LTV projections overestimate customer lifetime and unit economics appear healthier than they are.', '["all"]', 'external', 'Stage 1→10+', '67', 'Knowledge', 'RC-726', 'LTV Calculations Not Updated to Reflect Declining Tenure', '2026-08-03 03:11:32.257644+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('727', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Financial plans are built in static spreadsheets with no ability to quickly model different scenarios. Decisions are made without understanding their sensitivity to assumptions.', '["all"]', 'external', 'Stage 1→10+', '68', 'Operational', 'RC-727', 'Financial Planning Done in Spreadsheets Without Scenario Modelling', '2026-08-03 03:12:15.42336+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('728', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Financial forecasts are produced annually and rarely updated. The plan becomes disconnected from reality within weeks of being created.', '["all"]', 'external', 'Stage 1→10+', '68', 'Operational', 'RC-728', 'No Rolling Forecast Updated Monthly', '2026-08-03 03:12:15.469484+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('729', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Financial planning happens separately from operational planning. Resource allocation decisions are not grounded in financial model outputs.', '["all"]', 'external', 'Stage 1→10+', '68', 'Strategic', 'RC-729', 'Finance and Operations Not Connected in Planning Process', '2026-08-03 03:11:40.340951+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('730', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Leading through managers requires different skills than direct leadership. The founder never developed the ability to coach, develop, and hold managers accountable.', '["all"]', 'external', 'Stage 1→10+', '69', 'Knowledge', 'RC-730', 'Founder Has Not Developed Manager Coaching Skills', '2026-08-03 03:11:32.408118+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('731', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'What managers are expected to own, decide, and deliver was never formally communicated. Ambiguity causes managers to underdelegate upward and second-guess their authority.', '["all"]', 'external', 'Stage 1→10+', '69', 'Operational', 'RC-731', 'Manager Expectations Not Explicitly Set', '2026-08-03 03:12:15.517785+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('732', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Under pressure, the founder reverts to direct contact with individual contributors. This undermines the management layer and signals that managers authority is conditional.', '["all"]', 'external', 'Stage 1→10+', '69', 'Behavioural', 'RC-732', 'Founder Bypasses Managers During Stressful Periods', '2026-08-03 03:12:15.565684+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('733', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Performance reviews never became a formal system. Feedback is given informally, inconsistently, and usually only when a problem is already serious.', '["all"]', 'external', 'Stage 1→10+', '70', 'Operational', 'RC-733', 'No Formal Review Process Designed as Team Grew', '2026-08-03 03:11:30.962326+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('734', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Giving negative feedback feels confrontational and relationship-damaging. Founders avoid it, which causes underperformance to persist unchecked.', '["all"]', 'external', 'Stage 1→10+', '70', 'Psychological', 'RC-734', 'Founder Uncomfortable with Difficult Feedback Conversations', '2026-08-03 03:12:15.620799+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('735', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Without documented performance expectations, team members do not know what excellent looks like. Reviews become subjective and feel unfair.', '["all"]', 'external', 'Stage 1→10+', '70', 'Knowledge', 'RC-735', 'No Clear Performance Standards Defined for Roles', '2026-08-03 03:11:32.305181+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('736', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Planning for someone else to fill a role feels like admitting vulnerability or planning for failure. Founders delay it indefinitely.', '["all"]', 'external', 'Stage 1→10+', '71', 'Psychological', 'RC-736', 'Succession Planning Feels Premature to the Founder', '2026-08-03 03:11:32.456207+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('737', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Key institutional knowledge — relationships, processes, context — exists only in the heads of a few individuals. No systematic knowledge transfer has occurred.', '["all"]', 'external', 'Stage 1→10+', '71', 'Operational', 'RC-737', 'Critical Knowledge Not Documented or Transferred', '2026-08-03 03:11:32.502183+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('738', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The company has not invested in developing internal candidates for senior roles. When a senior person leaves, there is no one ready to step into the gap.', '["all"]', 'external', 'Stage 1→10+', '71', 'Strategic', 'RC-738', 'No Internal Talent Development Pipeline', '2026-08-03 03:12:15.675648+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('739', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Salaries are set based on negotiation and intuition rather than market data. This creates pay inequity that only becomes visible when someone compares notes.', '["all"]', 'external', 'Stage 1→10+', '72', 'Knowledge', 'RC-739', 'No Compensation Benchmarking Process Established', '2026-08-03 03:12:15.76978+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('740', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The option pool was sized for early team members and is now insufficient to offer meaningful equity to senior hires who expect market-rate grants.', '["all"]', 'external', 'Stage 1→10+', '72', 'Strategic', 'RC-740', 'Equity Pool Not Planned for Growth Stage Hiring Needs', '2026-08-03 03:12:15.722659+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('741', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Different vesting terms were agreed at different times without a consistent framework. This creates resentment when team members compare arrangements.', '["all"]', 'external', 'Stage 1→10+', '72', 'Operational', 'RC-741', 'Vesting Schedules Inconsistent Across Team', '2026-08-03 03:12:15.818024+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('742', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Culture was never deliberately designed. It emerged from early team dynamics and the founder personal style. As the team grew, the founder influence diluted and no designed culture filled the gap.', '["all"]', 'external', 'Stage 1→10+', '73', 'Behavioural', 'RC-742', 'Culture Left to Emerge Rather Than Intentionally Built', '2026-08-03 03:11:32.558244+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('743', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Company values exist on paper but are not used as decision criteria in hiring, performance management, or promotions. Values become decoration rather than direction.', '["all"]', 'external', 'Stage 1→10+', '73', 'Behavioural', 'RC-743', 'Values Documented but Not Reinforced in Decisions', '2026-08-03 03:11:32.605808+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('744', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'New hires join with no explicit communication about the company cultural norms. They pick up whatever behaviour is modelled around them — which varies by team.', '["all"]', 'external', 'Stage 1→10+', '73', 'Operational', 'RC-744', 'Cultural Norms Not Transferred During Onboarding', '2026-08-03 03:11:31.009473+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('745', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'No regular structured way for employees to share how they are feeling about the company exists. Morale problems build invisibly until they cause attrition.', '["all"]', 'external', 'Stage 1→10+', '74', 'Operational', 'RC-745', 'No Employee Feedback Mechanisms Built', '2026-08-03 03:11:32.74671+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('746', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Team members do not know how the company is performing, where it is heading, or how their work contributes. Disconnection from purpose reduces engagement.', '["all"]', 'external', 'Stage 1→10+', '74', 'Operational', 'RC-746', 'Communication of Company Direction and Progress Insufficient', '2026-08-03 03:12:15.870704+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('747', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The company is growing fast and the team is stretched. Sustained overwork without recognition or relief reduces motivation and increases burnout risk.', '["all"]', 'external', 'Stage 1→10+', '74', 'Behavioural', 'RC-747', 'High Growth Pace Creating Chronic Overwork', '2026-08-03 03:12:15.981421+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('748', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'As teams compete for limited budget and headcount, collaboration becomes a threat to local interests. Teams start hoarding information and blocking each other.', '["all"]', 'external', 'Stage 1→10+', '75', 'Strategic', 'RC-748', 'Resource Scarcity Creating Zero-Sum Team Competition', '2026-08-03 03:12:15.931681+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('749', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'When teams disagree, there is no established process for resolution. Conflicts get escalated to the founder or resolved informally through whoever has more political influence.', '["all"]', 'external', 'Stage 1→10+', '75', 'Operational', 'RC-749', 'No Clear Decision Process for Cross-Team Conflicts', '2026-08-03 03:11:27.367208+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('750', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Without clear team-level metrics, success is ambiguous and contested. Teams compete for credit when things go well and deflect blame when things go badly.', '["all"]', 'external', 'Stage 1→10+', '75', 'Operational', 'RC-750', 'Unclear Metrics Create Competition Over Credit', '2026-08-03 03:11:20.830732+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('751', '0.82', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Individual contributors are promoted into management based on technical performance without any training in people leadership, coaching, or feedback skills.', '["all"]', 'external', 'Stage 1→10+', '76', 'Knowledge', 'RC-751', 'Promoted Without Management Skill Development', '2026-08-03 03:11:32.653106+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('752', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'After being promoted, new managers receive no coaching, peer support, or structured feedback on their leadership performance. They succeed or fail entirely on their own.', '["all"]', 'external', 'Stage 1→10+', '76', 'Operational', 'RC-752', 'No Manager Support Structure After Promotion', '2026-08-03 03:12:16.029852+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('753', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'What a manager is expected to do differently from an individual contributor is never explicitly communicated. New managers default to doing their old job plus some administrative tasks.', '["all"]', 'external', 'Stage 1→10+', '76', 'Operational', 'RC-753', 'Expectations of New Manager Role Not Clearly Defined', '2026-08-03 03:11:34.41085+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('754', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Job descriptions and role boundaries were set during an earlier stage and never updated. As the organisation grew, responsibilities overlapped and gaps appeared.', '["all"]', 'external', 'Stage 1→10+', '77', 'Operational', 'RC-754', 'Roles Not Redefined as Company Structure Evolved', '2026-08-03 03:11:32.699755+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('755', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Team members have no visibility into how they advance in the organisation. Without a clear path forward, high performers explore opportunities elsewhere.', '["all"]', 'external', 'Stage 1→10+', '77', 'Strategic', 'RC-755', 'No Career Progression Framework Communicated', '2026-08-03 03:12:16.076528+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('756', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The company grew so quickly that roles were created reactively to fill immediate needs rather than designed as part of a coherent organisational structure.', '["all"]', 'external', 'Stage 1→10+', '77', 'Operational', 'RC-756', 'Fast Growth Outpaced Role Clarity', '2026-08-03 03:11:34.456481+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('757', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'No pulse surveys, engagement scores, or structured feedback mechanisms exist. The founder relies on intuition and informal conversations to assess culture health.', '["all"]', 'external', 'Stage 1→10+', '78', 'Operational', 'RC-757', 'No Systematic Employee Sentiment Measurement', '2026-08-03 03:12:16.123269+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('758', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Metrics that predict engagement decline — absenteeism, meeting participation, voluntary attrition — are not tracked. Problems only become visible after damage is done.', '["all"]', 'external', 'Stage 1→10+', '78', 'Operational', 'RC-758', 'Early Warning Signals for Morale Problems Not Tracked', '2026-08-03 03:11:16.560228+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('759', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder and leadership team believe the culture is healthy because they do not hear otherwise. The absence of complaints is mistaken for evidence of engagement.', '["all"]', 'external', 'Stage 1→10+', '78', 'Psychological', 'RC-759', 'Leadership Overconfident in Culture Health Without Data', '2026-08-03 03:11:31.057724+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('760', '0.82', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The company grew on the strength of being first but never built lasting competitive advantages — switching costs, proprietary data, network effects, brand — that would protect position.', '["all"]', 'external', 'Stage 1→10+', '79', 'Strategic', 'RC-760', 'No Defensible Competitive Moat Built', '2026-08-03 03:11:34.547882+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('761', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Proving the concept made the opportunity visible to larger, better-resourced competitors. The founder did not anticipate how quickly success would attract competition.', '["all"]', 'external', 'Stage 1→10+', '79', 'Strategic', 'RC-761', 'Market Validation Attracted Well-Funded Imitators', '2026-08-03 03:11:34.502111+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('762', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'No process exists for tracking competitor moves, pricing changes, or new entrants. Competitive threats are discovered reactively rather than anticipated.', '["all"]', 'external', 'Stage 1→10+', '79', 'Operational', 'RC-762', 'Competitive Intelligence Not Monitored Systematically', '2026-08-03 03:11:16.609792+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('763', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The original differentiation was feature-based. Competitors have caught up and the features that were unique are now table stakes across the category.', '["all"]', 'external', 'Stage 1→10+', '80', 'Strategic', 'RC-763', 'Advantage Built on Features That Are Now Standard', '2026-08-03 03:11:16.657232+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('764', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'While defending the current position, no resources have been allocated to building the next source of differentiation. The company is in maintenance mode on its moat.', '["all"]', 'external', 'Stage 1→10+', '80', 'Strategic', 'RC-764', 'No Investment in Next-Generation Competitive Advantage', '2026-08-03 03:11:27.764215+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('765', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The company has built customer relationships and brand equity that could be defensible advantages but these have not been intentionally developed as competitive barriers.', '["all"]', 'external', 'Stage 1→10+', '80', 'Strategic', 'RC-765', 'Brand and Relationships Not Leveraged as Defence', '2026-08-03 03:12:16.171293+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('766', '0.82', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The product was designed for early adopter users who had high tolerance for gaps. Enterprise buyers require SLAs, security certifications, and support standards that were never built.', '["all"]', 'external', 'Stage 1→10+', '81', 'Operational', 'RC-766', 'Product and Support Not Built for Enterprise Requirements', '2026-08-03 03:11:34.751468+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('767', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'As more enterprise customers are acquired, the support and success burden increases significantly. The customer success team was not scaled to meet these demands.', '["all"]', 'external', 'Stage 1→10+', '81', 'Operational', 'RC-767', 'Customer Success Capacity Not Scaled for Enterprise Demands', '2026-08-03 03:11:34.599978+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('768', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Enterprise customers require significantly more resources to serve but pricing reflects the original SMB model. Margins deteriorate without a visible mechanism.', '["all"]', 'external', 'Stage 1→10+', '81', 'Strategic', 'RC-768', 'Pricing Not Adjusted for Higher Enterprise Cost to Serve', '2026-08-03 03:11:34.64562+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('769', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The company competed on price and features rather than investing in brand, expertise positioning, or community that could justify premium pricing as the market matured.', '["all"]', 'external', 'Stage 1→10+', '82', 'Strategic', 'RC-769', 'No Premium Positioning or Brand Differentiation Developed', '2026-08-03 03:12:16.220388+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('770', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The speed of market maturation exceeded the company ability to build defensible differentiation. What worked in an emerging market does not work in a mature one.', '["all"]', 'external', 'Stage 1→10+', '82', 'Strategic', 'RC-770', 'Category Matured Faster Than Differentiation Was Built', '2026-08-03 03:12:16.321704+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('771', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'In response to competitive pressure, the company reduced prices to protect volume. This accelerated margin erosion and signalled commodity status to the market.', '["all"]', 'external', 'Stage 1→10+', '82', 'Behavioural', 'RC-771', 'Race to Bottom on Pricing to Maintain Volume', '2026-08-03 03:12:16.268921+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('772', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The company is pursuing too many strategic bets simultaneously. Resources are too thin to execute any single initiative to full potential.', '["all"]', 'external', 'Stage 1→10+', '83', 'Strategic', 'RC-772', 'Resources Spread Across Too Many Initiatives', '2026-08-03 03:12:16.370111+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('773', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'New product initiatives are launched without a clear theory of why this is the right time and how it connects to the core business strategy.', '["all"]', 'external', 'Stage 1→10+', '83', 'Strategic', 'RC-773', 'Innovation Work Not Connected to Clear Strategic Rationale', '2026-08-03 03:11:31.116723+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('774', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The existing product base is stagnating as leadership attention moves to new initiatives. Core customer satisfaction is declining without being noticed.', '["all"]', 'external', 'Stage 1→10+', '83', 'Operational', 'RC-774', 'Core Business Quality Suffering While Attention Goes to New Products', '2026-08-03 03:11:34.798258+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('775', '0.82', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The majority of customer acquisition flows through one platform — an app store, a marketplace, a social network — creating existential dependency on one party decisions.', '["all"]', 'external', 'Stage 1→10+', '84', 'Strategic', 'RC-775', 'Over-Reliance on Single Distribution Platform', '2026-08-03 03:11:34.706296+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('776', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The risk of platform policy changes, algorithm updates, or fee increases was never formally assessed or built into business continuity planning.', '["all"]', 'external', 'Stage 1→10+', '84', 'Strategic', 'RC-776', 'Platform Risk Not Assessed or Mitigated', '2026-08-03 03:11:31.169647+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('777', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Despite the concentration risk, no serious investment was made in building alternative channels that could sustain the business if the primary platform became unavailable.', '["all"]', 'external', 'Stage 1→10+', '84', 'Operational', 'RC-777', 'No Alternative Distribution Channel Developed', '2026-08-03 03:12:16.416943+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('778', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'No structured programme exists to reward and deepen relationships with long-term customers. Loyalty is assumed rather than designed.', '["all"]', 'external', 'Stage 1→10+', '85', 'Operational', 'RC-778', 'No Formal Customer Loyalty or Retention Programme', '2026-08-03 03:12:16.512314+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('779', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The team celebrates new customer wins while long-term customers receive declining attention. Tenure and loyalty are not recognised or reinforced.', '["all"]', 'external', 'Stage 1→10+', '85', 'Behavioural', 'RC-779', 'Long-Term Customer Neglect as Attention Goes to New Acquisition', '2026-08-03 03:11:45.153983+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('780', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Customer relationships are managed reactively — the team responds to requests but does not proactively add value, share insights, or deepen the relationship.', '["all"]', 'external', 'Stage 1→10+', '85', 'Operational', 'RC-780', 'No Proactive Account Management for Mature Customers', '2026-08-03 03:11:30.429299+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('781', '0.82', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'A key partner relationship drives significant revenue but operates without a formal contract defining commitments, exclusivity, or notice periods.', '["all"]', 'external', 'Stage 1→10+', '86', 'Strategic', 'RC-781', 'Partnership Critical to Revenue but No Formal Agreement', '2026-08-03 03:12:16.562084+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('782', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The partnership became the default GTM motion. No parallel channel was developed, making the business critically dependent on the partner continued cooperation.', '["all"]', 'external', 'Stage 1→10+', '86', 'Strategic', 'RC-782', 'No Alternative Go-to-Market Developed Alongside Key Partnership', '2026-08-03 03:12:16.464292+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('783', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The partnership has no formal review cadence, performance metrics, or governance structure. Misalignment builds undetected until a crisis surfaces.', '["all"]', 'external', 'Stage 1→10+', '86', 'Operational', 'RC-783', 'Partner Relationship Managed Informally Without Review Cadence', '2026-08-03 03:11:34.892044+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('784', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Compliance requirements in the new market were assessed superficially before entry. Legal, tax, data, and employment obligations differ significantly from the home market.', '["all"]', 'external', 'Stage 1→10+', '87', 'Knowledge', 'RC-784', 'Local Market Regulatory Requirements Underestimated', '2026-08-03 03:11:34.84539+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('785', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The product was launched in new markets without meaningful localisation — language, payment methods, local integrations, cultural adjustments. Adoption fails as a result.', '["all"]', 'external', 'Stage 1→10+', '87', 'Operational', 'RC-785', 'Product Not Localised for New Market Requirements', '2026-08-03 03:11:34.938998+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('786', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Senior leadership attention is divided across multiple international markets simultaneously. The home market suffers and no single international market receives sufficient focus.', '["all"]', 'external', 'Stage 1→10+', '87', 'Strategic', 'RC-786', 'Management Bandwidth Split Across Too Many Geographies', '2026-08-03 03:11:35.122609+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('787', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder self-worth is derived from the work they produce — writing code, closing deals, designing features. Shifting to leadership feels like becoming less valuable.', '["all"]', 'external', 'Stage 1→10+', '88', 'Psychological', 'RC-787', 'Value Identity Tied to Technical or Operational Contribution', '2026-08-03 03:12:16.6101+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('788', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder has never seen or learned how to make the shift from operator to CEO. They have no framework for what their new role should look like.', '["all"]', 'external', 'Stage 1→10+', '88', 'Knowledge', 'RC-788', 'No Role Model or Blueprint for the Transition', '2026-08-03 03:12:16.659673+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('789', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Execution produces immediate, visible results. Leadership produces results months later through others. The gratification gap makes doing feel more productive even when it is not.', '["all"]', 'external', 'Stage 1→10+', '88', 'Psychological', 'RC-789', 'Immediate Gratification of Doing vs Delayed Returns of Leading', '2026-08-03 03:11:31.262101+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('790', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Previous experiences where delegated work went wrong reinforced the belief that the founder must do things themselves. Each failure makes the next delegation attempt less likely.', '["all"]', 'external', 'Stage 1→10+', '89', 'Psychological', 'RC-790', 'Past Delegation Failures Reinforced Trust Deficit', '2026-08-03 03:12:16.707606+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('791', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder delegates but never clearly communicates the standard they expect. When the output does not match their internal standard, they conclude delegation failed — rather than that communication failed.', '["all"]', 'external', 'Stage 1→10+', '89', 'Operational', 'RC-791', 'Standard Never Made Explicit Before Delegation', '2026-08-03 03:11:34.983186+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('792', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Unconsciously, the founder fears that if the team succeeds without their direct involvement, they become redundant. Staying involved protects their sense of necessity.', '["all"]', 'external', 'Stage 1→10+', '89', 'Psychological', 'RC-792', 'Fear of Losing Relevance Through Delegation', '2026-08-03 03:11:35.034401+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('793', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder has only managed people junior to themselves. Managing experienced executives requires different skills — listening, challenging, creating space — that were never developed.', '["all"]', 'external', 'Stage 1→10+', '90', 'Knowledge', 'RC-793', 'No Prior Experience Managing People More Senior', '2026-08-03 03:11:35.169211+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('794', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The extent of an executive independent authority was never explicitly agreed. Both parties operate on different assumptions, creating friction when decisions are made.', '["all"]', 'external', 'Stage 1→10+', '90', 'Operational', 'RC-794', 'Executive Autonomy Not Clearly Defined Upfront', '2026-08-03 03:11:28.153674+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('795', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Under pressure, the founder takes back executive-level tasks rather than coaching the executive through the challenge. This undermines the executive and prevents their development.', '["all"]', 'external', 'Stage 1→10+', '90', 'Behavioural', 'RC-795', 'Founder Reverting to Execution in Executive Domain', '2026-08-03 03:11:35.078416+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('796', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder has never operated with a formal board. The discipline of board pack preparation, structured reporting, and governance communication is entirely new.', '["all"]', 'external', 'Stage 1→10+', '91', 'Knowledge', 'RC-796', 'No Experience Preparing for or Running Board Meetings', '2026-08-03 03:12:16.756487+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('797', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder feels pressure to present positively to the board. Bad news is minimised or withheld, depriving the board of the context they need to provide useful guidance.', '["all"]', 'external', 'Stage 1→10+', '91', 'Psychological', 'RC-797', 'Difficult Information Withheld from Board', '2026-08-03 03:12:16.853762+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('798', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder experiences board oversight as threatening rather than supportive. This adversarial dynamic prevents the relationship from becoming genuinely useful.', '["all"]', 'external', 'Stage 1→10+', '91', 'Psychological', 'RC-798', 'Board Relationship Treated as Adversarial Rather Than Advisory', '2026-08-03 03:11:31.309196+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('799', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Investor updates are sent ad-hoc, usually after positive events. No consistent cadence of proactive communication was established, creating anxiety when updates stop.', '["all"]', 'external', 'Stage 1→10+', '92', 'Operational', 'RC-799', 'No Structured Investor Communication Cadence', '2026-08-03 03:12:16.90098+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('800', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Investors lack the operational context to interpret events accurately. Without regular, proactive communication, they fill gaps with assumptions — usually negative.', '["all"]', 'external', 'Stage 1→10+', '92', 'Operational', 'RC-800', 'Information Asymmetry Between Founder and Investors', '2026-08-03 03:12:16.80567+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('801', '0.72', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder did not anticipate how much time managing a growing investor base would require. Time spent on investor relations displaces time building the business.', '["all"]', 'external', 'Stage 1→10+', '92', 'Behavioural', 'RC-801', 'Founder Underestimating Time Cost of Investor Management', '2026-08-03 03:11:35.220106+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('802', '0.80', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder calendar is entirely reactive. Without protected time for strategic thinking, long-term direction gets defined by default rather than by design.', '["all"]', 'external', 'Stage 1→10+', '93', 'Operational', 'RC-802', 'No Protected Strategic Thinking Time in Founder Calendar', '2026-08-03 03:11:40.388994+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('803', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Urgent tasks trigger a stress response that makes them feel more important than they are. Strategic thinking, which has no immediate deadline, is continuously deprioritised.', '["all"]', 'external', 'Stage 1→10+', '93', 'Psychological', 'RC-803', 'Operational Urgency Consistently Wins Over Strategic Importance', '2026-08-03 03:11:35.268465+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('804', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Even where strategic thinking occurs, it is not documented or communicated across the organisation. The team cannot execute a strategy they have never seen.', '["all"]', 'external', 'Stage 1→10+', '93', 'Operational', 'RC-804', 'Strategy Not Documented or Widely Communicated', '2026-08-03 03:11:35.313862+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('805', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The founder believes that adding process will slow down creative thinking. This false dichotomy prevents the organisation from building the structure needed for quality without sacrificing agility.', '["all"]', 'external', 'Stage 1→10+', '94', 'Psychological', 'RC-805', 'Structure Seen as Enemy of Innovation', '2026-08-03 03:11:35.361019+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('806', '0.75', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'The company never built a model for managing core business operations and innovation simultaneously. Resources allocated to either/or rather than to both in parallel.', '["all"]', 'external', 'Stage 1→10+', '94', 'Strategic', 'RC-806', 'No Ambidextrous Operating Model Designed', '2026-08-03 03:12:16.950432+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('807', '0.78', '2026-07-10 14:16:03.417981+00', '1536', 'text-embedding-3-small', 'v2', 'Innovation produces new products and features that are launched without the operational infrastructure — support, documentation, monitoring — needed to sustain them reliably.', '["all"]', 'external', 'Stage 1→10+', '94', 'Operational', 'RC-807', 'New Capabilities Launched Without Operational Support', '2026-08-03 03:11:31.362974+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('808', '0.72', '2026-07-25 14:26:46.300271+00', '1536', 'text-embedding-3-small', 'v2', 'The founder has never been in circles where credible co-founders are met, so the search never realistically starts.', '["all"]', 'external', 'Stage 0', '22', 'Operational', 'RC-808', 'No Access to Founder Networks', '2026-08-03 03:11:26.826565+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('809', '0.76', '2026-07-25 14:26:46.300271+00', '1536', 'text-embedding-3-small', 'v2', 'Reluctance to give up meaningful ownership rules out the calibre of co-founder worth having.', '["all"]', 'external', 'Stage 0', '22', 'Behavioural', 'RC-809', 'Unwilling to Share Equity', '2026-08-03 03:11:26.877184+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('810', '0.75', '2026-07-25 14:26:46.300271+00', '1536', 'text-embedding-3-small', 'v2', 'A belief that nobody will care about the idea as much as they do keeps the founder working alone by choice.', '["all"]', 'external', 'Stage 0', '22', 'Psychological', 'RC-810', 'Difficulty Trusting Others With the Vision', '2026-08-03 03:11:26.923009+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('811', '0.78', '2026-07-25 14:26:46.300271+00', '1536', 'text-embedding-3-small', 'v2', 'The founder covers functions they are not equipped for, so weak areas stay permanently weak.', '["all"]', 'external', 'Stage 0→1', '22', 'Operational', 'RC-811', 'Critical Skill Gaps Left Unfilled', '2026-08-03 03:11:28.392904+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('812', '0.77', '2026-07-25 14:26:46.300271+00', '1536', 'text-embedding-3-small', 'v2', 'With no peer to pressure-test choices, poor decisions travel a long way before anyone questions them.', '["all"]', 'external', 'Stage 0→1', '22', 'Strategic', 'RC-812', 'Decisions Made Without Challenge', '2026-08-03 03:11:28.444905+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('813', '0.78', '2026-07-25 14:26:46.300271+00', '1536', 'text-embedding-3-small', 'v2', 'Every function competes for one person''s hours, so growth stalls at whatever one person can personally carry.', '["all"]', 'external', 'Stage 0→1', '22', 'Operational', 'RC-813', 'Founder Bandwidth Ceiling', '2026-08-03 03:11:28.495391+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('814', '0.74', '2026-07-25 14:26:46.300271+00', '1536', 'text-embedding-3-small', 'v2', 'The emotional load of the business is carried alone, which distorts judgement during hard periods.', '["all"]', 'external', 'Stage 0→1', '22', 'Psychological', 'RC-814', 'Isolation With No Sounding Board', '2026-08-03 03:11:28.545776+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('815', '0.73', '2026-07-25 14:26:46.300271+00', '1536', 'text-embedding-3-small', 'v2', 'A painful earlier partnership makes the founder avoid ever sharing control again, regardless of current need.', '["all"]', 'external', 'Stage 0→1', '22', 'Psychological', 'RC-815', 'Previous Co-founder Fallout', '2026-08-03 03:11:28.598047+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('816', '0.77', '2026-07-25 14:28:19.652936+00', '1536', 'text-embedding-3-small', 'v2', 'No one outside the company reviews major decisions, so there is no independent check on the founder''s judgement.', '["all"]', 'external', 'Stage 0→1', '24', 'Operational', 'RC-816', 'No Board or Advisory Structure', '2026-08-03 03:11:27.019755+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('817', '0.78', '2026-07-25 14:28:19.652936+00', '1536', 'text-embedding-3-small', 'v2', 'Every approval routes through one person, so oversight depends entirely on that person choosing to seek it.', '["all"]', 'external', 'Stage 1→10+', '24', 'Behavioural', 'RC-817', 'All Decision Rights Held by the Founder', '2026-08-03 03:11:27.069497+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('818', '0.78', '2026-07-25 14:28:19.652936+00', '1536', 'text-embedding-3-small', 'v2', 'Nobody knows who is allowed to approve what, so decisions get made ad hoc by whoever is closest to the issue.', '["all"]', 'external', 'Stage 0→1', '24', 'Operational', 'RC-818', 'Decision Rights Never Defined', '2026-08-03 03:11:27.116771+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('819', '0.75', '2026-07-25 14:28:19.652936+00', '1536', 'text-embedding-3-small', 'v2', 'Oversight is seen as red tape that slows a startup down, so it is deliberately skipped in favour of speed.', '["all"]', 'external', 'Stage 0→1', '24', 'Behavioural', 'RC-819', 'Governance Treated as Bureaucracy', '2026-08-03 03:11:28.644349+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('820', '0.76', '2026-07-25 14:28:19.652936+00', '1536', 'text-embedding-3-small', 'v2', 'Nothing is written down, so consistency depends on memory and whoever happens to be asked.', '["all"]', 'external', 'Stage 0→1', '24', 'Operational', 'RC-820', 'No Documented Policies or Approval Limits', '2026-08-03 03:11:28.690432+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('821', '0.79', '2026-07-25 14:28:19.652936+00', '1536', 'text-embedding-3-small', 'v2', 'Money moves without approval thresholds or separation of duties, so errors and misuse go undetected.', '["all"]', 'external', 'Stage 1→10+', '24', 'Operational', 'RC-821', 'Financial Controls Never Established', '2026-08-03 03:11:28.741896+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('822', '0.74', '2026-07-25 14:28:19.652936+00', '1536', 'text-embedding-3-small', 'v2', 'Updates are irregular and reactive, so problems surface to stakeholders far later than they should.', '["all"]', 'external', 'Stage 1→10+', '24', 'Strategic', 'RC-822', 'Investor and Stakeholder Reporting Treated as Optional', '2026-08-03 03:11:28.788232+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('823', '0.73', '2026-07-25 14:28:19.652936+00', '1536', 'text-embedding-3-small', 'v2', 'Related-party dealings and personal relationships are never declared, creating risk nobody is tracking.', '["all"]', 'external', 'Stage 1→10+', '24', 'Strategic', 'RC-823', 'Conflicts of Interest Left Unmanaged', '2026-08-03 03:11:28.342741+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('824', '0.74', '2026-07-25 14:29:07.560307+00', '1536', 'text-embedding-3-small', 'v2', 'The round is optimised for the headline number rather than the right amount from the right investor.', '["all"]', 'external', 'Stage 0→1', '27', 'Strategic', 'RC-824', 'Valuation Chased Over Fit', '2026-08-03 03:11:27.225122+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('825', '0.80', '2026-07-25 14:29:07.560307+00', '1536', 'text-embedding-3-small', 'v2', 'Money arrives before the model is validated, so it funds guessing at scale instead of learning cheaply.', '["all"]', 'external', 'Stage 0→1', '27', 'Strategic', 'RC-825', 'Capital Raised Before Product-Market Fit Is Proven', '2026-08-03 03:11:27.271892+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('826', '0.75', '2026-07-25 14:29:07.560307+00', '1536', 'text-embedding-3-small', 'v2', 'Closing a round is celebrated as success in itself, which hides the fact that nothing has been proven yet.', '["all"]', 'external', 'Stage 0→1', '27', 'Behavioural', 'RC-826', 'Fundraising Treated as the Milestone', '2026-08-03 03:11:27.318365+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('827', '0.79', '2026-07-25 14:29:07.560307+00', '1536', 'text-embedding-3-small', 'v2', 'A full bank account removes the constraint that was forcing sharp decisions, and standards quietly drop.', '["all"]', 'external', 'Stage 0→1', '27', 'Behavioural', 'RC-827', 'Spending Discipline Erodes With a Large Balance', '2026-08-03 03:11:28.976327+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('828', '0.80', '2026-07-25 14:29:07.560307+00', '1536', 'text-embedding-3-small', 'v2', 'Headcount and commitments grow ahead of revenue simply because the cash allows it, not because demand requires it.', '["all"]', 'external', 'Stage 1→10+', '27', 'Operational', 'RC-828', 'Premature Scaling of Team and Fixed Costs', '2026-08-03 03:11:29.023905+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('829', '0.77', '2026-07-25 14:29:07.560307+00', '1536', 'text-embedding-3-small', 'v2', 'Too much equity is given away before the business is worth much, which constrains every future round.', '["all"]', 'external', 'Stage 0→1', '27', 'Strategic', 'RC-829', 'Excessive Dilution Before Value Inflection', '2026-08-03 03:11:29.072777+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('830', '0.76', '2026-07-25 14:29:07.560307+00', '1536', 'text-embedding-3-small', 'v2', 'The raise sets growth expectations the business has no realistic path to meeting in the time available.', '["all"]', 'external', 'Stage 1→10+', '27', 'Strategic', 'RC-830', 'Unrealistic Milestones Attached to the Round', '2026-08-03 03:11:28.832324+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('831', '0.74', '2026-07-25 14:29:07.560307+00', '1536', 'text-embedding-3-small', 'v2', 'A large cheque brings demands for a speed and scale of growth the founder never actually intended to pursue.', '["all"]', 'external', 'Stage 1→10+', '27', 'Strategic', 'RC-831', 'Investor Expectations Misaligned With Founder Pace', '2026-08-03 03:11:29.169959+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('832', '0.81', '2026-07-25 14:32:26.366765+00', '1536', 'text-embedding-3-small', 'v2', 'The raise is planned as a six to eight week exercise when it realistically takes four to six months, so the runway maths was wrong from day one.', '["all"]', 'external', 'Stage 0→1', '32', 'Strategic', 'RC-832', 'Fundraise Timeline Underestimated', '2026-08-03 03:11:27.429903+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('833', '0.79', '2026-07-25 14:32:26.366765+00', '1536', 'text-embedding-3-small', 'v2', 'The process begins when runway is already short, which removes any ability to walk away from a bad offer.', '["all"]', 'external', 'Stage 0→1', '32', 'Strategic', 'RC-833', 'Fundraising Started Too Late', '2026-08-03 03:11:27.478057+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('834', '0.78', '2026-07-25 14:32:26.366765+00', '1536', 'text-embedding-3-small', 'v2', 'The founder disappears into investor meetings and the business stalls, so the metrics being pitched start declining mid-process.', '["all"]', 'external', 'Stage 0→1', '32', 'Operational', 'RC-834', 'Founder Attention Fully Diverted to Raising', '2026-08-03 03:11:27.525137+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('835', '0.80', '2026-07-25 14:32:26.366765+00', '1536', 'text-embedding-3-small', 'v2', 'Burn is never cut when the raise starts because the money is assumed to be arriving, so every week of delay costs full price.', '["all"]', 'external', 'Stage 0→1', '32', 'Behavioural', 'RC-835', 'Spending Continued at Pre-Raise Burn Rate', '2026-08-03 03:11:29.216416+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('836', '0.79', '2026-07-25 14:32:26.366765+00', '1536', 'text-embedding-3-small', 'v2', 'There is no plan B if the round slips or falls through, so a delay becomes an emergency rather than an inconvenience.', '["all"]', 'external', 'Stage 1→10+', '32', 'Strategic', 'RC-836', 'No Bridge or Fallback Financing Plan', '2026-08-03 03:11:29.262961+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('837', '0.75', '2026-07-25 14:32:26.366765+00', '1536', 'text-embedding-3-small', 'v2', 'Spend is pushed up to show traction during the process, accelerating burn at exactly the moment cash is tightest.', '["all"]', 'external', 'Stage 1→10+', '32', 'Behavioural', 'RC-837', 'Growth Spending Increased to Look Attractive in Diligence', '2026-08-03 03:11:29.120733+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('838', '0.80', '2026-07-25 14:32:26.366765+00', '1536', 'text-embedding-3-small', 'v2', 'The founder has no accurate live runway figure, so the danger point is discovered late rather than anticipated.', '["all"]', 'external', 'Stage 0→1', '32', 'Operational', 'RC-838', 'Weak Cash Flow Visibility', '2026-08-03 03:11:16.311756+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('839', '0.77', '2026-07-25 14:32:26.366765+00', '1536', 'text-embedding-3-small', 'v2', 'As cash drains, terms that would have been refused become acceptable, and the round closes worse than it should have.', '["all"]', 'external', 'Stage 1→10+', '32', 'Strategic', 'RC-839', 'Shrinking Runway Weakens Negotiating Position', '2026-08-03 03:11:29.356087+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('840', '0.77', '2026-07-25 14:33:13.377633+00', '1536', 'text-embedding-3-small', 'v2', 'A short-term cash need overrides product judgement, so decisions get made for this quarter rather than for the user.', '["all"]', 'external', 'Stage 0→1', '38', 'Strategic', 'RC-840', 'Revenue Pressure From Runway or Investors', '2026-08-03 03:11:27.616622+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('841', '0.80', '2026-07-25 14:33:13.377633+00', '1536', 'text-embedding-3-small', 'v2', 'Charging begins before users reliably get value, so the product asks for money it has not yet earned.', '["all"]', 'external', 'Stage 0→1', '38', 'Strategic', 'RC-841', 'Monetisation Added Before Value Is Proven', '2026-08-03 03:11:27.669336+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('842', '0.79', '2026-07-25 14:33:13.377633+00', '1536', 'text-embedding-3-small', 'v2', 'The exact thing users came for is locked behind payment, so the product stops delivering on its own promise.', '["all"]', 'external', 'Stage 0→1', '38', 'Strategic', 'RC-842', 'Paywall Placed on the Core Value', '2026-08-03 03:11:27.715767+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('843', '0.78', '2026-07-25 14:33:13.377633+00', '1536', 'text-embedding-3-small', 'v2', 'The team optimises for this month''s revenue over retention, and the damage only shows up a few months later.', '["all"]', 'external', 'Stage 1→10+', '38', 'Behavioural', 'RC-843', 'Short-Term Metrics Drive Product Decisions', '2026-08-03 03:11:29.403901+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('844', '0.76', '2026-07-25 14:33:13.377633+00', '1536', 'text-embedding-3-small', 'v2', 'Nobody in the room represents the user when pricing and packaging are decided, so the trade-off is never argued.', '["all"]', 'external', 'Stage 0→1', '38', 'Operational', 'RC-844', 'No Voice of the Customer in Monetisation Decisions', '2026-08-03 03:11:29.451125+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('845', '0.75', '2026-07-25 14:33:13.377633+00', '1536', 'text-embedding-3-small', 'v2', 'The product becomes noisier and harder to use as more revenue surfaces are added on top of it.', '["all"]', 'external', 'Stage 1→10+', '38', 'Operational', 'RC-845', 'Aggressive Ads and Upsells Degrade the Experience', '2026-08-03 03:11:28.878077+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('846', '0.79', '2026-07-25 14:33:13.377633+00', '1536', 'text-embedding-3-small', 'v2', 'Users leaving is explained away as the wrong segment rather than treated as direct feedback on the change.', '["all"]', 'external', 'Stage 1→10+', '38', 'Behavioural', 'RC-846', 'Churn Signals Ignored or Rationalised', '2026-08-03 03:11:29.542673+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('847', '0.76', '2026-07-25 14:33:13.377633+00', '1536', 'text-embedding-3-small', 'v2', 'Price and packaging are guessed rather than researched, so the model lands badly and gets patched with more monetisation.', '["all"]', 'external', 'Stage 0→1', '38', 'Knowledge', 'RC-847', 'Pricing Set Without Understanding Willingness to Pay', '2026-08-03 03:11:29.589335+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('848', '0.80', '2026-07-25 14:33:57.753933+00', '1536', 'text-embedding-3-small', 'v2', 'Nobody checked whether buyers are actually ready to adopt this yet, so the product arrives into a market that is not looking for it.', '["all"]', 'external', 'Stage 0→1', '39', 'Strategic', 'RC-848', 'Market Readiness Never Assessed', '2026-08-03 03:11:27.812905+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('849', '0.78', '2026-07-25 14:33:57.753933+00', '1536', 'text-embedding-3-small', 'v2', 'The product depends on adoption, technology or regulation that has not arrived yet, so it works but nobody can use it properly.', '["all"]', 'external', 'Stage 0→1', '39', 'Strategic', 'RC-849', 'Building Ahead of Enabling Infrastructure', '2026-08-03 03:11:27.859907+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('850', '0.77', '2026-07-25 14:33:57.753933+00', '1536', 'text-embedding-3-small', 'v2', 'Competitors have already defined the category and captured the early buyers by the time launch happens.', '["all"]', 'external', 'Stage 0→1', '39', 'Strategic', 'RC-850', 'Launched Too Late Into an Already Crowded Market', '2026-08-03 03:11:27.90876+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('851', '0.79', '2026-07-25 14:33:57.753933+00', '1536', 'text-embedding-3-small', 'v2', 'The team builds for months without re-checking whether the window is still open, so the plan is validated against an old market.', '["all"]', 'external', 'Stage 0→1', '39', 'Operational', 'RC-851', 'Long Build Cycle Detached From Market Signals', '2026-08-03 03:11:29.733332+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('852', '0.76', '2026-07-25 14:33:57.753933+00', '1536', 'text-embedding-3-small', 'v2', 'A temporary spike in interest is read as a lasting market, and the product is built for a wave that has already passed.', '["all"]', 'external', 'Stage 0→1', '39', 'Knowledge', 'RC-852', 'Trend Mistaken for Durable Demand', '2026-08-03 03:11:29.780001+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('853', '0.74', '2026-07-25 14:33:57.753933+00', '1536', 'text-embedding-3-small', 'v2', 'The offer arrives at a point in the year when buyers have no budget allocated, so genuine interest cannot convert.', '["all"]', 'external', 'Stage 1→10+', '39', 'Knowledge', 'RC-853', 'Customer Budget Cycles Ignored', '2026-08-03 03:11:29.825472+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('854', '0.75', '2026-07-25 14:33:57.753933+00', '1536', 'text-embedding-3-small', 'v2', 'A rule change quietly opens or closes the window and nobody was tracking it closely enough to react in time.', '["all"]', 'external', 'Stage 1→10+', '39', 'Strategic', 'RC-854', 'Regulatory or Policy Shift Not Anticipated', '2026-08-03 03:11:29.308944+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('855', '0.79', '2026-07-25 14:33:57.753933+00', '1536', 'text-embedding-3-small', 'v2', 'The date is set by when the team finishes building, not by when buyers are ready to buy.', '["all"]', 'external', 'Stage 0→1', '39', 'Behavioural', 'RC-855', 'Launch Timed Around Internal Readiness Rather Than Market Demand', '2026-08-03 03:11:29.919355+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('856', '0.81', '2026-07-25 14:34:46.017324+00', '1536', 'text-embedding-3-small', 'v2', 'Money moves between the founder and the company without a clean boundary, so no figure the business produces can be trusted.', '["all"]', 'external', 'Stage 0', '43', 'Operational', 'RC-856', 'No Separation Between Personal and Business Finances', '2026-08-03 03:11:28.006387+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('857', '0.79', '2026-07-25 14:34:46.017324+00', '1536', 'text-embedding-3-small', 'v2', 'Books are only brought up to date at filing time, so the founder is always looking at a picture several months old.', '["all"]', 'external', 'Stage 0→1', '43', 'Operational', 'RC-857', 'Bookkeeping Done Retrospectively', '2026-08-03 03:11:28.054885+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('858', '0.80', '2026-07-25 14:34:46.017324+00', '1536', 'text-embedding-3-small', 'v2', 'Records live in scattered spreadsheets or nowhere at all, so there is no single reliable ledger to work from.', '["all"]', 'external', 'Stage 0→1', '43', 'Operational', 'RC-858', 'No Proper Accounting System in Place', '2026-08-03 03:11:28.101635+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('859', '0.78', '2026-07-25 14:34:46.017324+00', '1536', 'text-embedding-3-small', 'v2', 'The numbers exist only to satisfy the tax filing, so they are never actually used to make a business decision.', '["all"]', 'external', 'Stage 0→1', '43', 'Behavioural', 'RC-859', 'Finance Treated as a Compliance Chore Rather Than a Decision Tool', '2026-08-03 03:11:29.964486+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('860', '0.80', '2026-07-25 14:34:46.017324+00', '1536', 'text-embedding-3-small', 'v2', 'Nobody looks at the numbers on a fixed cadence, so problems are discovered by accident rather than by review.', '["all"]', 'external', 'Stage 0→1', '43', 'Operational', 'RC-860', 'No Regular Financial Review Rhythm', '2026-08-03 03:11:30.015504+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('861', '0.78', '2026-07-25 14:34:46.017324+00', '1536', 'text-embedding-3-small', 'v2', 'Money already earned goes uncollected because no one is systematically chasing what is owed.', '["all"]', 'external', 'Stage 0→1', '43', 'Operational', 'RC-861', 'Invoicing and Collections Not Tracked', '2026-08-03 03:11:28.925719+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('862', '0.79', '2026-07-25 14:34:46.017324+00', '1536', 'text-embedding-3-small', 'v2', 'Nobody is accountable for the numbers, so financial work only happens when someone happens to find time for it.', '["all"]', 'external', 'Stage 1→10+', '43', 'Operational', 'RC-862', 'No Finance Owner Appointed', '2026-08-03 03:11:30.108729+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('863', '0.77', '2026-07-25 14:34:46.017324+00', '1536', 'text-embedding-3-small', 'v2', 'The founder lacks the literacy to interpret their own P&L and cash position, so warning signs pass unnoticed.', '["all"]', 'external', 'Stage 0→1', '43', 'Knowledge', 'RC-863', 'Founder Cannot Read Their Own Financial Statements', '2026-08-03 03:11:30.155561+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('864', '0.78', '2026-07-25 14:36:11.20662+00', '1536', 'text-embedding-3-small', 'v2', 'Regulatory work is postponed as something to sort out once the business is bigger, so obligations quietly accumulate.', '["all"]', 'external', 'Stage 0→1', '45', 'Behavioural', 'RC-864', 'Compliance Treated as a Later-Stage Concern', '2026-08-03 03:11:28.200442+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('865', '0.80', '2026-07-25 14:36:11.20662+00', '1536', 'text-embedding-3-small', 'v2', 'Nothing tracks what is due and when, so deadlines are missed by oversight rather than by decision.', '["all"]', 'external', 'Stage 0→1', '45', 'Operational', 'RC-865', 'No Compliance Calendar or Filing Tracker', '2026-08-03 03:11:28.246699+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('866', '0.80', '2026-07-25 14:36:11.20662+00', '1536', 'text-embedding-3-small', 'v2', 'The business operates without permissions it legally requires, which caps what it can safely do and who it can sell to.', '["all"]', 'external', 'Stage 0→1', '45', 'Operational', 'RC-866', 'Registrations and Licences Left Incomplete', '2026-08-03 03:11:28.296167+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('867', '0.79', '2026-07-25 14:36:11.20662+00', '1536', 'text-embedding-3-small', 'v2', 'With no accountant, company secretary or lawyer involved, obligations are unknown rather than deliberately ignored.', '["all"]', 'external', 'Stage 0→1', '45', 'Knowledge', 'RC-867', 'No Professional Advisor Engaged', '2026-08-03 03:11:30.291281+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('868', '0.78', '2026-07-25 14:36:11.20662+00', '1536', 'text-embedding-3-small', 'v2', 'Work proceeds on verbal understanding, so there is no enforceable position when something goes wrong.', '["all"]', 'external', 'Stage 0→1', '45', 'Operational', 'RC-868', 'Contracts and Agreements Left Informal', '2026-08-03 03:11:30.338182+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('869', '0.77', '2026-07-25 14:36:11.20662+00', '1536', 'text-embedding-3-small', 'v2', 'Provident fund, insurance, payroll tax and labour registrations are skipped, creating liability that grows with every hire.', '["all"]', 'external', 'Stage 1→10+', '45', 'Operational', 'RC-869', 'Employee Statutory Obligations Not Met', '2026-08-03 03:11:30.383676+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('870', '0.76', '2026-07-25 14:36:11.20662+00', '1536', 'text-embedding-3-small', 'v2', 'Customer data is collected and stored without consent, retention or protection rules, which becomes a serious exposure at scale.', '["all"]', 'external', 'Stage 1→10+', '45', 'Strategic', 'RC-870', 'Data and Privacy Obligations Unaddressed', '2026-08-03 03:11:29.496383+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('871', '0.75', '2026-07-25 14:36:11.20662+00', '1536', 'text-embedding-3-small', 'v2', 'Fines are paid and normalised instead of triggering a fix, so the underlying gap is never actually closed.', '["all"]', 'external', 'Stage 1→10+', '45', 'Behavioural', 'RC-871', 'Penalties Absorbed as a Cost of Doing Business', '2026-08-03 03:11:30.475206+00') on conflict do nothing;
