insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('879', '0.77', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Surrounding narratives celebrate grinding through pain, which frames rest or support as a lack of commitment.', '["all"]', 'internal', 'Stage 0→1', '97', 'Psychological', 'RC-879', 'Founder Culture Glorifies Suffering', '2026-08-03 03:11:26.734389+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('880', '0.78', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Any admission feels like it could travel to people who control funding, so difficulty is concealed rather than addressed.', '["all"]', 'internal', 'Stage 1→10+', '97', 'Psychological', 'RC-880', 'Fear That Struggling Will Reach Investors', '2026-08-03 03:11:19.812254+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('881', '0.75', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Nobody in the founder circle has openly done this, so there is no example making it feel normal or safe.', '["all"]', 'internal', 'Stage 0→1', '97', 'Knowledge', 'RC-881', 'No Visible Peers Who Have Sought Support', '2026-08-03 03:11:26.779366+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('882', '0.74', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Support is dismissed as unaffordable or too time-consuming before it is ever actually priced or tried.', '["all"]', 'internal', 'Stage 0→1', '97', 'Behavioural', 'RC-882', 'Cost and Time Treated as Disqualifying', '2026-08-03 03:11:27.5707+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('883', '0.76', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'The founder immediate environment treats these conversations as shameful or unnecessary, reinforcing avoidance.', '["all"]', 'internal', 'Stage 0', '97', 'Psychological', 'RC-883', 'Family or Cultural Discouragement', '2026-08-03 03:11:27.958863+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('884', '0.80', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Never knowing whether the business survives the next quarter keeps the founder in a permanent state of alertness.', '["all"]', 'internal', 'Stage 0→1', '98', 'Psychological', 'RC-884', 'Constant Existential Uncertainty', '2026-08-03 03:11:35.408213+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('885', '0.79', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'A shrinking cash position makes every decision feel urgent, which crowds out considered judgement.', '["all"]', 'internal', 'Stage 0→1', '98', 'Psychological', 'RC-885', 'Runway Anxiety Driving Short-Term Reactions', '2026-08-03 03:11:34.363331+00') on conflict do nothing;
