insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('887', '0.77', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Work has no closing time, so the nervous system never gets the signal that the day is over.', '["all"]', 'internal', 'Stage 0→1', '98', 'Behavioural', 'RC-887', 'No Separation Between Work and Rest Hours', '2026-08-03 03:11:35.649658+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('888', '0.78', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'A single lost customer or bad meeting is read as evidence the whole business is failing.', '["all"]', 'internal', 'Stage 0→1', '98', 'Psychological', 'RC-888', 'Catastrophising Small Setbacks', '2026-08-03 03:11:35.509252+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('889', '0.74', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Caffeine or similar props are used to maintain performance, which amplifies the underlying agitation.', '["all"]', 'internal', 'Stage 0→1', '98', 'Behavioural', 'RC-889', 'Stimulants Used to Sustain Output', '2026-08-03 03:11:35.695669+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('890', '0.80', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Rest is framed as a cost rather than an input, so it is always the first thing cut.', '["all"]', 'internal', 'Stage 0→1', '100', 'Behavioural', 'RC-890', 'Recovery Seen as Time Stolen From the Business', '2026-08-03 03:11:35.555201+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('891', '0.77', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'The founder has never identified what actually recharges them, so recovery attempts are random and ineffective.', '["all"]', 'internal', 'Stage 0→1', '100', 'Behavioural', 'RC-891', 'No Practice That Reliably Restores Energy', '2026-08-03 03:11:17.477287+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('892', '0.79', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Nothing is done until things become unbearable, so recovery is always crisis response rather than maintenance.', '["all"]', 'internal', 'Stage 0→1', '100', 'Behavioural', 'RC-892', 'Coping Handled Only Reactively at Breaking Point', '2026-08-03 03:11:35.601381+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('893', '0.78', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Everything outside the business has been dropped, removing the sources of perspective and identity that buffer stress.', '["all"]', 'internal', 'Stage 0→1', '100', 'Behavioural', 'RC-893', 'Hobbies and Relationships Fully Displaced by Work', '2026-08-03 03:11:35.742298+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('894', '0.78', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Any non-work time produces guilt, so even attempted rest does not actually restore anything.', '["all"]', 'internal', 'Stage 0→1', '100', 'Psychological', 'RC-894', 'Guilt When Not Working', '2026-08-03 03:11:35.834688+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('895', '0.79', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Nothing runs without the founder, so genuine time off is not just unchosen but practically impossible.', '["all"]', 'internal', 'Stage 1→10+', '100', 'Operational', 'RC-895', 'No Structural Permission to Step Away', '2026-08-03 03:11:35.787118+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('896', '0.79', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Responses are issued immediately under pressure, before the founder has processed what actually happened.', '["all"]', 'internal', 'Stage 1→10+', '120', 'Behavioural', 'RC-896', 'Reacting in the Moment Rather Than Pausing', '2026-08-03 03:11:35.879957+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('897', '0.78', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'The founder cannot name what reliably sets them off, so the same situations produce the same reaction each time.', '["all"]', 'internal', 'Stage 0→1', '120', 'Knowledge', 'RC-897', 'No Awareness of Personal Trigger Patterns', '2026-08-03 03:11:36.037076+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('898', '0.79', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Pressure from outside the company is discharged onto whoever is nearest, usually the people least responsible for it.', '["all"]', 'internal', 'Stage 1→10+', '120', 'Behavioural', 'RC-898', 'Frustration Directed at the Team', '2026-08-03 03:11:17.528355+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('899', '0.76', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Feelings are pushed down rather than processed, which works until it fails suddenly and visibly.', '["all"]', 'internal', 'Stage 0→1', '120', 'Psychological', 'RC-899', 'Emotional Control Equated With Suppression', '2026-08-03 03:11:36.084366+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('900', '0.78', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Chronic tiredness removes the small buffer that normally sits between feeling something and acting on it.', '["all"]', 'internal', 'Stage 0→1', '120', 'Behavioural', 'RC-900', 'Fatigue Eroding Impulse Control', '2026-08-03 03:11:35.943303+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('901', '0.77', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Nobody tells the founder how their reactions land, so the pattern continues uncorrected for years.', '["all"]', 'internal', 'Stage 1→10+', '120', 'Operational', 'RC-901', 'No Feedback Loop on Own Behaviour', '2026-08-03 03:11:36.13453+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('902', '0.78', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Nobody nearby understands the specific pressures, so problems get explained rather than understood.', '["all"]', 'internal', 'Stage 0→1', '124', 'Operational', 'RC-902', 'No Peer Founders in the Immediate Circle', '2026-08-03 03:11:36.182862+00') on conflict do nothing;
