insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('906', '0.75', '2026-07-25 15:22:07.624059+00', '1536', 'text-embedding-3-small', 'v2', 'Founder communities are used for opportunity rather than support, because asking feels like taking.', '["all"]', 'internal', 'Stage 0→1', '124', 'Psychological', 'RC-906', 'Reluctance to Appear Needy in Networks', '2026-08-03 03:11:36.275926+00') on conflict do nothing;
