insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('951', '0.79', '2026-07-25 15:23:26.210576+00', '1536', 'text-embedding-3-small', 'v2', 'What has already been built shapes what is considered possible next, so the pivot is judged against the wrong baseline.', '["all"]', 'internal', 'Stage 0→1', '109', 'Psychological', 'RC-951', 'Sunk Build Effort Anchoring the Product', '2026-08-03 03:11:38.154147+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('952', '0.78', '2026-07-25 15:23:26.210576+00', '1536', 'text-embedding-3-small', 'v2', 'A small set of current users is treated as binding, even when they are not the market the business needs.', '["all"]', 'internal', 'Stage 0→1', '109', 'Strategic', 'RC-952', 'Existing Customers Used as a Reason Not to Change', '2026-08-03 03:11:38.295174+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('953', '0.79', '2026-07-25 15:23:26.210576+00', '1536', 'text-embedding-3-small', 'v2', 'A change of direction is understood as losing everything rather than redeploying what was learned.', '["all"]', 'internal', 'Stage 0→1', '109', 'Psychological', 'RC-953', 'Pivot Framed as Starting Over', '2026-08-03 03:11:17.955246+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('954', '0.78', '2026-07-25 15:23:26.210576+00', '1536', 'text-embedding-3-small', 'v2', 'Changing course is assumed to read as failure externally, so the decision is delayed past the point of usefulness.', '["all"]', 'internal', 'Stage 1→10+', '109', 'Psychological', 'RC-954', 'Fear of Signalling Failure to Investors', '2026-08-03 03:11:38.339952+00') on conflict do nothing;
