insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('956', '0.78', '2026-07-25 15:23:26.210576+00', '1536', 'text-embedding-3-small', 'v2', 'Incoming evidence is fitted into the current view rather than allowed to change it.', '["all"]', 'internal', 'Stage 1→10+', '118', 'Psychological', 'RC-956', 'New Information Filtered Through Existing Conclusions', '2026-08-03 03:11:18.089781+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('957', '0.78', '2026-07-25 15:23:26.210576+00', '1536', 'text-embedding-3-small', 'v2', 'Years in the field are read as having already learned this, which closes the question prematurely.', '["all"]', 'internal', 'Stage 1→10+', '118', 'Psychological', 'RC-957', 'Experience Treated as Settled Knowledge', '2026-08-03 03:11:38.43577+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('958', '0.77', '2026-07-25 15:23:26.210576+00', '1536', 'text-embedding-3-small', 'v2', 'Suggestions to do things differently land as judgement of past decisions, so they are resisted rather than considered.', '["all"]', 'internal', 'Stage 1→10+', '118', 'Psychological', 'RC-958', 'Change Requests Interpreted as Criticism', '2026-08-03 03:11:18.135745+00') on conflict do nothing;
