insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('977', '0.79', '2026-07-25 15:24:15.793978+00', '1536', 'text-embedding-3-small', 'v2', 'The first hour is given to other people agendas, which sets a reactive tone for everything after it.', '["all"]', 'internal', 'Stage 0→1', '121', 'Behavioural', 'RC-977', 'Day Starts With Messages and Notifications', '2026-08-03 03:11:39.335629+00') on conflict do nothing;
