insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('984', '0.79', '2026-07-25 15:24:15.793978+00', '1536', 'text-embedding-3-small', 'v2', 'Dates slip routinely without comment, which teaches everyone that dates are not real.', '["all"]', 'internal', 'Stage 0→1', '113', 'Behavioural', 'RC-984', 'Deadlines Treated as Aspirations', '2026-08-03 03:11:39.62706+00') on conflict do nothing;
