insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1001', '0.68', '2026-08-03 06:11:34.594992+00', '1536', 'text-embedding-3-small', NULL, 'When discovery conversations do happen, questions are phrased to confirm the idea rather than to uncover the truth.', '["all"]', 'external', 'Stage 0', '126', 'Knowledge', 'RC-1001', 'Leading Questions in Interviews', '2026-08-03 06:14:29.665396+00') on conflict do nothing;
