insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1005', '0.65', '2026-08-03 06:11:34.594992+00', '1536', 'text-embedding-3-small', NULL, 'The persona document was written in one brainstorming session rather than updated as real evidence came in.', '["all"]', 'external', 'Stage 0', '127', 'Behavioural', 'RC-1005', 'Persona Built in a Single Sitting', '2026-08-03 06:14:29.888912+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1006', '0.70', '2026-08-03 06:11:34.594992+00', '1536', 'text-embedding-3-small', NULL, 'In B2B or multi-sided products, the founder has not distinguished who pays from who uses the product day to day.', '["all"]', 'external', 'Stage 0', '127', 'Knowledge', 'RC-1006', 'Confusing a Buyer Persona with a User Persona', '2026-08-03 06:14:29.940975+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1007', '0.68', '2026-08-03 06:11:34.594992+00', '1536', 'text-embedding-3-small', NULL, 'The founder generalises the whole market from the traits of the very first person who showed interest.', '["all"]', 'external', 'Stage 0', '127', 'Behavioural', 'RC-1007', 'Anchoring on the First Customer', '2026-08-03 06:14:29.994232+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1008', '0.62', '2026-08-03 06:11:34.594992+00', '1536', 'text-embedding-3-small', NULL, 'The persona was written once at the start and has never been revisited even though the founder has since learned more.', '["all"]', 'external', 'Stage 0', '127', 'Operational', 'RC-1008', 'No Refresh Cycle for the Persona', '2026-08-03 06:14:30.046889+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1009', '0.68', '2026-08-03 06:11:34.594992+00', '1536', 'text-embedding-3-small', NULL, 'The persona focuses on age, income, or job title but says nothing about the customer''s actual triggers, fears, or buying behaviour.', '["all"]', 'external', 'Stage 0', '127', 'Knowledge', 'RC-1009', 'Overreliance on Demographics', '2026-08-03 06:14:30.099254+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1010', '0.62', '2026-08-03 06:11:34.594992+00', '1536', 'text-embedding-3-small', NULL, 'The founder assumed a competitor''s public messaging accurately reflects who is really buying, without independent verification.', '["all"]', 'external', 'Stage 0', '127', 'Strategic', 'RC-1010', 'Copying a Competitor''s Stated Customer', '2026-08-03 06:14:30.155045+00') on conflict do nothing;
