insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1013', '0.62', '2026-08-03 06:11:34.594992+00', '1536', 'text-embedding-3-small', NULL, 'Competitor research was a one-time exercise rather than an ongoing habit, so the picture is already stale.', '["all"]', 'external', 'Stage 0→1', '128', 'Operational', 'RC-1013', 'No Repeatable Research Process', '2026-08-03 06:14:30.307394+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1014', '0.68', '2026-08-03 06:11:34.594992+00', '1536', 'text-embedding-3-small', NULL, 'Looking closely at strong competitors feels threatening to the founder''s confidence in the idea, so the research is kept shallow on purpose.', '["all"]', 'external', 'Stage 0→1', '128', 'Psychological', 'RC-1014', 'Avoidance of Discouraging Information', '2026-08-03 06:14:30.358642+00') on conflict do nothing;
