insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1016', '0.70', '2026-08-03 06:11:34.594992+00', '1536', 'text-embedding-3-small', NULL, 'The founder has not considered that the customer''s current default — doing nothing or tolerating the problem — is itself the hardest competitor to beat.', '["all"]', 'external', 'Stage 0→1', '128', 'Strategic', 'RC-1016', 'Ignoring the ''Do Nothing'' Competitor', '2026-08-03 06:14:30.465897+00') on conflict do nothing;
