insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1018', '0.68', '2026-08-03 06:11:34.594992+00', '1536', 'text-embedding-3-small', NULL, 'Price was built up from the founder''s own costs without ever comparing it to what the market already pays for alternatives.', '["all"]', 'external', 'Stage 0→1', '129', 'Knowledge', 'RC-1018', 'Cost-Plus Default Without Market Check', '2026-08-03 06:14:30.566346+00') on conflict do nothing;
