insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1047', '0.68', '2026-08-03 07:00:44.107477+00', '1536', 'text-embedding-3-small', NULL, 'The founder has not mapped out the order of activities (waitlist, soft launch, public launch, etc.) needed to bring the product to market.', '["all"]', 'external', 'Stage 0→1', '134', 'Knowledge', 'RC-1047', 'No Launch Sequence Defined', '2026-08-03 07:02:20.117601+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1048', '0.70', '2026-08-03 07:00:44.107477+00', '1536', 'text-embedding-3-small', NULL, 'No decision has been made about which channel(s) will be used to reach the first customers.', '["all"]', 'external', 'Stage 0→1', '134', 'Strategic', 'RC-1048', 'Channel Selection Never Made', '2026-08-03 07:02:20.179231+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1049', '0.68', '2026-08-03 07:00:44.107477+00', '1536', 'text-embedding-3-small', NULL, 'There is no existing list, community, or audience to activate when the product is ready.', '["all"]', 'external', 'Stage 0→1', '134', 'Operational', 'RC-1049', 'No Pre-Launch Audience Built', '2026-08-03 07:02:20.235483+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1050', '0.65', '2026-08-03 07:00:44.107477+00', '1536', 'text-embedding-3-small', NULL, 'Core positioning and messaging have not been tested with real prospects before being finalized for launch.', '["all"]', 'external', 'Stage 0→1', '134', 'Knowledge', 'RC-1050', 'Messaging Never Tested Before Launch', '2026-08-03 07:02:20.292706+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1051', '0.62', '2026-08-03 07:00:44.107477+00', '1536', 'text-embedding-3-small', NULL, 'The founder is thinking of "launch day" as one moment rather than a structured multi-week campaign.', '["all"]', 'external', 'Stage 0→1', '134', 'Behavioural', 'RC-1051', 'Launch Treated as a Single Event, Not a Plan', '2026-08-03 07:02:20.338663+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1052', '0.60', '2026-08-03 07:00:44.107477+00', '1536', 'text-embedding-3-small', NULL, 'There''s no clear metric or target for what a successful launch actually looks like.', '["all"]', 'external', 'Stage 0→1', '134', 'Strategic', 'RC-1052', 'No Definition of Early Success', '2026-08-03 07:02:20.386038+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1053', '0.65', '2026-08-03 07:00:44.107477+00', '1536', 'text-embedding-3-small', NULL, 'GTM planning has been delayed until the product is finished, rather than run in parallel.', '["all"]', 'external', 'Stage 0→1', '134', 'Behavioural', 'RC-1053', 'Waiting for the Product to Be Ready Before Any GTM Work', '2026-08-03 07:02:20.433383+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1054', '0.72', '2026-08-03 07:00:44.107477+00', '1536', 'text-embedding-3-small', NULL, 'The founder is unaware of structured tools (e.g. the Business Model Canvas) that exist specifically for designing a business model before building.', '["all"]', 'external', 'Stage 0', '135', 'Knowledge', 'RC-1054', 'Never Heard of or Used a Business Model Framework', '2026-08-03 07:02:20.48194+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1055', '0.68', '2026-08-03 07:00:44.107477+00', '1536', 'text-embedding-3-small', NULL, 'No version of the business model has ever been written down or visualized in one place.', '["all"]', 'external', 'Stage 0', '135', 'Operational', 'RC-1055', 'Business Model Exists Only in the Founder''s Head', '2026-08-03 07:02:20.528285+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1056', '0.65', '2026-08-03 07:00:44.107477+00', '1536', 'text-embedding-3-small', NULL, 'The founder can describe what they offer, but has not connected that offer to exactly how and where money is made.', '["all"]', 'external', 'Stage 0', '135', 'Strategic', 'RC-1056', 'Value Proposition Not Explicitly Linked to Revenue Streams', '2026-08-03 07:02:20.578395+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1057', '0.60', '2026-08-03 07:00:44.107477+00', '1536', 'text-embedding-3-small', NULL, 'The founder has not thought through what partnerships, suppliers, or resources the business model actually depends on.', '["all"]', 'external', 'Stage 0', '135', 'Knowledge', 'RC-1057', 'Key Partners and Resources Never Identified', '2026-08-03 07:02:20.626024+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1058', '0.65', '2026-08-03 07:00:44.107477+00', '1536', 'text-embedding-3-small', NULL, 'Different pieces of the business (pricing, channel, customer segment) may actually contradict each other, but this has never been checked.', '["all"]', 'external', 'Stage 0', '135', 'Strategic', 'RC-1058', 'Model Never Pressure-Tested for Internal Consistency', '2026-08-03 07:02:20.675982+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1059', '0.62', '2026-08-03 07:00:44.107477+00', '1536', 'text-embedding-3-small', NULL, 'The idea of designing a full business model feels big and abstract, so the founder avoids starting anywhere at all.', '["all"]', 'external', 'Stage 0', '135', 'Psychological', 'RC-1059', 'Overwhelmed by Where to Start', '2026-08-03 07:02:20.723197+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1060', '0.70', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'The founder has no repeatable set of questions or criteria applied to every new opportunity that comes in.', '["all"]', 'external', 'Stage 1→10+', '136', 'Knowledge', 'RC-1060', 'No Consistent Evaluation Criteria', '2026-08-03 07:23:25.292473+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1061', '0.68', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'Enthusiasm in the moment substitutes for objective assessment of whether an opportunity is actually good for the business.', '["all"]', 'external', 'Stage 1→10+', '136', 'Psychological', 'RC-1061', 'Excitement-Driven Decision Making', '2026-08-03 07:23:25.366272+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1062', '0.68', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'The founder says yes to avoid the discomfort of watching someone else potentially benefit from the opportunity.', '["all"]', 'external', 'Stage 1→10+', '136', 'Psychological', 'RC-1062', 'Fear of Missing Out Overrides Judgment', '2026-08-03 07:23:25.428265+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1063', '0.70', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'What the founder would have to give up (time, focus, resources) to pursue this opportunity is never explicitly weighed against what pursuing it might yield.', '["all"]', 'external', 'Stage 1→10+', '136', 'Knowledge', 'RC-1063', 'No Opportunity Cost Comparison', '2026-08-03 07:23:25.481332+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1064', '0.62', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'There''s no triage — a small partnership request gets the same urgent attention as a potentially business-changing opportunity.', '["all"]', 'external', 'Stage 1→10+', '136', 'Behavioural', 'RC-1064', 'Every Opportunity Treated as Equally Urgent', '2026-08-03 07:23:25.540358+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1065', '0.60', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'Opportunities are evaluated and decided on alone, without input from a co-founder, advisor, or team member who might see risks or blind spots.', '["all"]', 'external', 'Stage 1→10+', '136', 'Operational', 'RC-1065', 'No One Else Involved in the Decision', '2026-08-03 07:23:25.593357+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1066', '0.65', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'The founder doesn''t check whether a new opportunity actually supports or distracts from the core strategy already in motion.', '["all"]', 'external', 'Stage 1→10+', '136', 'Strategic', 'RC-1066', 'Strategic Fit Never Explicitly Checked', '2026-08-03 07:23:25.646323+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1067', '0.68', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'Saying no feels like letting someone down, so the founder avoids it even when an opportunity is clearly not a fit.', '["all"]', 'external', 'Stage 1→10+', '137', 'Psychological', 'RC-1067', 'Discomfort with Disappointing People', '2026-08-03 07:23:25.713784+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1068', '0.65', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'The founder equates having many things in motion with being more likely to succeed, rather than recognizing the cost of split focus.', '["all"]', 'external', 'Stage 1→10+', '137', 'Strategic', 'RC-1068', 'Belief That More Options Means More Success', '2026-08-03 07:23:25.768252+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1069', '0.60', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'There''s no place to park good-but-not-now opportunities, so they either get pursued immediately or forgotten entirely.', '["all"]', 'external', 'Stage 1→10+', '137', 'Operational', 'RC-1069', 'No Defined ''Not Right Now'' List', '2026-08-03 07:23:25.828141+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1070', '0.62', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'Each new opportunity is treated as unrepeatable, creating pressure to say yes rather than trusting more will come.', '["all"]', 'external', 'Stage 1→10+', '137', 'Behavioural', 'RC-1070', 'Every Opportunity Framed as Once-in-a-Lifetime', '2026-08-03 07:23:25.885358+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1071', '0.68', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'Without a clear sense of what matters most right now, everything looks equally worth pursuing.', '["all"]', 'external', 'Stage 1→10+', '137', 'Strategic', 'RC-1071', 'No Clarity on Current Core Priority', '2026-08-03 07:23:26.046531+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1072', '0.58', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'Previous partial commitments to other opportunities make it harder to decline new ones without feeling like past effort is wasted.', '["all"]', 'external', 'Stage 1→10+', '137', 'Behavioural', 'RC-1072', 'Sunk Cost in Half-Finished Pursuits', '2026-08-03 07:23:26.104811+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1073', '0.65', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'Each opportunity is considered on its own merits as it arrives, never compared side-by-side against others already on the table.', '["all"]', 'external', 'Stage 1→10+', '138', 'Behavioural', 'RC-1073', 'Opportunities Evaluated in Isolation', '2026-08-03 07:23:26.159614+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1074', '0.68', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'Even when multiple opportunities are considered, there''s no consistent yardstick used to compare them fairly.', '["all"]', 'external', 'Stage 1→10+', '138', 'Knowledge', 'RC-1074', 'No Shared Criteria Across Comparisons', '2026-08-03 07:23:26.21389+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1075', '0.62', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'The most recently presented opportunity gets disproportionate attention regardless of its actual merit relative to earlier ones.', '["all"]', 'external', 'Stage 1→10+', '138', 'Psychological', 'RC-1075', 'Recency Bias in Decision-Making', '2026-08-03 07:23:26.275015+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1076', '0.60', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'Opportunities aren''t tracked anywhere central, so the founder can''t actually see everything they''re choosing between.', '["all"]', 'external', 'Stage 1→10+', '138', 'Operational', 'RC-1076', 'No Visibility of All Options at Once', '2026-08-03 07:23:26.33149+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1077', '0.62', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'When too many opportunities exist at once, the founder freezes rather than systematically narrowing them down.', '["all"]', 'external', 'Stage 1→10+', '138', 'Psychological', 'RC-1077', 'Analysis Paralysis When Options Multiply', '2026-08-03 07:23:26.385064+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1078', '0.60', '2026-08-03 07:21:29.977684+00', '1536', 'text-embedding-3-small', NULL, 'Without a comparison method, decisions get delayed until the choice is made by default when one option''s window closes.', '["all"]', 'external', 'Stage 1→10+', '138', 'Behavioural', 'RC-1078', 'Decision Deferred Until an Opportunity Expires', '2026-08-03 07:23:26.438634+00') on conflict do nothing;
