insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1147', '0.62', '2026-08-03 11:00:51.857487+00', '1536', 'text-embedding-3-small', NULL, 'The founder sees opportunity evaluation as inherently a solo responsibility, not something to involve others in.', '["all"]', 'external', 'Stage 1→10+', '150', 'Psychological', 'RC-1147', 'Belief That Big Decisions Are the Founder''s Alone', '2026-08-03 11:01:50.7407+00') on conflict do nothing;
