insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1149', '0.65', '2026-08-03 11:00:51.857487+00', '1536', 'text-embedding-3-small', NULL, 'Team members closer to customers or operations might see risks or flaws in an opportunity that the founder, working from a distance, would miss.', '["all"]', 'external', 'Stage 1→10+', '150', 'Strategic', 'RC-1149', 'Blind Spots Team Could Catch Go Unnoticed', '2026-08-03 11:01:50.836499+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1150', '0.60', '2026-08-03 11:00:51.857487+00', '1536', 'text-embedding-3-small', NULL, 'By the time the team hears about a new opportunity being pursued, it''s already been decided rather than discussed.', '["all"]', 'external', 'Stage 1→10+', '150', 'Behavioural', 'RC-1150', 'Decisions Announced, Not Discussed', '2026-08-03 11:01:50.881339+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1151', '0.60', '2026-08-03 11:00:51.857487+00', '1536', 'text-embedding-3-small', NULL, 'Even if the founder wanted input, there''s no process or habit for actually gathering it before a decision is made.', '["all"]', 'external', 'Stage 1→10+', '150', 'Operational', 'RC-1151', 'No Structure for Gathering Input Before Deciding', '2026-08-03 11:01:50.92801+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1152', '0.58', '2026-08-03 11:00:51.857487+00', '1536', 'text-embedding-3-small', NULL, 'The founder avoids involving others because it feels like it would slow down decisive action.', '["all"]', 'external', 'Stage 1→10+', '150', 'Psychological', 'RC-1152', 'Fear That Consulting Others Slows Decisions Down', '2026-08-03 11:01:50.975649+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1153', '0.68', '2026-08-03 11:12:40.863128+00', '1536', 'text-embedding-3-small', NULL, 'Whatever planning happens stays with the founder and is never distributed or discussed with those who need to execute it.', '["all"]', 'external', 'Stage 0→1', '151', 'Operational', 'RC-1153', 'Plan Never Shared With the Team', '2026-08-03 11:13:55.584329+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1154', '0.62', '2026-08-03 11:12:40.863128+00', '1536', 'text-embedding-3-small', NULL, 'The founder assumes the team only needs task-level direction, not visibility into the broader plan.', '["all"]', 'external', 'Stage 0→1', '151', 'Psychological', 'RC-1154', 'Belief That the Team Doesn''t Need the Full Picture', '2026-08-03 11:13:55.641309+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1155', '0.62', '2026-08-03 11:12:40.863128+00', '1536', 'text-embedding-3-small', NULL, 'Even if the founder wanted to share the plan, there''s no simple format or document that makes it easy to communicate.', '["all"]', 'external', 'Stage 0→1', '151', 'Operational', 'RC-1155', 'No Format Exists to Communicate the Plan', '2026-08-03 11:13:55.691469+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1156', '0.65', '2026-08-03 11:12:40.863128+00', '1536', 'text-embedding-3-small', NULL, 'Without a shared plan, different team members may have different, sometimes conflicting, ideas about what matters most right now.', '["all"]', 'external', 'Stage 0→1', '151', 'Strategic', 'RC-1156', 'Team Working from Different Understandings of Priorities', '2026-08-03 11:13:55.739749+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1157', '0.62', '2026-08-03 11:12:40.863128+00', '1536', 'text-embedding-3-small', NULL, 'When the founder''s plan shifts, the team isn''t informed, so they continue working against an outdated version.', '["all"]', 'external', 'Stage 0→1', '151', 'Behavioural', 'RC-1157', 'Plan Changes Without Anyone Being Told', '2026-08-03 11:13:55.78853+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1158', '0.58', '2026-08-03 11:12:40.863128+00', '1536', 'text-embedding-3-small', NULL, 'Keeping the plan private avoids the discomfort of being visibly accountable if it doesn''t go as intended.', '["all"]', 'external', 'Stage 0→1', '151', 'Psychological', 'RC-1158', 'Discomfort Being Held Accountable to a Shared Plan', '2026-08-03 11:13:55.836634+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1159', '0.68', '2026-08-03 11:12:40.863128+00', '1536', 'text-embedding-3-small', NULL, 'Ambitious goals are set without first checking whether the team or founder has the bandwidth to actually deliver them.', '["all"]', 'external', 'Stage 0→1', '152', 'Knowledge', 'RC-1159', 'Goals Set Without Checking Available Capacity', '2026-08-03 11:13:55.884284+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1160', '0.65', '2026-08-03 11:12:40.863128+00', '1536', 'text-embedding-3-small', NULL, 'The plan doesn''t specify what it will cost, so financial resourcing is disconnected from strategic intent.', '["all"]', 'external', 'Stage 0→1', '152', 'Operational', 'RC-1160', 'Budget Never Connected to the Plan', '2026-08-03 11:13:55.932145+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1161', '0.65', '2026-08-03 11:12:40.863128+00', '1536', 'text-embedding-3-small', NULL, 'The founder assumes the current team can execute more than is realistic, without accounting for existing workload.', '["all"]', 'external', 'Stage 0→1', '152', 'Psychological', 'RC-1161', 'Overestimating What Current Team Can Deliver', '2026-08-03 11:13:55.979709+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1162', '0.62', '2026-08-03 11:12:40.863128+00', '1536', 'text-embedding-3-small', NULL, 'Plans assume everything goes smoothly, with no time or resource buffer for inevitable delays or surprises.', '["all"]', 'external', 'Stage 0→1', '152', 'Strategic', 'RC-1162', 'No Buffer for the Unexpected', '2026-08-03 11:13:56.026457+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1163', '0.62', '2026-08-03 11:12:40.863128+00', '1536', 'text-embedding-3-small', NULL, 'The need for more people or budget is only recognized once the plan is already failing to progress, rather than planned for upfront.', '["all"]', 'external', 'Stage 0→1', '152', 'Operational', 'RC-1163', 'Hiring or Resourcing Needs Identified Too Late', '2026-08-03 11:13:56.071804+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1164', '0.60', '2026-08-03 11:12:40.863128+00', '1536', 'text-embedding-3-small', NULL, 'Goals are set based on what the founder hopes is possible, rather than grounded in actual historical capacity or throughput.', '["all"]', 'external', 'Stage 0→1', '152', 'Behavioural', 'RC-1164', 'Plan Ambition Driven by Hope, Not Capacity Data', '2026-08-03 11:13:56.119819+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1165', '0.68', '2026-08-03 11:17:14.846403+00', '1536', 'text-embedding-3-small', NULL, 'Agreements with customers, vendors, or partners were used or signed without expert review of the risk they carry.', '["all"]', 'external', 'Stage 0→1', '153', 'Operational', 'RC-1165', 'Contracts Never Professionally Reviewed', '2026-08-03 11:18:15.861292+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1166', '0.68', '2026-08-03 11:17:14.846403+00', '1536', 'text-embedding-3-small', NULL, 'The founder isn''t certain which regulations actually apply to the business, or whether the business is fully compliant.', '["all"]', 'external', 'Stage 0→1', '153', 'Knowledge', 'RC-1166', 'Regulatory Obligations Not Fully Understood', '2026-08-03 11:18:15.939145+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1167', '0.65', '2026-08-03 11:17:14.846403+00', '1536', 'text-embedding-3-small', NULL, 'Trademarks, key content, or product IP have not been protected, leaving them vulnerable to copying or dispute.', '["all"]', 'external', 'Stage 0→1', '153', 'Operational', 'RC-1167', 'Intellectual Property Left Unprotected', '2026-08-03 11:18:15.992259+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1168', '0.62', '2026-08-03 11:17:14.846403+00', '1536', 'text-embedding-3-small', NULL, 'Legal review feels like a cost to avoid rather than a risk to manage, especially while the business is still small.', '["all"]', 'external', 'Stage 0→1', '153', 'Psychological', 'RC-1168', 'Legal Review Postponed as Too Expensive or Unnecessary', '2026-08-03 11:18:16.057709+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1169', '0.62', '2026-08-03 11:17:14.846403+00', '1536', 'text-embedding-3-small', NULL, 'There''s no ongoing relationship with legal expertise to call on, so issues only get addressed reactively when something goes wrong.', '["all"]', 'external', 'Stage 0→1', '153', 'Operational', 'RC-1169', 'No Relationship with a Lawyer or Compliance Advisor', '2026-08-03 11:18:16.148392+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1170', '0.60', '2026-08-03 11:17:14.846403+00', '1536', 'text-embedding-3-small', NULL, 'The founder assumes legal and compliance risk isn''t worth attention until the business is much bigger.', '["all"]', 'external', 'Stage 0→1', '153', 'Knowledge', 'RC-1170', 'Belief That Legal Risk Only Matters at a Larger Scale', '2026-08-03 11:18:16.196377+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1171', '0.65', '2026-08-03 11:17:14.846403+00', '1536', 'text-embedding-3-small', NULL, 'Without a named owner, responsibility for a risk is assumed to be shared, which in practice means nobody actually tracks it.', '["all"]', 'external', 'Stage 0→1', '154', 'Operational', 'RC-1171', 'Risks Treated as Everyone''s Job, So Nobody''s Job', '2026-08-03 11:18:16.247629+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1172', '0.62', '2026-08-03 11:17:14.846403+00', '1536', 'text-embedding-3-small', NULL, 'The founder takes on responsibility for every risk rather than delegating ownership, creating a bottleneck and reducing real oversight.', '["all"]', 'external', 'Stage 0→1', '154', 'Behavioural', 'RC-1172', 'Founder Defaults to Owning Every Risk Personally', '2026-08-03 11:18:16.300276+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1173', '0.65', '2026-08-03 11:17:14.846403+00', '1536', 'text-embedding-3-small', NULL, 'There''s no document listing risks and who''s responsible for each one, so ownership is never made explicit.', '["all"]', 'external', 'Stage 0→1', '154', 'Operational', 'RC-1173', 'No Risk Register or Tracking Document', '2026-08-03 11:18:16.34945+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1174', '0.62', '2026-08-03 11:17:14.846403+00', '1536', 'text-embedding-3-small', NULL, 'Even if the founder mentally assigns a risk to someone, that person often doesn''t know they''re expected to monitor it.', '["all"]', 'external', 'Stage 0→1', '154', 'Knowledge', 'RC-1174', 'Team Members Unaware They''re Expected to Watch for a Risk', '2026-08-03 11:18:16.399903+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1175', '0.60', '2026-08-03 11:17:14.846403+00', '1536', 'text-embedding-3-small', NULL, 'Without clear ownership, there''s no accountability when a known risk turns into an actual problem.', '["all"]', 'external', 'Stage 0→1', '154', 'Strategic', 'RC-1175', 'No Consequence for an Unmonitored Risk Materializing', '2026-08-03 11:18:16.449166+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1176', '0.58', '2026-08-03 11:17:14.846403+00', '1536', 'text-embedding-3-small', NULL, 'Risk ownership was assigned once but never reconfirmed as team roles or responsibilities changed.', '["all"]', 'external', 'Stage 0→1', '154', 'Behavioural', 'RC-1176', 'Ownership Assumed to Reset Automatically Over Time', '2026-08-03 11:18:16.502052+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1177', '0.68', '2026-08-03 11:28:47.796438+00', '1536', 'text-embedding-3-small', NULL, 'The model assumes a certain customer retention rate that was estimated, not measured from actual customer behavior.', '["all"]', 'external', 'Stage 0→1', '155', 'Knowledge', 'RC-1177', 'Retention Assumption Never Checked Against Real Data', '2026-08-03 11:29:40.152612+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1178', '0.65', '2026-08-03 11:28:47.796438+00', '1536', 'text-embedding-3-small', NULL, 'How often customers are expected to buy again was assumed at the start and never verified against real repeat-purchase data.', '["all"]', 'external', 'Stage 0→1', '155', 'Operational', 'RC-1178', 'Purchase Frequency Guessed, Not Observed', '2026-08-03 11:29:40.235213+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1179', '0.65', '2026-08-03 11:28:47.796438+00', '1536', 'text-embedding-3-small', NULL, 'The model counts on word-of-mouth or referrals at a certain rate that has never actually been observed or measured.', '["all"]', 'external', 'Stage 0→1', '155', 'Strategic', 'RC-1179', 'Referral Assumption Baked in Without Evidence', '2026-08-03 11:29:40.292324+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1180', '0.62', '2026-08-03 11:28:47.796438+00', '1536', 'text-embedding-3-small', NULL, 'There''s no dashboard or tracking that would reveal whether real customer behavior matches what the model assumes.', '["all"]', 'external', 'Stage 0→1', '155', 'Operational', 'RC-1180', 'No System for Tracking Real Behavior Against Model Assumptions', '2026-08-03 11:29:40.353154+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1181', '0.60', '2026-08-03 11:28:47.796438+00', '1536', 'text-embedding-3-small', NULL, 'The original assumptions behind the model were set early on and have never been updated as real data accumulated.', '["all"]', 'external', 'Stage 0→1', '155', 'Behavioural', 'RC-1181', 'Model Assumptions Set Once, Never Revisited', '2026-08-03 11:29:40.413316+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1182', '0.62', '2026-08-03 11:28:47.796438+00', '1536', 'text-embedding-3-small', NULL, 'Assumptions were set at hopeful levels rather than conservative ones, because the more hopeful numbers make the model look better.', '["all"]', 'external', 'Stage 0→1', '155', 'Psychological', 'RC-1182', 'Comfort with Optimistic Assumptions', '2026-08-03 11:29:40.469499+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1183', '0.70', '2026-08-03 12:57:17.857699+00', '1536', 'text-embedding-3-small', NULL, 'There''s no written definition of what makes a lead worth pursuing versus not, so every lead gets treated the same.', '["all"]', 'external', 'Stage 0→1', '156', 'Knowledge', 'RC-1183', 'No Defined Criteria for a Good-Fit Lead', '2026-08-03 12:58:09.811941+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1184', '0.65', '2026-08-03 12:57:17.857699+00', '1536', 'text-embedding-3-small', NULL, 'Declining to pursue a lead feels like leaving money on the table, so even poor-fit leads get chased.', '["all"]', 'external', 'Stage 0→1', '156', 'Psychological', 'RC-1184', 'Fear of Turning Away Potential Revenue', '2026-08-03 12:58:09.894881+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1185', '0.68', '2026-08-03 12:57:17.857699+00', '1536', 'text-embedding-3-small', NULL, 'Basic questions that would reveal fit (budget, timeline, authority, need) aren''t asked until far into the sales process, if at all.', '["all"]', 'external', 'Stage 0→1', '156', 'Operational', 'RC-1185', 'No Qualifying Questions Asked Early', '2026-08-03 12:58:09.953167+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1186', '0.62', '2026-08-03 12:57:17.857699+00', '1536', 'text-embedding-3-small', NULL, 'There''s no triage step, so a low-fit lead gets the same immediate attention as a high-fit one.', '["all"]', 'external', 'Stage 0→1', '156', 'Behavioural', 'RC-1186', 'All Leads Treated with Equal Urgency', '2026-08-03 12:58:10.008478+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1187', '0.60', '2026-08-03 12:57:17.857699+00', '1536', 'text-embedding-3-small', NULL, 'There''s no tracking of how much time goes into leads that never had a real chance of closing.', '["all"]', 'external', 'Stage 0→1', '156', 'Operational', 'RC-1187', 'Time Spent on Unqualified Leads Never Measured', '2026-08-03 12:58:10.061732+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1188', '0.62', '2026-08-03 12:57:17.857699+00', '1536', 'text-embedding-3-small', NULL, 'When the pipeline feels thin, qualification standards quietly drop just to keep something moving through it.', '["all"]', 'external', 'Stage 0→1', '156', 'Psychological', 'RC-1188', 'Qualification Skipped Under Pipeline Pressure', '2026-08-03 12:58:10.117768+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1189', '0.60', '2026-08-03 12:57:17.857699+00', '1536', 'text-embedding-3-small', NULL, 'Once a lead enters the pipeline, there''s no practice of actively removing poor-fit leads — they just linger.', '["all"]', 'external', 'Stage 0→1', '156', 'Behavioural', 'RC-1189', 'No Disqualification Habit', '2026-08-03 12:58:10.166504+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1190', '0.65', '2026-08-03 13:25:50.183633+00', '1536', 'text-embedding-3-small', NULL, 'Every outreach message is written completely from scratch, with no reusable structure to build on and refine.', '["all"]', 'external', 'Stage 0→1', '157', 'Operational', 'RC-1190', 'No Template or Structure to Start From', '2026-08-03 13:26:53.79154+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1191', '0.68', '2026-08-03 13:25:50.183633+00', '1536', 'text-embedding-3-small', NULL, 'The same generic message is sent to many prospects without any personalization to their specific situation.', '["all"]', 'external', 'Stage 0→1', '157', 'Behavioural', 'RC-1191', 'Generic Messaging Sent at Scale', '2026-08-03 13:26:53.879682+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1192', '0.65', '2026-08-03 13:25:50.183633+00', '1536', 'text-embedding-3-small', NULL, 'Different versions of outreach have never been compared to see which gets better response rates.', '["all"]', 'external', 'Stage 0→1', '157', 'Operational', 'RC-1192', 'No Testing of What Actually Gets Responses', '2026-08-03 13:26:53.936194+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1193', '0.68', '2026-08-03 13:25:50.183633+00', '1536', 'text-embedding-3-small', NULL, 'Outreach describes what the product does rather than starting from a problem the prospect actually has.', '["all"]', 'external', 'Stage 0→1', '157', 'Knowledge', 'RC-1193', 'Message Leads with Features, Not the Prospect''s Problem', '2026-08-03 13:26:53.995765+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1194', '0.62', '2026-08-03 13:25:50.183633+00', '1536', 'text-embedding-3-small', NULL, 'If the first message doesn''t get a response, there''s no planned follow-up — the prospect is simply dropped.', '["all"]', 'external', 'Stage 0→1', '157', 'Operational', 'RC-1194', 'No Follow-Up Sequence Beyond the First Message', '2026-08-03 13:26:54.050056+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1195', '0.60', '2026-08-03 13:25:50.183633+00', '1536', 'text-embedding-3-small', NULL, 'Discomfort with being direct about the offer leads to messages so soft they don''t clearly ask for anything.', '["all"]', 'external', 'Stage 0→1', '157', 'Psychological', 'RC-1195', 'Fear of Sounding Salesy Leads to Vague Messaging', '2026-08-03 13:26:54.100043+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1196', '0.58', '2026-08-03 13:25:50.183633+00', '1536', 'text-embedding-3-small', NULL, 'There''s no tracking of which message version or follow-up stage each prospect received, risking duplicate or inconsistent outreach.', '["all"]', 'external', 'Stage 0→1', '157', 'Operational', 'RC-1196', 'No Record of What''s Been Sent to Whom', '2026-08-03 13:26:54.147626+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1197', '0.68', '2026-08-03 13:30:06.16355+00', '1536', 'text-embedding-3-small', NULL, 'Every proposal is built from scratch, with no base template to save time and ensure consistency.', '["all"]', 'external', 'Stage 0→1', '158', 'Operational', 'RC-1197', 'No Reusable Proposal Template', '2026-08-03 13:30:58.341937+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1198', '0.65', '2026-08-03 13:30:06.16355+00', '1536', 'text-embedding-3-small', NULL, 'It takes so long to prepare a proposal that prospects lose momentum or interest while waiting.', '["all"]', 'external', 'Stage 0→1', '158', 'Operational', 'RC-1198', 'Proposal Turnaround Too Slow', '2026-08-03 13:30:58.406008+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1199', '0.68', '2026-08-03 13:30:06.16355+00', '1536', 'text-embedding-3-small', NULL, 'The proposal is generic or templated in a way that doesn''t clearly reference the specific problems and needs discussed with that prospect.', '["all"]', 'external', 'Stage 0→1', '158', 'Knowledge', 'RC-1199', 'Proposal Doesn''t Reflect What Was Discussed', '2026-08-03 13:30:58.461885+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1200', '0.65', '2026-08-03 13:30:06.16355+00', '1536', 'text-embedding-3-small', NULL, 'Pricing is presented inconsistently or confusingly, without a clear structure (tiers, options, what''s included) that makes the decision easy.', '["all"]', 'external', 'Stage 0→1', '158', 'Knowledge', 'RC-1200', 'No Clear Pricing Presentation Structure', '2026-08-03 13:30:58.515929+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1201', '0.62', '2026-08-03 13:30:06.16355+00', '1536', 'text-embedding-3-small', NULL, 'Once a proposal is sent, there''s no structured follow-up plan — the founder waits passively rather than proactively continuing the conversation.', '["all"]', 'external', 'Stage 0→1', '158', 'Operational', 'RC-1201', 'No Follow-Up Process After Sending a Proposal', '2026-08-03 13:30:58.566016+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1202', '0.60', '2026-08-03 13:30:06.16355+00', '1536', 'text-embedding-3-small', NULL, 'Proposals use jargon or try to sound sophisticated rather than being written for clarity and easy decision-making.', '["all"]', 'external', 'Stage 0→1', '158', 'Behavioural', 'RC-1202', 'Proposal Written to Impress, Not to Be Understood', '2026-08-03 13:30:58.613632+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1203', '0.60', '2026-08-03 13:30:06.16355+00', '1536', 'text-embedding-3-small', NULL, 'There''s no record of why proposals succeeded or failed, so nothing is learned or improved over time.', '["all"]', 'external', 'Stage 0→1', '158', 'Operational', 'RC-1203', 'No Tracking of Proposal Win/Loss Reasons', '2026-08-03 13:30:58.661316+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1204', '0.68', '2026-08-03 15:50:09.899288+00', '1536', 'text-embedding-3-small', NULL, 'There''s no set rhythm (e.g. day 1, 3, 7, 14) for following up with a prospect — it happens whenever the founder remembers.', '["all"]', 'external', 'Stage 0→1', '159', 'Operational', 'RC-1204', 'No Defined Follow-Up Cadence', '2026-08-03 15:51:12.665485+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1205', '0.65', '2026-08-03 15:50:09.899288+00', '1536', 'text-embedding-3-small', NULL, 'Whether and when to follow up depends entirely on the founder recalling to do it, with nothing tracking who''s due for a touch.', '["all"]', 'external', 'Stage 0→1', '159', 'Operational', 'RC-1205', 'Follow-Up Frequency Left to Memory', '2026-08-03 15:51:12.750452+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1206', '0.65', '2026-08-03 15:50:09.899288+00', '1536', 'text-embedding-3-small', NULL, 'The founder worries that following up too much will annoy the prospect, so they under-follow-up instead.', '["all"]', 'external', 'Stage 0→1', '159', 'Psychological', 'RC-1206', 'Fear of Being Seen as Pushy', '2026-08-03 15:51:12.820193+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1207', '0.60', '2026-08-03 15:50:09.899288+00', '1536', 'text-embedding-3-small', NULL, 'Follow-ups just repeat the same message (''checking in'') rather than adding new value or a new angle each time.', '["all"]', 'external', 'Stage 0→1', '159', 'Behavioural', 'RC-1207', 'Same Follow-Up Message Repeated', '2026-08-03 15:51:12.902749+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1208', '0.58', '2026-08-03 15:50:09.899288+00', '1536', 'text-embedding-3-small', NULL, 'Every follow-up happens through the same channel (e.g. only email), even when a prospect might respond better to a different one.', '["all"]', 'external', 'Stage 0→1', '159', 'Knowledge', 'RC-1208', 'No Channel Variety in Follow-Up', '2026-08-03 15:51:12.971636+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1209', '0.65', '2026-08-03 15:50:09.899288+00', '1536', 'text-embedding-3-small', NULL, 'As the number of active prospects grows, there''s no system to ensure everyone gets followed up with consistently.', '["all"]', 'external', 'Stage 0→1', '159', 'Operational', 'RC-1209', 'Prospects Fall Through the Cracks at Scale', '2026-08-03 15:51:13.029445+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1210', '0.60', '2026-08-03 15:50:09.899288+00', '1536', 'text-embedding-3-small', NULL, 'There''s no defined point at which the founder stops following up with an unresponsive prospect, leading to either premature giving-up or endless chasing.', '["all"]', 'external', 'Stage 0→1', '159', 'Strategic', 'RC-1210', 'No Clear Stopping Point for Follow-Up', '2026-08-03 15:51:13.093075+00') on conflict do nothing;
