insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1213', '0.68', '2026-08-03 15:55:34.351973+00', '1536', 'text-embedding-3-small', NULL, 'Losses aren''t tagged by reason (price, timing, fit, competitor, no decision), so there''s no way to see which reason is most common.', '["all"]', 'external', 'Stage 0→1', '160', 'Knowledge', 'RC-1213', 'No Categorization of Loss Reasons', '2026-08-03 15:56:33.928144+00') on conflict do nothing;
