insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1251', '0.60', '2026-08-03 17:48:41.682416+00', '1536', 'text-embedding-3-small', NULL, 'Ad copy, visuals, or messaging get created at the last minute rather than planned as part of the campaign.', '["all"]', 'external', 'Stage 0→1', '165', 'Operational', 'RC-1251', 'No Creative or Messaging Plan Before Launch', '2026-08-03 17:49:35.735887+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1252', '0.60', '2026-08-03 17:48:41.682416+00', '1536', 'text-embedding-3-small', NULL, 'Campaigns get launched out of pressure to ''do something'' or react to a competitor, rather than as part of a deliberate plan.', '["all"]', 'external', 'Stage 0→1', '165', 'Psychological', 'RC-1252', 'Campaigns Launched Reactively to Compete or Fill Time', '2026-08-03 17:49:35.792484+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1253', '0.68', '2026-08-03 17:53:07.927357+00', '1536', 'text-embedding-3-small', NULL, 'There''s no habit of sitting down after a campaign ends to review what actually happened.', '["all"]', 'external', 'Stage 0→1', '166', 'Operational', 'RC-1253', 'No Post-Campaign Review Conducted', '2026-08-03 17:54:05.830288+00') on conflict do nothing;
