insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1257', '0.62', '2026-08-03 17:53:07.927357+00', '1536', 'text-embedding-3-small', NULL, 'Even where something is learned from a campaign, it isn''t written down anywhere, so the same lessons get relearned repeatedly.', '["all"]', 'external', 'Stage 0→1', '166', 'Operational', 'RC-1257', 'Learnings Not Documented or Carried Forward', '2026-08-03 17:54:06.132332+00') on conflict do nothing;
