insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1317', '0.68', '2026-08-03 19:16:01.508577+00', '1536', 'text-embedding-3-small', NULL, 'How to do key tasks exists only in the founder''s memory, never externalized into a document anyone else could follow.', '["all"]', 'external', 'Stage 0→1', '176', 'Knowledge', 'RC-1317', 'Knowledge Stays in the Founder''s Head', '2026-08-03 19:17:01.742448+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1318', '0.62', '2026-08-03 19:16:01.508577+00', '1536', 'text-embedding-3-small', NULL, 'Documenting a process feels like a distraction from actually doing the work, so it keeps getting deprioritized.', '["all"]', 'external', 'Stage 0→1', '176', 'Psychological', 'RC-1318', 'Writing SOPs Feels Like a Low Priority', '2026-08-03 19:17:01.790668+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1319', '0.62', '2026-08-03 19:16:01.508577+00', '1536', 'text-embedding-3-small', NULL, 'Rather than writing something down once, the founder re-explains the same process verbally every time it comes up.', '["all"]', 'external', 'Stage 0→1', '176', 'Behavioural', 'RC-1319', 'Same Instructions Repeated Verbally Each Time', '2026-08-03 19:17:01.841321+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1320', '0.60', '2026-08-03 19:16:01.508577+00', '1536', 'text-embedding-3-small', NULL, 'Even if the founder wanted to write an SOP, there''s no simple format or template to make it quick and consistent.', '["all"]', 'external', 'Stage 0→1', '176', 'Operational', 'RC-1320', 'No Template or Format for Writing SOPs', '2026-08-03 19:17:01.890128+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1321', '0.60', '2026-08-03 19:16:01.508577+00', '1536', 'text-embedding-3-small', NULL, 'Where an SOP was written once, it''s gone stale and no longer reflects how the process actually works now.', '["all"]', 'external', 'Stage 0→1', '176', 'Operational', 'RC-1321', 'Existing SOPs Never Updated as Process Changes', '2026-08-03 19:17:01.938076+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1322', '0.58', '2026-08-03 19:16:01.508577+00', '1536', 'text-embedding-3-small', NULL, 'Nobody, including the founder, is responsible for reviewing and updating documented procedures over time.', '["all"]', 'external', 'Stage 0→1', '176', 'Operational', 'RC-1322', 'No One Owns Keeping SOPs Current', '2026-08-03 19:17:01.988534+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1323', '0.68', '2026-08-03 19:18:54.268294+00', '1536', 'text-embedding-3-small', NULL, 'There''s no written document covering basic workplace policies (conduct, leave, hours, expectations).', '["all"]', 'external', 'Stage 0→1', '177', 'Operational', 'RC-1323', 'No Employee Handbook or Policy Document Exists', '2026-08-03 19:20:03.13344+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1324', '0.70', '2026-08-03 19:18:54.268294+00', '1536', 'text-embedding-3-small', NULL, 'New hires join without a clear written contract or offer letter covering terms of employment.', '["all"]', 'external', 'Stage 0→1', '177', 'Operational', 'RC-1324', 'Employment Terms Never Formally Documented', '2026-08-03 19:20:03.197099+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1325', '0.62', '2026-08-03 19:18:54.268294+00', '1536', 'text-embedding-3-small', NULL, 'The founder assumes formal policies only matter once the team is much bigger.', '["all"]', 'external', 'Stage 0→1', '177', 'Psychological', 'RC-1325', 'Policies Assumed Unnecessary at Small Team Size', '2026-08-03 19:20:03.25096+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1326', '0.65', '2026-08-03 19:18:54.268294+00', '1536', 'text-embedding-3-small', NULL, 'Employment practices and any informal policies have never been checked against legal requirements.', '["all"]', 'external', 'Stage 0→1', '177', 'Knowledge', 'RC-1326', 'No Legal Review of Employment Practices', '2026-08-03 19:20:03.304396+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1327', '0.60', '2026-08-03 19:18:54.268294+00', '1536', 'text-embedding-3-small', NULL, 'Whatever rules or expectations exist get communicated verbally, differently to different people, rather than in one consistent written source.', '["all"]', 'external', 'Stage 0→1', '177', 'Behavioural', 'RC-1327', 'Policies Communicated Verbally and Inconsistently', '2026-08-03 19:20:03.356466+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1328', '0.58', '2026-08-03 19:18:54.268294+00', '1536', 'text-embedding-3-small', NULL, 'Nobody, including the founder, has responsibility for creating or keeping policies up to date.', '["all"]', 'external', 'Stage 0→1', '177', 'Operational', 'RC-1328', 'No Owner for Creating or Maintaining Policies', '2026-08-03 19:20:03.416143+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1329', '0.60', '2026-08-03 19:18:54.268294+00', '1536', 'text-embedding-3-small', NULL, 'The absence of a policy only becomes visible reactively, once a specific situation exposes the gap.', '["all"]', 'external', 'Stage 0→1', '177', 'Behavioural', 'RC-1329', 'Policy Gaps Only Noticed After a Problem Arises', '2026-08-03 19:20:03.47139+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1330', '0.68', '2026-08-04 05:13:53.57963+00', '1536', 'text-embedding-3-small', NULL, 'There''s no point-based or ranked system for scoring leads against each other on likely fit or urgency.', '["all"]', 'external', 'Stage 0→1', '178', 'Knowledge', 'RC-1330', 'No Lead Scoring Criteria Defined', '2026-08-04 05:15:00.547402+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1331', '0.65', '2026-08-04 05:13:53.57963+00', '1536', 'text-embedding-3-small', NULL, 'Leads get contacted strictly in the order they came in, regardless of which is actually most promising.', '["all"]', 'external', 'Stage 0→1', '178', 'Behavioural', 'RC-1331', 'Leads Worked in Arrival Order Only', '2026-08-04 05:15:01.08147+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1332', '0.65', '2026-08-04 05:13:53.57963+00', '1536', 'text-embedding-3-small', NULL, 'All leads are treated with the same urgency, without separating clearly warm/ready leads from early-stage ones.', '["all"]', 'external', 'Stage 0→1', '178', 'Knowledge', 'RC-1332', 'No Distinction Between Hot and Cold Leads', '2026-08-04 05:15:01.220347+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1333', '0.60', '2026-08-04 05:13:53.57963+00', '1536', 'text-embedding-3-small', NULL, 'Which lead to work on next is decided intuitively in the moment rather than against consistent criteria.', '["all"]', 'external', 'Stage 0→1', '178', 'Behavioural', 'RC-1333', 'Prioritization Decided by Gut Feel Each Time', '2026-08-04 05:15:01.298905+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1334', '0.62', '2026-08-04 05:13:53.57963+00', '1536', 'text-embedding-3-small', NULL, 'Leads aren''t tracked in one place, so there''s no way to actually compare and prioritize across all of them together.', '["all"]', 'external', 'Stage 0→1', '178', 'Operational', 'RC-1334', 'No Visibility Across All Active Leads at Once', '2026-08-04 05:15:01.356436+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1335', '0.65', '2026-08-04 05:13:53.57963+00', '1536', 'text-embedding-3-small', NULL, 'A genuinely strong lead can get lost among many lower-quality ones because nothing flags it as a priority.', '["all"]', 'external', 'Stage 0→1', '178', 'Strategic', 'RC-1335', 'High-Value Leads Sometimes Missed in the Noise', '2026-08-04 05:15:01.412673+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1336', '0.60', '2026-08-04 05:13:53.57963+00', '1536', 'text-embedding-3-small', NULL, 'Equal time gets spent on every lead regardless of how much revenue potential it represents.', '["all"]', 'external', 'Stage 0→1', '178', 'Operational', 'RC-1336', 'No Time Allocated Based on Lead Potential', '2026-08-04 05:15:01.465796+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1337', '0.68', '2026-08-04 05:24:12.900201+00', '1536', 'text-embedding-3-small', NULL, 'Leads that are a good fit but poor timing get treated the same as leads that are a genuinely bad fit, rather than being handled differently.', '["all"]', 'external', 'Stage 0→1', '179', 'Knowledge', 'RC-1337', 'No Distinction Between ''Not a Fit'' and ''Not Ready Yet''', '2026-08-04 05:25:17.174351+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1338', '0.68', '2026-08-04 05:24:12.900201+00', '1536', 'text-embedding-3-small', NULL, 'There''s no ongoing touch sequence to stay in front of a good-fit lead until they''re ready to buy.', '["all"]', 'external', 'Stage 0→1', '179', 'Operational', 'RC-1338', 'No Nurture Sequence for Not-Yet-Ready Leads', '2026-08-04 05:25:17.268127+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1339', '0.65', '2026-08-04 05:24:12.900201+00', '1536', 'text-embedding-3-small', NULL, 'Once a lead says ''not right now,'' they disappear from any active tracking and are never followed up with again.', '["all"]', 'external', 'Stage 0→1', '179', 'Behavioural', 'RC-1339', 'Not-Ready Leads Simply Forgotten', '2026-08-04 05:25:17.352654+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1340', '0.65', '2026-08-04 05:24:12.900201+00', '1536', 'text-embedding-3-small', NULL, 'There''s no reminder or trigger for when to circle back with a lead who said to check in later.', '["all"]', 'external', 'Stage 0→1', '179', 'Operational', 'RC-1340', 'No System for Tracking When to Re-Engage', '2026-08-04 05:25:17.408476+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1341', '0.60', '2026-08-04 05:24:12.900201+00', '1536', 'text-embedding-3-small', NULL, 'The founder worries that following up with a not-ready lead later will feel pushy or annoying.', '["all"]', 'external', 'Stage 0→1', '179', 'Psychological', 'RC-1341', 'Fear of Being a Bother by Re-Engaging', '2026-08-04 05:25:17.46343+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1342', '0.58', '2026-08-04 05:24:12.900201+00', '1536', 'text-embedding-3-small', NULL, 'Even if the founder wanted to nurture a lead, there''s nothing useful (updates, insights, resources) to share in the meantime.', '["all"]', 'external', 'Stage 0→1', '179', 'Knowledge', 'RC-1342', 'No Value-Add Content to Nurture With', '2026-08-04 05:25:17.518598+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1343', '0.60', '2026-08-04 05:24:12.900201+00', '1536', 'text-embedding-3-small', NULL, 'These leads aren''t tracked as future potential revenue, so their value to the business goes unrecognized.', '["all"]', 'external', 'Stage 0→1', '179', 'Strategic', 'RC-1343', 'Not-Ready Leads Not Counted as Real Pipeline', '2026-08-04 05:25:17.576677+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1344', '0.68', '2026-08-04 05:30:58.762536+00', '1536', 'text-embedding-3-small', NULL, 'There''s no consistent order or set of questions used to run a qualifying conversation, so each call is structured differently.', '["all"]', 'external', 'Stage 0→1', '180', 'Operational', 'RC-1344', 'No Standard Question Sequence for Qualifying Calls', '2026-08-04 05:32:36.459556+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1345', '0.68', '2026-08-04 05:30:58.762536+00', '1536', 'text-embedding-3-small', NULL, 'Instead of asking discovery questions, the founder starts selling before actually understanding the prospect''s situation.', '["all"]', 'external', 'Stage 0→1', '180', 'Behavioural', 'RC-1345', 'Conversation Turns Into a Pitch Too Early', '2026-08-04 05:32:36.518329+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1346', '0.65', '2026-08-04 05:30:58.762536+00', '1536', 'text-embedding-3-small', NULL, 'The founder doesn''t know what to listen for that would indicate genuine interest or readiness versus polite interest.', '["all"]', 'external', 'Stage 0→1', '180', 'Knowledge', 'RC-1346', 'No Practice Reading Buying Signals in Real Time', '2026-08-04 05:32:36.567524+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1347', '0.65', '2026-08-04 05:30:58.762536+00', '1536', 'text-embedding-3-small', NULL, 'Questions about ability to pay or decision-making power feel awkward to ask directly, so they get avoided or asked indirectly.', '["all"]', 'external', 'Stage 0→1', '180', 'Psychological', 'RC-1347', 'Uncomfortable Asking Direct Questions About Budget or Authority', '2026-08-04 05:32:36.617748+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1348', '0.62', '2026-08-04 05:30:58.762536+00', '1536', 'text-embedding-3-small', NULL, 'Qualifying conversations often end without a defined next action, leaving the lead in limbo.', '["all"]', 'external', 'Stage 0→1', '180', 'Operational', 'RC-1348', 'No Way to End a Call with a Clear Next Step', '2026-08-04 05:32:36.669523+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1349', '0.60', '2026-08-04 05:30:58.762536+00', '1536', 'text-embedding-3-small', NULL, 'What''s learned during a qualifying conversation isn''t written down in a consistent place, so it gets lost or forgotten.', '["all"]', 'external', 'Stage 0→1', '180', 'Operational', 'RC-1349', 'Notes from Qualifying Calls Not Captured Consistently', '2026-08-04 05:32:36.721118+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1350', '0.58', '2026-08-04 05:30:58.762536+00', '1536', 'text-embedding-3-small', NULL, 'The founder has never practiced or refined how they run a qualifying call, so it stays inconsistent and improvised.', '["all"]', 'external', 'Stage 0→1', '180', 'Behavioural', 'RC-1350', 'No Practice or Rehearsal of the Qualifying Conversation', '2026-08-04 05:32:36.794147+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1351', '0.68', '2026-08-04 05:36:48.713599+00', '1536', 'text-embedding-3-small', NULL, 'Whatever criteria exist were decided at the start and have never been checked against real outcomes.', '["all"]', 'external', 'Stage 1→10+', '181', 'Operational', 'RC-1351', 'Qualification Criteria Set Once, Never Tested', '2026-08-04 05:37:53.313661+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1352', '0.68', '2026-08-04 05:36:48.713599+00', '1536', 'text-embedding-3-small', NULL, 'There''s no feedback loop connecting which leads passed qualification to how they performed as customers afterward.', '["all"]', 'external', 'Stage 1→10+', '181', 'Operational', 'RC-1352', 'No Tracking of Which Qualified Leads Actually Became Good Customers', '2026-08-04 05:37:53.377482+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1353', '0.65', '2026-08-04 05:36:48.713599+00', '1536', 'text-embedding-3-small', NULL, 'Qualification criteria were guessed at the start rather than derived from patterns in actual won deals.', '["all"]', 'external', 'Stage 1→10+', '181', 'Knowledge', 'RC-1353', 'Criteria Based on Assumption, Not Past Data', '2026-08-04 05:37:53.442239+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1354', '0.62', '2026-08-04 05:36:48.713599+00', '1536', 'text-embedding-3-small', NULL, 'Leads that were screened out under current criteria might have actually converted well, but this is never checked.', '["all"]', 'external', 'Stage 1→10+', '181', 'Strategic', 'RC-1354', 'Some Disqualified Leads May Have Been Good Fits', '2026-08-04 05:37:53.510343+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1355', '0.60', '2026-08-04 05:36:48.713599+00', '1536', 'text-embedding-3-small', NULL, 'As the product, pricing, or market shifts, qualification criteria stay frozen at their original version.', '["all"]', 'external', 'Stage 1→10+', '181', 'Behavioural', 'RC-1355', 'Criteria Never Updated as the Business Evolves', '2026-08-04 05:37:53.561879+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1356', '0.62', '2026-08-04 05:36:48.713599+00', '1536', 'text-embedding-3-small', NULL, 'Criteria may filter for leads that are simply easy to close rather than those who become the most valuable, successful customers.', '["all"]', 'external', 'Stage 1→10+', '181', 'Knowledge', 'RC-1356', 'No Distinction Between Easy-to-Qualify and Best-Fit Customers', '2026-08-04 05:37:53.619417+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1357', '0.60', '2026-08-04 05:36:48.713599+00', '1536', 'text-embedding-3-small', NULL, 'There''s no clear definition of what a successful customer outcome even looks like, making it hard to check criteria against it.', '["all"]', 'external', 'Stage 1→10+', '181', 'Knowledge', 'RC-1357', 'Success Definition for ''Good Customer'' Never Actually Defined', '2026-08-04 05:37:53.670084+00') on conflict do nothing;
