insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1361', '0.60', '2026-08-04 05:43:41.336623+00', '1536', 'text-embedding-3-small', NULL, 'Even when some research happens, there''s no place to record it for use in the actual outreach message.', '["all"]', 'external', 'Stage 0→1', '182', 'Operational', 'RC-1361', 'No System for Storing What''s Learned About a Prospect', '2026-08-04 05:44:41.801498+00') on conflict do nothing;
