insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1419', '0.60', '2026-08-04 06:55:19.301466+00', '1536', 'text-embedding-3-small', NULL, 'A prospect who''s genuinely not interested is treated the same as one who''s just delayed, wasting effort on the wrong ones or giving up on the right ones.', '["all"]', 'external', 'Stage 0→1', '190', 'Knowledge', 'RC-1419', 'No Distinction Between a Soft No and a Hard No', '2026-08-04 06:56:49.789199+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1420', '0.58', '2026-08-04 06:55:19.301466+00', '1536', 'text-embedding-3-small', NULL, 'Feeling discouraged by silence leads to either giving up entirely or over-following-up out of anxiety, rather than a deliberate, calibrated approach.', '["all"]', 'external', 'Stage 0→1', '190', 'Psychological', 'RC-1420', 'Emotional Reaction to Silence Drives the Response', '2026-08-04 06:56:49.847655+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1421', '0.65', '2026-08-04 10:25:46.984914+00', '1536', 'text-embedding-3-small', NULL, 'After multiple unsuccessful attempts, the same kind of touch (e.g. another email) keeps getting used instead of trying something different.', '["all"]', 'external', 'Stage 0→1', '191', 'Behavioural', 'RC-1421', 'Same Follow-Up Type Repeated Even When It''s Not Working', '2026-08-04 10:26:48.96898+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1422', '0.65', '2026-08-04 10:25:46.984914+00', '1536', 'text-embedding-3-small', NULL, 'There''s no specific point (e.g. after 3 attempts) at which the approach is supposed to change.', '["all"]', 'external', 'Stage 0→1', '191', 'Operational', 'RC-1422', 'No Defined Escalation Point', '2026-08-04 10:26:49.116142+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1423', '0.62', '2026-08-04 10:25:46.984914+00', '1536', 'text-embedding-3-small', NULL, 'The founder doesn''t have a set of different tactics (a call, reaching a different contact, a different angle) to try when the standard approach stalls.', '["all"]', 'external', 'Stage 0→1', '191', 'Knowledge', 'RC-1423', 'No Alternative Approaches Considered', '2026-08-04 10:26:49.17856+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1424', '0.60', '2026-08-04 10:25:46.984914+00', '1536', 'text-embedding-3-small', NULL, 'When the usual follow-up doesn''t work, the only two options considered are keep repeating or stop entirely — nothing in between.', '["all"]', 'external', 'Stage 0→1', '191', 'Behavioural', 'RC-1424', 'Giving Up Treated as the Only Alternative to Repeating', '2026-08-04 10:26:49.231943+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1425', '0.60', '2026-08-04 10:25:46.984914+00', '1536', 'text-embedding-3-small', NULL, 'If the original contact goes quiet, there''s no consideration of reaching someone else at the company who might respond.', '["all"]', 'external', 'Stage 0→1', '191', 'Strategic', 'RC-1425', 'No Attempt to Reach a Different Stakeholder', '2026-08-04 10:26:49.296864+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1426', '0.58', '2026-08-04 10:25:46.984914+00', '1536', 'text-embedding-3-small', NULL, 'Trying something different after standard follow-up fails feels like it would seem overly eager or desperate.', '["all"]', 'external', 'Stage 0→1', '191', 'Psychological', 'RC-1426', 'Fear That Changing Approach Looks Desperate', '2026-08-04 10:26:49.349522+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1427', '0.58', '2026-08-04 10:25:46.984914+00', '1536', 'text-embedding-3-small', NULL, 'The founder isn''t aware of or hasn''t tried tactics specifically designed to break through when standard follow-up isn''t landing.', '["all"]', 'external', 'Stage 0→1', '191', 'Knowledge', 'RC-1427', 'No Pattern-Interrupt Tactics Ever Used', '2026-08-04 10:26:49.403813+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1428', '0.68', '2026-08-04 10:29:26.959051+00', '1536', 'text-embedding-3-small', NULL, 'There''s no record showing what''s already been sent to a given prospect and when.', '["all"]', 'external', 'Stage 0→1', '192', 'Operational', 'RC-1428', 'No Log of Past Follow-Up Attempts Per Prospect', '2026-08-04 10:30:33.826052+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1429', '0.68', '2026-08-04 10:29:26.959051+00', '1536', 'text-embedding-3-small', NULL, 'Without a system, the founder has to remember who''s been contacted and what was said, which breaks down as volume grows.', '["all"]', 'external', 'Stage 0→1', '192', 'Operational', 'RC-1429', 'Relies Entirely on Memory to Track Follow-Up History', '2026-08-04 10:30:33.899033+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1430', '0.62', '2026-08-04 10:29:26.959051+00', '1536', 'text-embedding-3-small', NULL, 'Without a history, a new follow-up might repeat information already sent or contradict an earlier message.', '["all"]', 'external', 'Stage 0→1', '192', 'Behavioural', 'RC-1430', 'Risk of Sending Contradictory or Duplicate Messages', '2026-08-04 10:30:33.958362+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1431', '0.60', '2026-08-04 10:29:26.959051+00', '1536', 'text-embedding-3-small', NULL, 'There''s no way to see how long a prospect has been in the follow-up sequence without checking manually.', '["all"]', 'external', 'Stage 0→1', '192', 'Knowledge', 'RC-1431', 'No Visibility Into How Long a Prospect Has Been in Follow-Up', '2026-08-04 10:30:34.017096+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1432', '0.62', '2026-08-04 10:29:26.959051+00', '1536', 'text-embedding-3-small', NULL, 'Without tracking, some prospects simply get lost and are never followed up with again, not because a decision was made, but because they were forgotten.', '["all"]', 'external', 'Stage 0→1', '192', 'Operational', 'RC-1432', 'Lost Prospects Never Rediscovered', '2026-08-04 10:30:34.080583+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1433', '0.60', '2026-08-04 10:29:26.959051+00', '1536', 'text-embedding-3-small', NULL, 'Follow-up history is scattered across email, notes, and memory rather than centralized in one place.', '["all"]', 'external', 'Stage 0→1', '192', 'Operational', 'RC-1433', 'No Single Place Housing All Prospect Communication', '2026-08-04 10:30:34.130474+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1434', '0.58', '2026-08-04 10:29:26.959051+00', '1536', 'text-embedding-3-small', NULL, 'The founder assumes a formal tracking system isn''t needed yet, even as volume grows past what memory can handle.', '["all"]', 'external', 'Stage 0→1', '192', 'Psychological', 'RC-1434', 'System Feels Unnecessary at Current Volume', '2026-08-04 10:30:34.17779+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1435', '0.68', '2026-08-04 10:33:13.907552+00', '1536', 'text-embedding-3-small', NULL, 'There''s no data showing whether the 1st, 2nd, or 5th follow-up is actually the one that gets responses.', '["all"]', 'external', 'Stage 1→10+', '193', 'Operational', 'RC-1435', 'No Tracking of Response Rates by Follow-Up Attempt Number', '2026-08-04 10:34:23.957665+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1436', '0.65', '2026-08-04 10:33:13.907552+00', '1536', 'text-embedding-3-small', NULL, 'Different intervals between follow-ups (next day vs next week) have never been compared for effectiveness.', '["all"]', 'external', 'Stage 1→10+', '193', 'Knowledge', 'RC-1436', 'No Comparison of Different Follow-Up Timings', '2026-08-04 10:34:24.045732+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1437', '0.65', '2026-08-04 10:33:13.907552+00', '1536', 'text-embedding-3-small', NULL, 'The same follow-up approach continues indefinitely regardless of whether it''s actually producing results.', '["all"]', 'external', 'Stage 1→10+', '193', 'Behavioural', 'RC-1437', 'Follow-Up Approach Never Adjusted Based on Results', '2026-08-04 10:34:24.106633+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1438', '0.60', '2026-08-04 10:33:13.907552+00', '1536', 'text-embedding-3-small', NULL, 'There''s no benchmark for what response rate or conversion rate would indicate the follow-up process is working well.', '["all"]', 'external', 'Stage 1→10+', '193', 'Knowledge', 'RC-1438', 'No Sense of What ''Good'' Follow-Up Performance Looks Like', '2026-08-04 10:34:24.178313+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1439', '0.60', '2026-08-04 10:33:13.907552+00', '1536', 'text-embedding-3-small', NULL, 'Follow-up is seen as just something you do, not a system that can be measured and improved over time.', '["all"]', 'external', 'Stage 1→10+', '193', 'Psychological', 'RC-1439', 'Follow-Up Treated as a Fixed Process, Not an Improvable System', '2026-08-04 10:34:24.247883+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1440', '0.60', '2026-08-04 10:33:13.907552+00', '1536', 'text-embedding-3-small', NULL, 'There''s no periodic check-in to look at how the follow-up process is performing overall.', '["all"]', 'external', 'Stage 1→10+', '193', 'Operational', 'RC-1440', 'No Regular Review of Follow-Up Performance', '2026-08-04 10:34:24.299886+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1441', '0.58', '2026-08-04 10:33:13.907552+00', '1536', 'text-embedding-3-small', NULL, 'Some specific follow-up messages or timings may be working much better than others, but this is never analyzed.', '["all"]', 'external', 'Stage 1→10+', '193', 'Strategic', 'RC-1441', 'Effective and Ineffective Touches Never Distinguished', '2026-08-04 10:34:24.364216+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1444', '0.85', '2026-08-04 12:57:54.606516+00', '1536', 'text-embedding-3-small', NULL, 'When a loss reason is identified, nobody is responsible for deciding what to do about it, so the finding sits without an owner to push it into action.', '["all"]', 'external', 'Stage 1→10+', '194', 'Operational', 'RC-1442', 'No Owner Assigned to Act on Loss-Analysis Findings', '2026-08-04 12:59:16.72392+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1445', '0.80', '2026-08-04 12:57:54.606516+00', '1536', 'text-embedding-3-small', NULL, 'Loss reasons get jotted in a CRM field, a notebook, or a chat message, but there is no central place anyone goes back to look at them together.', '["all"]', 'external', 'Stage 1→10+', '194', 'Operational', 'RC-1443', 'Findings Live in Scattered Notes Nobody Revisits', '2026-08-04 12:59:16.801694+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1446', '0.85', '2026-08-04 12:57:54.606516+00', '1536', 'text-embedding-3-small', NULL, 'There is no recurring meeting or check-in where lost deals and their reasons are actually discussed as a group, so findings never surface into decision-making.', '["all"]', 'external', 'Stage 1→10+', '194', 'Operational', 'RC-1444', 'No Regular Review Cadence to Discuss Lost-Deal Patterns', '2026-08-04 12:59:16.861379+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1447', '0.75', '2026-08-04 12:57:54.606516+00', '1536', 'text-embedding-3-small', NULL, 'The founder processes each lost deal individually without stepping back to ask what structural change would prevent the next several losses like it.', '["all"]', 'external', 'Stage 1→10+', '194', 'Strategic', 'RC-1445', 'Each Loss Treated as a One-Off, Not Connected to a Broader Fix', '2026-08-04 12:59:16.916289+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1448', '0.90', '2026-08-04 12:57:54.606516+00', '1536', 'text-embedding-3-small', NULL, 'Even clear, repeated loss reasons never reach the people or conversations where pricing, messaging, or product roadmap decisions are actually made.', '["all"]', 'external', 'Stage 1→10+', '194', 'Strategic', 'RC-1446', 'No Mechanism to Feed Loss Reasons Into Pricing, Positioning, or Product Decisions', '2026-08-04 12:59:16.975627+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1449', '0.70', '2026-08-04 12:57:54.606516+00', '1536', 'text-embedding-3-small', NULL, 'Acting on a loss reason can mean admitting something core needs to change, which feels threatening, so findings get downplayed or rationalized away instead of acted on.', '["all"]', 'external', 'Stage 1→10+', '194', 'Psychological', 'RC-1447', 'Fear of Admitting the Pitch or Product Needs to Change', '2026-08-04 12:59:17.048713+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1450', '0.75', '2026-08-04 12:57:54.606516+00', '1536', 'text-embedding-3-small', NULL, 'Even on the rare occasion something is changed in response to a loss reason, nobody checks afterward whether that reason actually stopped showing up — so there is no confirmation the fix worked.', '["all"]', 'external', 'Stage 1→10+', '194', 'Operational', 'RC-1448', 'No Tracking of Whether a Fix Actually Reduced That Loss Reason', '2026-08-04 12:59:17.107388+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1451', '0.85', '2026-08-04 13:01:34.397909+00', '1536', 'text-embedding-3-small', NULL, 'Once a deal closes, the founder moves on — there is no habit of asking why that particular deal worked, so only half the picture (losses) ever gets examined.', '["all"]', 'external', 'Stage 1→10+', '195', 'Operational', 'RC-1449', 'Won Deals Not Reviewed With the Same Scrutiny as Lost Ones', '2026-08-04 13:03:47.327375+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1452', '0.85', '2026-08-04 13:01:34.397909+00', '1536', 'text-embedding-3-small', NULL, 'Two deals that looked nearly identical going in — one won, one lost — are never placed next to each other to see what actually diverged.', '["all"]', 'external', 'Stage 1→10+', '195', 'Operational', 'RC-1450', 'No Side-by-Side Comparison of Similar Deals With Opposite Outcomes', '2026-08-04 13:03:47.426801+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1453', '0.75', '2026-08-04 13:01:34.397909+00', '1536', 'text-embedding-3-small', NULL, 'There is an unexamined confidence about what makes deals succeed, so the assumption is never actually checked against the data.', '["all"]', 'external', 'Stage 1→10+', '195', 'Psychological', 'RC-1451', 'Founder Assumes They Already Know Why Deals Are Won', '2026-08-04 13:03:47.498749+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1454', '0.80', '2026-08-04 13:01:34.397909+00', '1536', 'text-embedding-3-small', NULL, 'Whether the same objection was handled differently, or a different number of touchpoints occurred, is never compared across won versus lost deals.', '["all"]', 'external', 'Stage 1→10+', '195', 'Operational', 'RC-1452', 'No Comparison of How the Sales Process Itself Differed Between Wins and Losses', '2026-08-04 13:03:47.573649+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1455', '0.80', '2026-08-04 13:01:34.397909+00', '1536', 'text-embedding-3-small', NULL, 'Factors like deal size, lead source, industry, or timeline are never cross-checked between won and lost deals to look for correlations.', '["all"]', 'external', 'Stage 1→10+', '195', 'Operational', 'RC-1453', 'Deal Characteristics Not Compared Across Wins and Losses', '2026-08-04 13:03:47.644901+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1456', '0.75', '2026-08-04 13:01:34.397909+00', '1536', 'text-embedding-3-small', NULL, 'Even when a difference between wins and losses is suspected, it stays a hunch — nobody checks it against enough deals to confirm it is real.', '["all"]', 'external', 'Stage 1→10+', '195', 'Strategic', 'RC-1454', 'Suspected Differences Never Verified Against a Larger Sample', '2026-08-04 13:03:47.722894+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1457', '0.70', '2026-08-04 13:01:34.397909+00', '1536', 'text-embedding-3-small', NULL, 'Judgments about why deals are won or lost get shaped by whichever deals are most memorable, not by looking at the full set of outcomes.', '["all"]', 'external', 'Stage 1→10+', '195', 'Psychological', 'RC-1455', 'Survivorship Bias — Only Vivid or Recent Deals Are Remembered', '2026-08-04 13:03:47.787446+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1458', '0.85', '2026-08-04 13:05:55.452237+00', '1536', 'text-embedding-3-small', NULL, 'Every lost deal gets the same closed-lost label, with no way to flag that some were lost to timing or budget rather than a hard no.', '["all"]', 'external', 'Stage 1→10+', '196', 'Operational', 'RC-1456', '"Lost" Treated as a Single Permanent Status With No Timing Sub-Category', '2026-08-04 13:06:43.803796+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1459', '0.85', '2026-08-04 13:05:55.452237+00', '1536', 'text-embedding-3-small', NULL, 'Even when a deal is lost because the timing was wrong, no future date is set to circle back, so the prospect just falls off the radar.', '["all"]', 'external', 'Stage 1→10+', '196', 'Operational', 'RC-1457', 'No Re-Engagement Timeline Set for Timing-Based Losses', '2026-08-04 13:06:43.873966+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1460', '0.80', '2026-08-04 13:05:55.452237+00', '1536', 'text-embedding-3-small', NULL, 'Once marked lost, a prospect is archived or deleted rather than moved to a separate list meant for future re-approach.', '["all"]', 'external', 'Stage 1→10+', '196', 'Operational', 'RC-1458', 'Lost Prospects Removed From the Pipeline Entirely Rather Than Moved to a Nurture List', '2026-08-04 13:06:43.935173+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1461', '0.75', '2026-08-04 13:05:55.452237+00', '1536', 'text-embedding-3-small', NULL, 'There is no way to catch signals like a new budget cycle, a funding round, or a leadership change at the prospect''s company that would make it worth reaching out again.', '["all"]', 'external', 'Stage 1→10+', '196', 'Operational', 'RC-1459', 'No Trigger-Based System to Revisit a Lost Deal When Circumstances Change', '2026-08-04 13:06:43.997492+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1462', '0.75', '2026-08-04 13:05:55.452237+00', '1536', 'text-embedding-3-small', NULL, 'Reaching back out to someone who already said no feels uncomfortable or intrusive, so the founder avoids it even when the original reason for the no has likely changed.', '["all"]', 'external', 'Stage 1→10+', '196', 'Psychological', 'RC-1460', 'Founder Assumes a No Is Final and Avoids Seeming Pushy', '2026-08-04 13:06:44.050611+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1463', '0.80', '2026-08-04 13:05:55.452237+00', '1536', 'text-embedding-3-small', NULL, 'There is no recurring habit of looking back through old lost deals to decide which ones are now worth another attempt.', '["all"]', 'external', 'Stage 1→10+', '196', 'Operational', 'RC-1461', 'No Periodic Review of the Lost Pile to Identify Worthwhile Re-Approaches', '2026-08-04 13:06:44.109258+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1464', '0.70', '2026-08-04 13:05:55.452237+00', '1536', 'text-embedding-3-small', NULL, 'Because nobody tracks whether re-approaching old lost deals ever works, the value of doing it stays invisible and the practice never gets prioritized.', '["all"]', 'external', 'Stage 1→10+', '196', 'Strategic', 'RC-1462', 'No Tracking of How Often Revisited Lost Deals Actually Convert', '2026-08-04 13:06:44.16043+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1465', '0.85', '2026-08-04 13:09:04.541032+00', '1536', 'text-embedding-3-small', NULL, 'When a deal is lost to competition, the specific competitor''s name is not recorded anywhere, so there is no way to see patterns over time.', '["all"]', 'external', 'Stage 1→10+', '197', 'Operational', 'RC-1463', 'No Tracking of Which Specific Competitor Won a Lost Deal', '2026-08-04 13:09:53.172686+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1466', '0.85', '2026-08-04 13:09:04.541032+00', '1536', 'text-embedding-3-small', NULL, 'Price, features, terms, or relationship factors that tipped the decision toward a competitor are not documented, so the actual reason for the loss stays vague.', '["all"]', 'external', 'Stage 1→10+', '197', 'Operational', 'RC-1464', 'No Capture of What the Competitor Offered That Won the Deal', '2026-08-04 13:09:53.233848+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1467', '0.80', '2026-08-04 13:09:04.541032+00', '1536', 'text-embedding-3-small', NULL, 'Even if individual competitor losses are noted, nobody steps back to see whether the same competitor keeps showing up as the reason.', '["all"]', 'external', 'Stage 1→10+', '197', 'Operational', 'RC-1465', 'No Aggregation Across Losses to Spot a Recurring Competitor', '2026-08-04 13:09:53.287079+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1468', '0.70', '2026-08-04 13:09:04.541032+00', '1536', 'text-embedding-3-small', NULL, 'Beliefs about what competitors offer or why they win are based on guesswork and general market impressions, not on what actually happened in real lost deals.', '["all"]', 'external', 'Stage 1→10+', '197', 'Psychological', 'RC-1466', 'Founder Relies on Assumptions About Competitors Rather Than Direct Evidence', '2026-08-04 13:09:53.350217+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1469', '0.80', '2026-08-04 13:09:04.541032+00', '1536', 'text-embedding-3-small', NULL, 'Even when competitive loss reasons are known, they never reach the person or conversation where pricing or positioning decisions get made.', '["all"]', 'external', 'Stage 1→10+', '197', 'Strategic', 'RC-1467', 'Competitive Loss Intelligence Not Shared With Anyone Shaping Positioning or Pricing', '2026-08-04 13:09:53.406706+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1470', '0.80', '2026-08-04 13:09:04.541032+00', '1536', 'text-embedding-3-small', NULL, 'When a prospect says they are going with another option, the conversation ends there instead of asking who, what was offered, and why.', '["all"]', 'external', 'Stage 1→10+', '197', 'Behavioural', 'RC-1468', 'Sales Conversations Don''t Probe for Competitor Details When a Prospect Chooses Someone Else', '2026-08-04 13:09:53.460368+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1471', '0.75', '2026-08-04 13:09:04.541032+00', '1536', 'text-embedding-3-small', NULL, 'Even with a clear pattern of losing to a specific competitor for a specific reason, the pitch, messaging, or competitive materials are never revised to address it.', '["all"]', 'external', 'Stage 1→10+', '197', 'Strategic', 'RC-1469', 'No Update to Positioning or Battlecards Based on Real Loss Patterns', '2026-08-04 13:09:53.515479+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1472', '0.85', '2026-08-04 13:14:17.37662+00', '1536', 'text-embedding-3-small', NULL, 'When a new lead comes in, where it came from is not consistently logged, so there is no data to break conversion down by source later.', '["all"]', 'external', 'Stage 1→10+', '198', 'Operational', 'RC-1470', 'Lead Source Not Recorded at the Point of Capture', '2026-08-04 13:15:06.640036+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1473', '0.85', '2026-08-04 13:14:17.37662+00', '1536', 'text-embedding-3-small', NULL, 'Even when overall conversion rate is known, it is never split out by lead source to see which channels actually perform better.', '["all"]', 'external', 'Stage 1→10+', '198', 'Operational', 'RC-1471', 'Conversion Rate Calculated in Aggregate Only, Never Segmented by Source', '2026-08-04 13:15:06.715014+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1474', '0.75', '2026-08-04 13:14:17.37662+00', '1536', 'text-embedding-3-small', NULL, 'A cheap source that converts poorly can look efficient on cost alone if nobody weighs cost against how many of those leads actually become customers.', '["all"]', 'external', 'Stage 1→10+', '198', 'Strategic', 'RC-1472', 'No Comparison of Cost-Per-Lead Against Conversion Rate by Source', '2026-08-04 13:15:06.784748+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1475', '0.75', '2026-08-04 13:14:17.37662+00', '1536', 'text-embedding-3-small', NULL, 'Sales effort is spread across channels by habit or convenience rather than by which sources are known to convert best.', '["all"]', 'external', 'Stage 1→10+', '198', 'Operational', 'RC-1473', 'Time and Effort Allocated Evenly Across Sources Regardless of Known Quality Differences', '2026-08-04 13:15:06.845491+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1476', '0.70', '2026-08-04 13:14:17.37662+00', '1536', 'text-embedding-3-small', NULL, 'Leads with very different starting odds of converting go through the exact same process with no adjustment for the likely difference in intent.', '["all"]', 'external', 'Stage 1→10+', '198', 'Operational', 'RC-1474', 'Referral and Cold Leads Treated Identically in the Pipeline', '2026-08-04 13:15:06.910535+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1477', '0.70', '2026-08-04 13:14:17.37662+00', '1536', 'text-embedding-3-small', NULL, 'There is no working theory about which channels should outperform, so there is nothing specific to confirm or disprove with the data.', '["all"]', 'external', 'Stage 1→10+', '198', 'Strategic', 'RC-1475', 'No Hypothesis About Which Sources Should Convert Better, So Nothing Gets Tested', '2026-08-04 13:15:06.984285+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1478', '0.80', '2026-08-04 13:14:17.37662+00', '1536', 'text-embedding-3-small', NULL, 'Without source-level conversion data, a channel that is quietly wasting time or budget keeps getting used because there is no evidence to justify stopping it.', '["all"]', 'external', 'Stage 1→10+', '198', 'Strategic', 'RC-1476', 'Underperforming Sources Never Cut Because Nobody Can Prove They Underperform', '2026-08-04 13:15:07.042309+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1479', '0.85', '2026-08-04 13:17:23.486283+00', '1536', 'text-embedding-3-small', NULL, 'The time from first contact to close (or to going cold) is not measured, so there is no visibility into how long the sales process actually takes.', '["all"]', 'external', 'Stage 1→10+', '199', 'Operational', 'RC-1477', 'No Tracking of How Long Deals Stay in the Pipeline Before Closing or Being Lost', '2026-08-04 13:18:11.184118+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1480', '0.80', '2026-08-04 13:17:23.486283+00', '1536', 'text-embedding-3-small', NULL, 'There is no reference point for what a healthy amount of time in each stage looks like, so it is impossible to tell when a deal is taking too long.', '["all"]', 'external', 'Stage 1→10+', '199', 'Operational', 'RC-1478', 'No Benchmark for How Long Each Sales Stage Should Normally Take', '2026-08-04 13:18:11.251807+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1481', '0.85', '2026-08-04 13:17:23.486283+00', '1536', 'text-embedding-3-small', NULL, 'A deal that has gone quiet for weeks does not trigger any alert or follow-up action — it just sits until it is eventually forgotten or written off.', '["all"]', 'external', 'Stage 1→10+', '199', 'Operational', 'RC-1479', 'Stalled Deals Not Flagged or Escalated Once They Exceed a Normal Timeframe', '2026-08-04 13:18:11.309155+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1482', '0.75', '2026-08-04 13:17:23.486283+00', '1536', 'text-embedding-3-small', NULL, 'Whether faster-moving deals tend to close and slower ones tend to die (or vice versa) is never checked, so a potentially useful signal goes unused.', '["all"]', 'external', 'Stage 1→10+', '199', 'Strategic', 'RC-1480', 'No Comparison of Cycle Length Between Won Deals and Lost Deals', '2026-08-04 13:18:11.35975+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1483', '0.75', '2026-08-04 13:17:23.486283+00', '1536', 'text-embedding-3-small', NULL, 'Deals gradually taking longer to close is a slow, easy-to-miss trend, and without measurement it is never caught until pipeline health is already suffering.', '["all"]', 'external', 'Stage 1→10+', '199', 'Operational', 'RC-1481', 'Average Sales Cycle Length Allowed to Creep Up Over Time Without Anyone Noticing', '2026-08-04 13:18:11.410743+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1484', '0.75', '2026-08-04 13:17:23.486283+00', '1536', 'text-embedding-3-small', NULL, 'The sales process does not create any natural point where a prospect needs to decide, so deals can drift indefinitely without a forcing function.', '["all"]', 'external', 'Stage 1→10+', '199', 'Behavioural', 'RC-1482', 'No Urgency or Decision Deadlines Built Into the Sales Process Itself', '2026-08-04 13:18:11.464921+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1485', '0.70', '2026-08-04 13:17:23.486283+00', '1536', 'text-embedding-3-small', NULL, 'There is no evidence-based understanding of whether speeding up or slowing down the sales process would actually help conversion for this specific business.', '["all"]', 'external', 'Stage 1→10+', '199', 'Knowledge', 'RC-1483', 'Founder Does Not Know Whether a Faster or Slower Cycle Actually Correlates With Winning', '2026-08-04 13:18:11.515584+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1486', '0.85', '2026-08-04 13:20:45.948553+00', '1536', 'text-embedding-3-small', NULL, 'A single conversion number covers every prospect, so it is impossible to tell whether specific segments are pulling the average up or down.', '["all"]', 'external', 'Stage 1→10+', '200', 'Operational', 'RC-1484', 'Conversion Rate Only Calculated as One Blended Average', '2026-08-04 13:22:24.809379+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1487', '0.80', '2026-08-04 13:20:45.948553+00', '1536', 'text-embedding-3-small', NULL, 'Details like company size, industry, or ICP fit are not captured at intake, so there is no data to segment conversion by later.', '["all"]', 'external', 'Stage 1→10+', '200', 'Operational', 'RC-1485', 'Prospect Segment or Deal Size Not Consistently Recorded When a Lead Enters the Pipeline', '2026-08-04 13:22:24.881325+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1488', '0.80', '2026-08-04 13:20:45.948553+00', '1536', 'text-embedding-3-small', NULL, 'Prospects who closely match the ideal customer profile are never compared against those who do not, even though their conversion odds likely differ significantly.', '["all"]', 'external', 'Stage 1→10+', '200', 'Strategic', 'RC-1486', 'No Comparison of ICP-Fit Prospects Against Off-ICP Prospects', '2026-08-04 13:22:24.943627+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1489', '0.70', '2026-08-04 13:20:45.948553+00', '1536', 'text-embedding-3-small', NULL, 'There is an unexamined assumption that conversion is roughly the same across all types of prospects, so no one bothers to verify it.', '["all"]', 'external', 'Stage 1→10+', '200', 'Psychological', 'RC-1487', 'Founder Assumes All Segments Convert Similarly Without Checking', '2026-08-04 13:22:25.007083+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1490', '0.75', '2026-08-04 13:20:45.948553+00', '1536', 'text-embedding-3-small', NULL, 'Even if a segment quietly converts far better than others, nobody notices to redirect more time and attention toward it.', '["all"]', 'external', 'Stage 1→10+', '200', 'Strategic', 'RC-1488', 'High-Converting Segments Not Identified or Prioritized for More Focused Effort', '2026-08-04 13:22:25.07397+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1491', '0.75', '2026-08-04 13:20:45.948553+00', '1536', 'text-embedding-3-small', NULL, 'Segments that rarely convert keep consuming the same sales effort as everything else because there is no evidence flagging them as low-value.', '["all"]', 'external', 'Stage 1→10+', '200', 'Strategic', 'RC-1489', 'Low-Converting Segments Not Identified or Deprioritized', '2026-08-04 13:22:25.127307+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1492', '0.65', '2026-08-04 13:20:45.948553+00', '1536', 'text-embedding-3-small', NULL, 'Even as the business learns more about who its best customers actually are, the segments used to track conversion are never updated to reflect that.', '["all"]', 'external', 'Stage 1→10+', '200', 'Strategic', 'RC-1490', 'Segment Definitions Never Revisited as Understanding of Best-Fit Customer Evolves', '2026-08-04 13:22:25.183268+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1493', '0.85', '2026-08-04 13:24:40.032083+00', '1536', 'text-embedding-3-small', NULL, 'What was actually quoted or proposed to each prospect is not logged anywhere, so there is no data to analyze later.', '["all"]', 'external', 'Stage 1→10+', '201', 'Operational', 'RC-1491', 'No Record of Which Price or Package Tier Was Offered to Which Prospect', '2026-08-04 13:25:26.649871+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1494', '0.85', '2026-08-04 13:24:40.032083+00', '1536', 'text-embedding-3-small', NULL, 'Even when different offers exist, conversion is never broken down to see which one actually closes more often.', '["all"]', 'external', 'Stage 1→10+', '201', 'Operational', 'RC-1492', 'No Comparison of Conversion Rate Across Different Pricing or Package Options', '2026-08-04 13:25:26.748286+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1495', '0.80', '2026-08-04 13:24:40.032083+00', '1536', 'text-embedding-3-small', NULL, 'Discounts get handed out based on the moment or the prospect''s pushback, with no record of whether they actually changed the outcome.', '["all"]', 'external', 'Stage 1→10+', '201', 'Operational', 'RC-1493', 'Discounts Given Ad Hoc Without Tracking Whether They Increase Conversion', '2026-08-04 13:25:26.803513+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1496', '0.75', '2026-08-04 13:24:40.032083+00', '1536', 'text-embedding-3-small', NULL, 'It is never verified whether the prospect would have said yes at full price anyway, so discounting may be giving away margin for nothing.', '["all"]', 'external', 'Stage 1→10+', '201', 'Strategic', 'RC-1494', 'No Test of Full Price Versus Discounted Price to See If the Discount Was Necessary', '2026-08-04 13:25:26.870876+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1497', '0.70', '2026-08-04 13:24:40.032083+00', '1536', 'text-embedding-3-small', NULL, 'Which package gets pitched to a given prospect depends on habit or gut feel in the moment, not on evidence of what fits or converts best.', '["all"]', 'external', 'Stage 1→10+', '201', 'Behavioural', 'RC-1495', 'Package or Tier Chosen at Random or by Founder Preference Rather Than Data', '2026-08-04 13:25:26.920021+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1498', '0.75', '2026-08-04 13:24:40.032083+00', '1536', 'text-embedding-3-small', NULL, 'There is no data-backed answer to whether this specific business converts better leading with a premium offer or a lower-cost entry point.', '["all"]', 'external', 'Stage 1→10+', '201', 'Knowledge', 'RC-1496', 'No Visibility Into Whether Higher-Priced or Lower-Priced Offers Convert Better', '2026-08-04 13:25:26.984281+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1499', '0.70', '2026-08-04 13:24:40.032083+00', '1536', 'text-embedding-3-small', NULL, 'Price gets blamed by default when a deal is lost, without checking whether pricing was actually the reason or just the easiest explanation.', '["all"]', 'external', 'Stage 1→10+', '201', 'Psychological', 'RC-1497', 'Founder Assumes Price Is the Deciding Factor Without Verifying It', '2026-08-04 13:25:27.035201+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1500', '0.85', '2026-08-04 13:27:55.489164+00', '1536', 'text-embedding-3-small', NULL, 'There is no record or ongoing view of a customer''s evolving needs beyond what they originally bought, so expansion opportunities are invisible.', '["all"]', 'external', 'Stage 1→10+', '202', 'Operational', 'RC-1498', 'No Tracking of What Else a Given Customer Might Need', '2026-08-04 13:28:45.437699+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1501', '0.80', '2026-08-04 13:27:55.489164+00', '1536', 'text-embedding-3-small', NULL, 'A founder may notice in passing that a customer could use more, but it never turns into an actual offer or conversation.', '["all"]', 'external', 'Stage 1→10+', '202', 'Behavioural', 'RC-1499', 'Expansion Opportunities Noticed Informally but Never Acted On', '2026-08-04 13:28:45.493411+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1502', '0.80', '2026-08-04 13:27:55.489164+00', '1536', 'text-embedding-3-small', NULL, 'There is no way to systematically flag which customers show signs of being ready to expand, so opportunities are found by luck rather than process.', '["all"]', 'external', 'Stage 1→10+', '202', 'Operational', 'RC-1500', 'No Process for Identifying Which Customers Are Ready for More', '2026-08-04 13:28:45.543572+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1503', '0.75', '2026-08-04 13:27:55.489164+00', '1536', 'text-embedding-3-small', NULL, 'Even scheduled customer conversations never include a moment to explore whether more value could be delivered and sold.', '["all"]', 'external', 'Stage 1→10+', '202', 'Behavioural', 'RC-1501', 'Check-Ins With Customers Stay Purely Relationship Maintenance', '2026-08-04 13:28:45.726662+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1504', '0.80', '2026-08-04 13:27:55.489164+00', '1536', 'text-embedding-3-small', NULL, 'There is nothing specific and ready to pitch to an existing customer — no packaged next step exists to offer even if the moment arises.', '["all"]', 'external', 'Stage 1→10+', '202', 'Operational', 'RC-1502', 'No Upsell or Cross-Sell Offer Ever Formally Prepared', '2026-08-04 13:28:45.776053+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1505', '0.70', '2026-08-04 13:27:55.489164+00', '1536', 'text-embedding-3-small', NULL, 'Asking someone who already trusts and pays you for more can feel like pushing your luck, so the ask gets avoided even when it is warranted.', '["all"]', 'external', 'Stage 1→10+', '202', 'Psychological', 'RC-1503', 'Founder Feels Awkward Asking an Existing Customer for More Business', '2026-08-04 13:28:45.824536+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1506', '0.75', '2026-08-04 13:27:55.489164+00', '1536', 'text-embedding-3-small', NULL, 'Revenue from existing customers buying more is not distinguished from new-customer revenue, so there is no way to see whether expansion is happening at all.', '["all"]', 'external', 'Stage 1→10+', '202', 'Operational', 'RC-1504', 'Expansion Revenue Not Tracked Separately, So It Stays Invisible', '2026-08-04 13:28:45.872763+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1507', '0.85', '2026-08-04 13:31:45.161559+00', '1536', 'text-embedding-3-small', NULL, 'Complaints or problems raised by customers are not written down anywhere consistent, so they exist only in whoever happened to receive them.', '["all"]', 'external', 'Stage 1→10+', '203', 'Operational', 'RC-1505', 'No System for Logging When a Customer Raises an Issue', '2026-08-04 13:32:36.266432+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1508', '0.80', '2026-08-04 13:31:45.161559+00', '1536', 'text-embedding-3-small', NULL, 'Once a complaint comes in, there is no measurement of the time from report to resolution, so slow or stalled issues go unnoticed.', '["all"]', 'external', 'Stage 1→10+', '203', 'Operational', 'RC-1506', 'No Tracking of How Long Issues Take to Resolve', '2026-08-04 13:32:36.332587+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1509', '0.75', '2026-08-04 13:31:45.161559+00', '1536', 'text-embedding-3-small', NULL, 'There is no consistent process for handling a complaint — it gets resolved differently depending on who deals with it and how much time they have.', '["all"]', 'external', 'Stage 1→10+', '203', 'Operational', 'RC-1507', 'Issue Resolution Depends Entirely on Whoever Happens to Be Available', '2026-08-04 13:32:36.393459+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1510', '0.80', '2026-08-04 13:31:45.161559+00', '1536', 'text-embedding-3-small', NULL, 'Complaints are not tagged or grouped by type, so nobody can see that the same issue keeps coming up across different customers.', '["all"]', 'external', 'Stage 1→10+', '203', 'Operational', 'RC-1508', 'No Categorization of Complaint Types, So Recurring Issues Go Unnoticed', '2026-08-04 13:32:36.452626+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1511', '0.75', '2026-08-04 13:31:45.161559+00', '1536', 'text-embedding-3-small', NULL, 'Once something is marked handled internally, there is no check-back with the customer to confirm they are actually satisfied with the outcome.', '["all"]', 'external', 'Stage 1→10+', '203', 'Operational', 'RC-1509', 'No Follow-Up With the Customer to Confirm the Issue Was Actually Resolved', '2026-08-04 13:32:36.511347+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1512', '0.80', '2026-08-04 13:31:45.161559+00', '1536', 'text-embedding-3-small', NULL, 'Each instance of a repeating complaint gets patched individually rather than the underlying product, process, or communication issue being addressed.', '["all"]', 'external', 'Stage 1→10+', '203', 'Strategic', 'RC-1510', 'Root Cause of a Recurring Complaint Never Gets Fixed, Only the Symptom', '2026-08-04 13:32:36.568589+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1513', '0.70', '2026-08-04 13:31:45.161559+00', '1536', 'text-embedding-3-small', NULL, 'When a complaint is too big or sensitive for normal handling, there is no defined way for it to be flagged and handled with more urgency or seniority.', '["all"]', 'external', 'Stage 1→10+', '203', 'Operational', 'RC-1511', 'No Escalation Path for Serious or Unresolved Issues', '2026-08-04 13:32:36.62918+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1514', '0.80', '2026-08-04 13:34:36.848326+00', '1536', 'text-embedding-3-small', NULL, 'There is no way to flag which customers are clearly happy and therefore good candidates for a referral or testimonial ask.', '["all"]', 'external', 'Stage 1→10+', '204', 'Operational', 'RC-1512', 'No System for Identifying Which Customers Are Satisfied Enough to Ask', '2026-08-04 13:35:23.650533+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1515', '0.85', '2026-08-04 13:34:36.848326+00', '1536', 'text-embedding-3-small', NULL, 'Even during check-ins or positive moments, there is no built-in point where asking for a referral or review naturally happens.', '["all"]', 'external', 'Stage 1→10+', '204', 'Operational', 'RC-1513', 'Referral or Testimonial Ask Never Built Into Any Regular Customer Touchpoint', '2026-08-04 13:35:23.73394+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1516', '0.75', '2026-08-04 13:34:36.848326+00', '1536', 'text-embedding-3-small', NULL, 'Asking a satisfied customer for something in return feels like it could sour the relationship, so the ask gets avoided.', '["all"]', 'external', 'Stage 1→10+', '204', 'Psychological', 'RC-1514', 'Founder Feels Awkward or Transactional Asking a Happy Customer for a Favor', '2026-08-04 13:35:23.792528+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1517', '0.75', '2026-08-04 13:34:36.848326+00', '1536', 'text-embedding-3-small', NULL, 'There is no simple template, link, or process ready to hand a willing customer, so even a "yes" turns into friction.', '["all"]', 'external', 'Stage 1→10+', '204', 'Operational', 'RC-1515', 'No Easy Way for the Customer to Give a Referral or Testimonial Even If Willing', '2026-08-04 13:35:23.845294+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1518', '0.70', '2026-08-04 13:34:36.848326+00', '1536', 'text-embedding-3-small', NULL, 'When a referral does come in naturally, it is not recorded as such, so there is no visibility into how much of the business actually comes from referrals.', '["all"]', 'external', 'Stage 1→10+', '204', 'Operational', 'RC-1516', 'Organic Referrals Not Tracked, So Their Volume and Value Stay Invisible', '2026-08-04 13:35:23.901863+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1519', '0.70', '2026-08-04 13:34:36.848326+00', '1536', 'text-embedding-3-small', NULL, 'There is nothing — even a small thank-you or simple structure — that makes referring feel worthwhile or easy for the customer.', '["all"]', 'external', 'Stage 1→10+', '204', 'Strategic', 'RC-1517', 'No Incentive or Ask Structure to Make Referring Easy or Motivating', '2026-08-04 13:35:23.959373+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1520', '0.70', '2026-08-04 13:34:36.848326+00', '1536', 'text-embedding-3-small', NULL, 'Positive feedback given informally is never converted into a usable testimonial or case study, so it goes to waste.', '["all"]', 'external', 'Stage 1→10+', '204', 'Operational', 'RC-1518', 'Testimonials or Case Studies Never Collected Even When a Customer Would Have Said Yes', '2026-08-04 13:35:24.017894+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1521', '0.85', '2026-08-04 13:37:33.052371+00', '1536', 'text-embedding-3-small', NULL, 'There is no single source of truth for when each customer is due to renew, so nothing prompts action ahead of time.', '["all"]', 'external', 'Stage 1→10+', '205', 'Operational', 'RC-1519', 'Renewal or Contract End Dates Not Tracked in One Place', '2026-08-04 13:38:19.860628+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1522', '0.85', '2026-08-04 13:37:33.052371+00', '1536', 'text-embedding-3-small', NULL, 'Customers are not proactively contacted ahead of their renewal date, so the first conversation about renewal often happens too late.', '["all"]', 'external', 'Stage 1→10+', '205', 'Operational', 'RC-1520', 'No Advance-Notice Outreach Before a Renewal Comes Due', '2026-08-04 13:38:19.937906+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1523', '0.80', '2026-08-04 13:37:33.052371+00', '1536', 'text-embedding-3-small', NULL, 'The renewal process is entirely reactive, triggered only by a customer taking negative action rather than by a proactive checkpoint.', '["all"]', 'external', 'Stage 1→10+', '205', 'Operational', 'RC-1521', 'Renewals Only Get Attention When a Customer Cancels or a Payment Fails', '2026-08-04 13:38:19.992738+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1524', '0.80', '2026-08-04 13:37:33.052371+00', '1536', 'text-embedding-3-small', NULL, 'There is no way to flag which upcoming renewals are likely to be lost, so at-risk accounts get the same treatment as healthy ones until it is too late.', '["all"]', 'external', 'Stage 1→10+', '205', 'Operational', 'RC-1522', 'No Process for Identifying At-Risk Renewals Ahead of the Renewal Date', '2026-08-04 13:38:20.049009+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1525', '0.75', '2026-08-04 13:37:33.052371+00', '1536', 'text-embedding-3-small', NULL, 'What proportion of customers actually renew is never calculated, so there is no baseline to know if renewal performance is good, bad, or changing.', '["all"]', 'external', 'Stage 1→10+', '205', 'Operational', 'RC-1523', 'No Tracking of Renewal Rate as a Measurable Number', '2026-08-04 13:38:20.118456+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1526', '0.70', '2026-08-04 13:37:33.052371+00', '1536', 'text-embedding-3-small', NULL, 'Price, scope, or terms are not deliberately reviewed at renewal — the contract just rolls over or gets handled inconsistently case by case.', '["all"]', 'external', 'Stage 1→10+', '205', 'Strategic', 'RC-1524', 'Renewal Terms Never Revisited, Just Auto-Continued or Handled Ad Hoc', '2026-08-04 13:38:20.271745+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1527', '0.75', '2026-08-04 13:37:33.052371+00', '1536', 'text-embedding-3-small', NULL, 'Every renewal gets the same generic treatment regardless of how the relationship is actually going, missing the chance to intervene where it matters most.', '["all"]', 'external', 'Stage 1→10+', '205', 'Strategic', 'RC-1525', 'No Differentiation in Renewal Approach Between Healthy and At-Risk Accounts', '2026-08-04 13:38:20.329358+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1528', '0.85', '2026-08-04 13:58:05.279059+00', '1536', 'text-embedding-3-small', NULL, 'The calendar gets filled with topics on a schedule, without reference to what the business is actually trying to accomplish that period.', '["all"]', 'external', 'Stage 0→1', '206', 'Strategic', 'RC-1526', 'Content Calendar Built Independently of Any Marketing Campaign or Business Objective', '2026-08-04 13:58:52.427724+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1529', '0.85', '2026-08-04 13:58:05.279059+00', '1536', 'text-embedding-3-small', NULL, 'Even known upcoming business moments are not deliberately reflected in the content plan ahead of time.', '["all"]', 'external', 'Stage 0→1', '206', 'Operational', 'RC-1527', 'No Mapping of Content to Specific Launches, Promotions, or Seasonal Moments', '2026-08-04 13:58:52.50649+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1530', '0.80', '2026-08-04 13:58:05.279059+00', '1536', 'text-embedding-3-small', NULL, 'What gets posted is decided in isolation from whatever the business is focused on achieving that month or quarter.', '["all"]', 'external', 'Stage 0→1', '206', 'Strategic', 'RC-1528', 'Content Topics Chosen Without Reference to That Period''s Business Priorities', '2026-08-04 13:58:52.566742+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1531', '0.75', '2026-08-04 13:58:05.279059+00', '1536', 'text-embedding-3-small', NULL, 'Content is not deliberately mapped to awareness, consideration, or decision-stage purposes, so it is unclear what job any given piece is doing.', '["all"]', 'external', 'Stage 0→1', '206', 'Strategic', 'RC-1529', 'No One Connects the Content Calendar to the Funnel Stage It Is Meant to Serve', '2026-08-04 13:58:52.62311+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1532', '0.80', '2026-08-04 13:58:05.279059+00', '1536', 'text-embedding-3-small', NULL, 'A new product, offer, or market change does not trigger any update to the existing content plan — it keeps running on autopilot.', '["all"]', 'external', 'Stage 0→1', '206', 'Operational', 'RC-1530', 'Content Calendar Never Revisited When Business Priorities Shift', '2026-08-04 13:58:52.673805+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1533', '0.75', '2026-08-04 13:58:05.279059+00', '1536', 'text-embedding-3-small', NULL, 'There is no concept of temporarily increasing content output or focus around a launch or promotion — everything stays at the same steady pace.', '["all"]', 'external', 'Stage 0→1', '206', 'Operational', 'RC-1531', 'No Campaign-Specific Content Bursts Planned Around Key Business Moments', '2026-08-04 13:58:52.723695+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1534', '0.70', '2026-08-04 13:58:05.279059+00', '1536', 'text-embedding-3-small', NULL, 'Even when the business clearly needs more visibility around a specific moment, content volume and focus do not increase to match.', '["all"]', 'external', 'Stage 0→1', '206', 'Operational', 'RC-1532', 'Content Output Stays Flat Even During Major Business Moments That Would Benefit From a Push', '2026-08-04 13:58:52.774921+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1535', '0.80', '2026-08-04 14:01:05.772581+00', '1536', 'text-embedding-3-small', NULL, 'Platforms are chosen by habit or convenience rather than by where the actual target audience spends their time.', '["all"]', 'external', 'Stage 0→1', '207', 'Strategic', 'RC-1533', 'No Consideration of Which Platforms the Target Audience Actually Uses', '2026-08-04 14:01:58.413526+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1536', '0.85', '2026-08-04 14:01:05.772581+00', '1536', 'text-embedding-3-small', NULL, 'A single piece of content is posted identically everywhere, ignoring that each platform has different norms and expectations.', '["all"]', 'external', 'Stage 0→1', '207', 'Operational', 'RC-1534', 'Same Content Copy-Pasted Across Every Platform Without Adaptation', '2026-08-04 14:01:58.482654+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1537', '0.80', '2026-08-04 14:01:05.772581+00', '1536', 'text-embedding-3-small', NULL, 'The same format (e.g. static image or long text) is used regardless of whether a platform favors video, short-form, or something else entirely.', '["all"]', 'external', 'Stage 0→1', '207', 'Operational', 'RC-1535', 'No Format Variation Planned by Platform', '2026-08-04 14:01:58.54223+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1538', '0.75', '2026-08-04 14:01:05.772581+00', '1536', 'text-embedding-3-small', NULL, 'Every channel gets the same posting frequency, even though optimal cadence differs significantly by platform.', '["all"]', 'external', 'Stage 0→1', '207', 'Operational', 'RC-1536', 'No Platform-Specific Posting Cadence', '2026-08-04 14:01:58.602764+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1539', '0.80', '2026-08-04 14:01:05.772581+00', '1536', 'text-embedding-3-small', NULL, 'Performance is not compared across platforms, so effort keeps getting spread evenly instead of toward what works.', '["all"]', 'external', 'Stage 0→1', '207', 'Operational', 'RC-1537', 'No Tracking of Which Platform Actually Drives Results', '2026-08-04 14:01:58.659975+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1540', '0.70', '2026-08-04 14:01:05.772581+00', '1536', 'text-embedding-3-small', NULL, 'The planning tool or document treats content as one undifferentiated stream rather than separate plans tailored to each platform.', '["all"]', 'external', 'Stage 0→1', '207', 'Operational', 'RC-1538', 'Content Calendar Has One Track Instead of Per-Platform Tracks', '2026-08-04 14:01:58.711233+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1541', '0.70', '2026-08-04 14:01:05.772581+00', '1536', 'text-embedding-3-small', NULL, 'There is little understanding of what each platform''s algorithm currently favors or what formats are trending there, so content misses easy opportunities.', '["all"]', 'external', 'Stage 0→1', '207', 'Knowledge', 'RC-1539', 'No Awareness of Platform-Specific Trends or Algorithm Preferences', '2026-08-04 14:01:58.764451+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1542', '0.85', '2026-08-04 14:05:21.291935+00', '1536', 'text-embedding-3-small', NULL, 'Planning, when it happens, is done in the moment rather than as a regular practice with a real lead time.', '["all"]', 'external', 'Stage 0→1', '208', 'Operational', 'RC-1540', 'No Standing Habit of Planning Content Weeks or a Month Ahead', '2026-08-04 14:06:09.351189+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1543', '0.80', '2026-08-04 14:05:21.291935+00', '1536', 'text-embedding-3-small', NULL, 'Ideas surface when something is due immediately, not as part of calm, unhurried planning ahead of time.', '["all"]', 'external', 'Stage 0→1', '208', 'Behavioural', 'RC-1541', 'Content Ideas Only Generated Under the Pressure of an Imminent Deadline', '2026-08-04 14:06:09.415673+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1544', '0.75', '2026-08-04 14:05:21.291935+00', '1536', 'text-embedding-3-small', NULL, 'Content is made one piece at a time right before it is needed, rather than produced in efficient batches ahead of schedule.', '["all"]', 'external', 'Stage 0→1', '208', 'Operational', 'RC-1542', 'No Batch-Production Process to Create Multiple Pieces in One Sitting', '2026-08-04 14:06:09.46512+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1545', '0.80', '2026-08-04 14:05:21.291935+00', '1536', 'text-embedding-3-small', NULL, 'There is nothing already prepared to fall back on when time is tight, so busy weeks mean content simply does not go out.', '["all"]', 'external', 'Stage 0→1', '208', 'Operational', 'RC-1543', 'No Buffer of Ready-to-Publish Content for Busy Weeks', '2026-08-04 14:06:09.515474+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1546', '0.75', '2026-08-04 14:05:21.291935+00', '1536', 'text-embedding-3-small', NULL, 'Under pressure, the little planning that does happen gets cut first, making the whole system even more reactive.', '["all"]', 'external', 'Stage 0→1', '208', 'Behavioural', 'RC-1544', 'Planning Horizon Shrinks Further Whenever the Founder Gets Busy', '2026-08-04 14:06:09.577284+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1547', '0.70', '2026-08-04 14:05:21.291935+00', '1536', 'text-embedding-3-small', NULL, 'Because there is no forward view of the plan, last-minute content creation feels like the default way things work rather than a warning sign.', '["all"]', 'external', 'Stage 0→1', '208', 'Psychological', 'RC-1545', 'No Advance Visibility Into What Is Coming, So Scrambling Feels Normal', '2026-08-04 14:06:09.630391+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1548', '0.75', '2026-08-04 14:05:21.291935+00', '1536', 'text-embedding-3-small', NULL, 'Partnerships, seasonal tie-ins, or coordinated launches that need advance preparation get missed entirely because planning never looks far enough ahead.', '["all"]', 'external', 'Stage 0→1', '208', 'Strategic', 'RC-1546', 'Missed Opportunities That Require Lead Time', '2026-08-04 14:06:09.693129+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1549', '0.80', '2026-08-04 14:08:21.664763+00', '1536', 'text-embedding-3-small', NULL, 'There is no list or calendar of dates that matter to the audience or industry, so nothing prompts planning around them.', '["all"]', 'external', 'Stage 0→1', '209', 'Operational', 'RC-1547', 'No Tracking of Relevant Holidays, Awareness Days, or Seasonal Moments', '2026-08-04 14:09:13.682511+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1550', '0.80', '2026-08-04 14:08:21.664763+00', '1536', 'text-embedding-3-small', NULL, 'Even where a relevant date is known, content for it is not prepared ahead of time.', '["all"]', 'external', 'Stage 0→1', '209', 'Operational', 'RC-1548', 'No Advance Planning Around Known Seasonal or Industry Dates', '2026-08-04 14:09:13.752284+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1551', '0.75', '2026-08-04 14:08:21.664763+00', '1536', 'text-embedding-3-small', NULL, 'The same type of content goes out no matter what season, holiday, or industry moment is happening around it.', '["all"]', 'external', 'Stage 0→1', '209', 'Operational', 'RC-1549', 'Content Stays Generic Regardless of Time of Year', '2026-08-04 14:09:13.812512+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1552', '0.65', '2026-08-04 14:08:21.664763+00', '1536', 'text-embedding-3-small', NULL, 'There is little visibility into how competitors or peers are using seasonal moments, missing easy inspiration and benchmarking.', '["all"]', 'external', 'Stage 0→1', '209', 'Knowledge', 'RC-1550', 'No Awareness of What Others in the Space Are Doing Around Seasonal Moments', '2026-08-04 14:09:13.87437+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1553', '0.70', '2026-08-04 14:08:21.664763+00', '1536', 'text-embedding-3-small', NULL, 'Conferences, launches, or industry-wide moments that the audience is paying attention to are not reflected in the content calendar.', '["all"]', 'external', 'Stage 0→1', '209', 'Operational', 'RC-1551', 'Relevant Industry Events Not Factored Into the Content Plan', '2026-08-04 14:09:13.940312+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1554', '0.75', '2026-08-04 14:08:21.664763+00', '1536', 'text-embedding-3-small', NULL, 'A relevant moment gets recognized in hindsight, after the window to create timely content for it has already closed.', '["all"]', 'external', 'Stage 0→1', '209', 'Behavioural', 'RC-1552', 'Seasonal Opportunities Noticed Only After They Have Already Passed', '2026-08-04 14:09:14.005475+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1555', '0.65', '2026-08-04 14:08:21.664763+00', '1536', 'text-embedding-3-small', NULL, 'Each seasonal moment is figured out from scratch rather than drawing on a growing list of ideas built from past experience.', '["all"]', 'external', 'Stage 0→1', '209', 'Operational', 'RC-1553', 'No Repository of Go-To Seasonal Content Ideas Built Up Over Time', '2026-08-04 14:09:14.063134+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1556', '0.85', '2026-08-04 14:11:32.866643+00', '1536', 'text-embedding-3-small', NULL, 'Real questions and objections that come up while selling are not written down anywhere, so they disappear after the conversation ends.', '["all"]', 'external', 'Stage 0→1', '210', 'Operational', 'RC-1554', 'No System for Capturing Questions or Objections From Sales Conversations', '2026-08-04 14:12:32.825636+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1557', '0.80', '2026-08-04 14:11:32.866643+00', '1536', 'text-embedding-3-small', NULL, 'Support conversations surface exactly what customers are confused about or struggling with, but none of it is recorded for later use.', '["all"]', 'external', 'Stage 0→1', '210', 'Operational', 'RC-1555', 'No System for Capturing Questions From Customer Support Interactions', '2026-08-04 14:12:32.911185+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1558', '0.80', '2026-08-04 14:11:32.866643+00', '1536', 'text-embedding-3-small', NULL, 'Rather than mining actual conversations, content ideas are invented in isolation, disconnected from what customers are really asking.', '["all"]', 'external', 'Stage 0→1', '210', 'Behavioural', 'RC-1556', 'Content Topics Guessed From Scratch Instead of Drawn From Real Interactions', '2026-08-04 14:12:32.984385+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1559', '0.75', '2026-08-04 14:11:32.866643+00', '1536', 'text-embedding-3-small', NULL, 'Even if questions were occasionally noted, there is no habit of periodically reviewing them to generate content ideas.', '["all"]', 'external', 'Stage 0→1', '210', 'Operational', 'RC-1557', 'No Regular Review of Captured Questions to Turn Into Content', '2026-08-04 14:12:33.046518+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1560', '0.75', '2026-08-04 14:11:32.866643+00', '1536', 'text-embedding-3-small', NULL, 'The people having sales or support conversations and the person creating content are disconnected, with nothing bridging the two.', '["all"]', 'external', 'Stage 0→1', '210', 'Operational', 'RC-1558', 'No One Responsible for Connecting Customer-Facing Conversations to Content Creation', '2026-08-04 14:12:33.106772+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1561', '0.75', '2026-08-04 14:11:32.866643+00', '1536', 'text-embedding-3-small', NULL, 'When the same question comes up repeatedly, it is not recognized as strong evidence that content addressing it would resonate widely.', '["all"]', 'external', 'Stage 0→1', '210', 'Strategic', 'RC-1559', 'Recurring Questions Not Recognized as Signals of High-Value Content Topics', '2026-08-04 14:12:33.162967+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1562', '0.65', '2026-08-04 14:11:32.866643+00', '1536', 'text-embedding-3-small', NULL, 'Ordinary customer conversations are not seen as a content goldmine, so no deliberate effort is made to tap into them.', '["all"]', 'external', 'Stage 0→1', '210', 'Psychological', 'RC-1560', 'Founder Underestimates How Much Content Value Exists in Everyday Conversations', '2026-08-04 14:12:33.219948+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1563', '0.85', '2026-08-04 14:52:42.210866+00', '1536', 'text-embedding-3-small', NULL, 'There is no written reference defining how the brand should sound, so voice is decided fresh, inconsistently, each time.', '["all"]', 'external', 'Stage 0→1', '211', 'Strategic', 'RC-1561', 'No Documented Brand Voice or Tone Guidelines Exist', '2026-08-04 14:53:41.656195+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1564', '0.80', '2026-08-04 14:52:42.210866+00', '1536', 'text-embedding-3-small', NULL, 'Without a standard to follow, tone drifts based on whoever is writing and how they happen to feel in the moment.', '["all"]', 'external', 'Stage 0→1', '211', 'Behavioural', 'RC-1562', 'Content Style Varies Depending on Who Creates It or Their Mood That Day', '2026-08-04 14:53:41.763549+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1565', '0.75', '2026-08-04 14:52:42.210866+00', '1536', 'text-embedding-3-small', NULL, 'There is nothing to point to as "this is what our content should sound like," so each new piece starts from a blank slate.', '["all"]', 'external', 'Stage 0→1', '211', 'Operational', 'RC-1563', 'No Reference Examples of On-Voice Content to Guide Future Creation', '2026-08-04 14:53:41.835894+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1566', '0.75', '2026-08-04 14:52:42.210866+00', '1536', 'text-embedding-3-small', NULL, 'Voice and tone have never been treated as a deliberate choice to make — it just happens by default rather than by design.', '["all"]', 'external', 'Stage 0→1', '211', 'Strategic', 'RC-1564', 'Brand Voice Never Explicitly Discussed or Defined as a Business Decision', '2026-08-04 14:53:41.902117+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1567', '0.75', '2026-08-04 14:52:42.210866+00', '1536', 'text-embedding-3-small', NULL, 'Without a deliberate standard, the same brand sounds buttoned-up in one piece and casual in another, with no clear reason for the difference.', '["all"]', 'external', 'Stage 0→1', '211', 'Operational', 'RC-1565', 'Tone Shifts Unintentionally Between Formal and Casual', '2026-08-04 14:53:41.959372+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1568', '0.70', '2026-08-04 14:52:42.210866+00', '1536', 'text-embedding-3-small', NULL, 'Even if a voice were defined, there is no step in the process that checks new content against it before publishing.', '["all"]', 'external', 'Stage 0→1', '211', 'Operational', 'RC-1566', 'No Review Step Checking Whether New Content Matches the Intended Voice', '2026-08-04 14:53:42.018283+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1569', '0.65', '2026-08-04 14:52:42.210866+00', '1536', 'text-embedding-3-small', NULL, 'When more than one person creates content, their individual styles show through unfiltered, making the brand sound like several different voices.', '["all"]', 'external', 'Stage 0→1', '211', 'Operational', 'RC-1567', 'Multiple Content Creators Produce Noticeably Different-Sounding Pieces', '2026-08-04 14:53:42.086139+00') on conflict do nothing;
