insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1571', '0.80', '2026-08-04 14:55:52.644908+00', '1536', 'text-embedding-3-small', NULL, 'Previously created visual material is not saved anywhere organized, so it cannot be found or reused later.', '["all"]', 'external', 'Stage 0→1', '212', 'Operational', 'RC-1569', 'No Repository of Past Photos, Graphics, or Video Clips Available to Reuse', '2026-08-04 14:56:43.538315+00') on conflict do nothing;
