insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1578', '0.80', '2026-08-04 14:58:59.391437+00', '1536', 'text-embedding-3-small', NULL, 'As soon as writing or design is done, it goes live immediately, without any time set aside to revisit it with fresh eyes.', '["all"]', 'external', 'Stage 0→1', '213', 'Behavioural', 'RC-1576', 'Content Published the Moment It Is Finished, With No Gap for a Second Look', '2026-08-04 15:04:02.828377+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1579', '0.75', '2026-08-04 14:58:59.391437+00', '1536', 'text-embedding-3-small', NULL, 'Content is created and published by the same person with no outside eyes ever checking it beforehand.', '["all"]', 'external', 'Stage 0→1', '213', 'Operational', 'RC-1577', 'No Second Person Ever Reviews Content Before It Goes Out', '2026-08-04 15:04:02.906193+00') on conflict do nothing;
