insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1581', '0.75', '2026-08-04 14:58:59.391437+00', '1536', 'text-embedding-3-small', NULL, 'There is nothing to prompt a check of links, claims, formatting, or other easy-to-miss details before content goes out.', '["all"]', 'external', 'Stage 0→1', '213', 'Operational', 'RC-1579', 'No Checklist of Things to Verify Before Publishing', '2026-08-04 15:04:03.027925+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1582', '0.75', '2026-08-04 14:58:59.391437+00', '1536', 'text-embedding-3-small', NULL, 'Under a deadline, review is the first step to get cut, even in cases where it would otherwise be part of the process.', '["all"]', 'external', 'Stage 0→1', '213', 'Behavioural', 'RC-1580', 'Time Pressure Leads to Skipping Review Even When It Would Normally Happen', '2026-08-04 15:04:03.089991+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1583', '0.65', '2026-08-04 14:58:59.391437+00', '1536', 'text-embedding-3-small', NULL, 'Reviewing content before publishing is seen as a low-value extra step rather than a meaningful safeguard, so it gets deprioritized.', '["all"]', 'external', 'Stage 0→1', '213', 'Psychological', 'RC-1581', 'Founder Does Not View a Quick Review Pass as Worth the Extra Time', '2026-08-04 15:04:03.156947+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1584', '0.85', '2026-08-04 15:06:45.898864+00', '1536', 'text-embedding-3-small', NULL, 'The campaign launches without any dedicated page built to receive and convert the traffic it generates.', '["all"]', 'external', 'Stage 0→1', '214', 'Operational', 'RC-1582', 'No Landing Page Created Specifically for the Campaign', '2026-08-04 15:07:40.92092+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1585', '0.85', '2026-08-04 15:06:45.898864+00', '1536', 'text-embedding-3-small', NULL, 'Clicking through leads to a general homepage or contact page that does not reflect what the campaign was actually about.', '["all"]', 'external', 'Stage 0→1', '214', 'Operational', 'RC-1583', 'Traffic Sent to a Generic Page Unrelated to the Specific Campaign Message', '2026-08-04 15:07:41.001175+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1586', '0.80', '2026-08-04 15:06:45.898864+00', '1536', 'text-embedding-3-small', NULL, 'Once someone arrives, there is nothing obvious telling them what to do next, so momentum is lost.', '["all"]', 'external', 'Stage 0→1', '214', 'Operational', 'RC-1584', 'No Clear Next Step or Call-to-Action on the Landing Page', '2026-08-04 15:07:41.156984+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1587', '0.80', '2026-08-04 15:06:45.898864+00', '1536', 'text-embedding-3-small', NULL, 'A mismatch between what got someone to click and what they actually see breaks trust and drops conversion.', '["all"]', 'external', 'Stage 0→1', '214', 'Strategic', 'RC-1585', 'Landing Page Message Does Not Match What the Ad or Promotion Promised', '2026-08-04 15:07:41.212214+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1588', '0.75', '2026-08-04 15:06:45.898864+00', '1536', 'text-embedding-3-small', NULL, 'Even where a landing page exists, there is no way to see how many visitors actually convert once they arrive.', '["all"]', 'external', 'Stage 0→1', '214', 'Operational', 'RC-1586', 'No Tracking Set Up to Measure Conversion on the Landing Page', '2026-08-04 15:07:41.264479+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1589', '0.70', '2026-08-04 15:06:45.898864+00', '1536', 'text-embedding-3-small', NULL, 'One default page gets reused for every campaign, even when the offer or message is completely different each time.', '["all"]', 'external', 'Stage 0→1', '214', 'Operational', 'RC-1587', 'Same Generic Page Used Across Every Campaign Regardless of Offer', '2026-08-04 15:07:41.319456+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1590', '0.70', '2026-08-04 15:06:45.898864+00', '1536', 'text-embedding-3-small', NULL, 'There is nothing prepared for the moment right after conversion — no thank-you step, no next action, no follow-up trigger.', '["all"]', 'external', 'Stage 0→1', '214', 'Operational', 'RC-1588', 'No Plan for What Happens Immediately After Someone Converts', '2026-08-04 15:07:41.378245+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1591', '0.85', '2026-08-04 15:09:59.477543+00', '1536', 'text-embedding-3-small', NULL, 'Whoever is responsible for handling leads has no advance notice that a campaign is about to start generating them.', '["all"]', 'external', 'Stage 0→1', '215', 'Operational', 'RC-1589', 'Sales or Follow-Up Person Not Informed a Campaign Is Launching', '2026-08-04 15:10:51.057912+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1592', '0.85', '2026-08-04 15:09:59.477543+00', '1536', 'text-embedding-3-small', NULL, 'Follow-up conversations do not match what the campaign actually promised, because the person following up never saw the campaign material.', '["all"]', 'external', 'Stage 0→1', '215', 'Operational', 'RC-1590', 'Sales Unaware of the Campaign''s Specific Messaging or Offer', '2026-08-04 15:10:51.13309+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1593', '0.75', '2026-08-04 15:09:59.477543+00', '1536', 'text-embedding-3-small', NULL, 'Nobody has a sense of how many leads to expect, so there is no way to prepare capacity or a response plan.', '["all"]', 'external', 'Stage 0→1', '215', 'Operational', 'RC-1591', 'No Estimate of Expected Lead Volume Shared With Whoever Handles It', '2026-08-04 15:10:51.207804+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1594', '0.75', '2026-08-04 15:09:59.477543+00', '1536', 'text-embedding-3-small', NULL, 'When leads come in from a campaign, there is no defined process for sorting or prioritizing them for follow-up.', '["all"]', 'external', 'Stage 0→1', '215', 'Operational', 'RC-1592', 'No Plan for How Incoming Campaign Leads Will Be Triaged or Prioritized', '2026-08-04 15:10:51.271989+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1595', '0.70', '2026-08-04 15:09:59.477543+00', '1536', 'text-embedding-3-small', NULL, 'A campaign that could generate more demand than the business can currently deliver on gets launched without checking capacity first.', '["all"]', 'external', 'Stage 0→1', '215', 'Strategic', 'RC-1593', 'Fulfillment or Operational Capacity Not Checked Before Launching a Demand-Driving Campaign', '2026-08-04 15:10:51.335438+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1596', '0.75', '2026-08-04 15:09:59.477543+00', '1536', 'text-embedding-3-small', NULL, 'Marketing never learns from sales how the leads from a given campaign actually converted or performed, so future campaigns cannot improve based on that.', '["all"]', 'external', 'Stage 0→1', '215', 'Operational', 'RC-1594', 'No Feedback Loop From Sales Back to Marketing About Lead Quality', '2026-08-04 15:10:51.401501+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1597', '0.70', '2026-08-04 15:09:59.477543+00', '1536', 'text-embedding-3-small', NULL, 'A campaign might launch during a period when nobody is available to follow up promptly, letting hot leads go cold.', '["all"]', 'external', 'Stage 0→1', '215', 'Operational', 'RC-1595', 'Campaign Timing Not Coordinated With Team Availability', '2026-08-04 15:10:51.464027+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1598', '0.85', '2026-08-04 15:19:02.203121+00', '1536', 'text-embedding-3-small', NULL, 'The campaign goes straight to full spend without first validating the approach on a smaller, lower-risk scale.', '["all"]', 'external', 'Stage 0→1', '216', 'Operational', 'RC-1596', 'No Small-Scale Test Run Before Committing the Full Budget', '2026-08-04 15:19:53.48492+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1599', '0.80', '2026-08-04 15:19:02.203121+00', '1536', 'text-embedding-3-small', NULL, 'The entire intended audience is targeted from the start instead of beginning with a smaller slice to learn from.', '["all"]', 'external', 'Stage 0→1', '216', 'Operational', 'RC-1597', 'Full Audience Targeted Immediately Rather Than Starting With a Narrow Test Segment', '2026-08-04 15:19:53.557733+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1600', '0.75', '2026-08-04 15:19:02.203121+00', '1536', 'text-embedding-3-small', NULL, 'Even if a test were run, there is no pre-set benchmark to judge whether it succeeded before deciding to scale.', '["all"]', 'external', 'Stage 0→1', '216', 'Strategic', 'RC-1598', 'No Definition of What a Successful Test Result Would Look Like Beforehand', '2026-08-04 15:19:53.631298+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1601', '0.70', '2026-08-04 15:19:02.203121+00', '1536', 'text-embedding-3-small', NULL, 'The desire to see real results quickly makes the smaller, slower test phase feel like an unnecessary delay, so it gets skipped.', '["all"]', 'external', 'Stage 0→1', '216', 'Psychological', 'RC-1599', 'Impatience to See Full Results Leads to Skipping the Test Phase', '2026-08-04 15:19:53.68169+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1602', '0.75', '2026-08-04 15:19:02.203121+00', '1536', 'text-embedding-3-small', NULL, 'The full budget is allocated to the main campaign with nothing set aside for a lower-stakes test run first.', '["all"]', 'external', 'Stage 0→1', '216', 'Operational', 'RC-1600', 'No Budget Specifically Reserved for Testing Before Scaling', '2026-08-04 15:19:53.730779+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1603', '0.75', '2026-08-04 15:19:02.203121+00', '1536', 'text-embedding-3-small', NULL, 'Only one version of the message or creative ever gets used, with no comparison to see if an alternative would perform better.', '["all"]', 'external', 'Stage 0→1', '216', 'Operational', 'RC-1601', 'Multiple Messages or Creatives Never Tested Against Each Other', '2026-08-04 15:19:53.780729+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1604', '0.70', '2026-08-04 15:19:02.203121+00', '1536', 'text-embedding-3-small', NULL, 'Even in the rare case a test is run, its results do not actually change how the full campaign gets executed.', '["all"]', 'external', 'Stage 0→1', '216', 'Strategic', 'RC-1602', 'Lessons From Small Tests Not Used to Adjust the Full-Scale Rollout', '2026-08-04 15:19:53.829754+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1605', '0.80', '2026-08-04 15:22:03.688961+00', '1536', 'text-embedding-3-small', NULL, 'A campaign launches without any scan of whether a competitor is currently running something similar that could compete for the same attention.', '["all"]', 'external', 'Stage 0→1', '217', 'Strategic', 'RC-1603', 'No Check of What Competitors Are Currently Doing Before Launching', '2026-08-04 15:22:58.301412+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1606', '0.75', '2026-08-04 15:22:03.688961+00', '1536', 'text-embedding-3-small', NULL, 'Larger conditions in the market or industry that could affect how the campaign lands are not considered before launch.', '["all"]', 'external', 'Stage 0→1', '217', 'Knowledge', 'RC-1604', 'No Awareness of Broader Market or Industry Timing', '2026-08-04 15:22:58.385577+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1607', '0.80', '2026-08-04 15:22:03.688961+00', '1536', 'text-embedding-3-small', NULL, 'The launch date is set based purely on when the business is ready, without any check against external timing factors.', '["all"]', 'external', 'Stage 0→1', '217', 'Operational', 'RC-1605', 'Campaign Timing Decided by Internal Readiness Alone', '2026-08-04 15:22:58.444182+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1608', '0.75', '2026-08-04 15:22:03.688961+00', '1536', 'text-embedding-3-small', NULL, 'Busy seasons, competing events, or other distractions pulling at the audience''s attention are not factored into launch timing.', '["all"]', 'external', 'Stage 0→1', '217', 'Strategic', 'RC-1606', 'No Consideration of Audience Attention Cycles', '2026-08-04 15:22:58.506977+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1609', '0.70', '2026-08-04 15:22:03.688961+00', '1536', 'text-embedding-3-small', NULL, 'A campaign unknowingly competes head-on with a larger, similar effort from someone else in the market at the same time.', '["all"]', 'external', 'Stage 0→1', '217', 'Operational', 'RC-1607', 'Campaigns Sometimes Launched Into Direct Competition With a Similar Bigger Push', '2026-08-04 15:22:58.564589+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1610', '0.75', '2026-08-04 15:22:03.688961+00', '1536', 'text-embedding-3-small', NULL, 'There is no habitual check built into the campaign process for scanning external conditions before committing to a launch date.', '["all"]', 'external', 'Stage 0→1', '217', 'Operational', 'RC-1608', 'No Process for Checking Market Conditions as a Standard Pre-Launch Step', '2026-08-04 15:22:58.690504+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1611', '0.65', '2026-08-04 15:22:03.688961+00', '1536', 'text-embedding-3-small', NULL, 'There is a belief that a strong offer will succeed regardless of external timing, so timing itself never gets deliberately evaluated.', '["all"]', 'external', 'Stage 0→1', '217', 'Psychological', 'RC-1609', 'Founder Assumes Timing Does Not Matter Much If the Offer Is Good', '2026-08-04 15:22:58.747764+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1612', '0.85', '2026-08-04 15:25:32.15793+00', '1536', 'text-embedding-3-small', NULL, 'Total spend on a campaign is not recorded with enough precision to divide it against results and get a meaningful number.', '["all"]', 'external', 'Stage 0→1', '218', 'Operational', 'RC-1610', 'Campaign Spend Not Tracked Precisely Enough to Calculate Cost-Per-Result', '2026-08-04 15:26:22.367797+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1613', '0.85', '2026-08-04 15:25:32.15793+00', '1536', 'text-embedding-3-small', NULL, 'Even with spend and results both known, nobody actually does the division to see what each lead or sale cost.', '["all"]', 'external', 'Stage 0→1', '218', 'Operational', 'RC-1611', 'No Calculation of Cost-Per-Lead or Cost-Per-Acquisition After a Campaign Ends', '2026-08-04 15:26:22.4399+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1614', '0.80', '2026-08-04 15:25:32.15793+00', '1536', 'text-embedding-3-small', NULL, 'Sales that came from a campaign are not tagged or traced back to it, so revenue and campaign cost never get connected.', '["all"]', 'external', 'Stage 0→1', '218', 'Operational', 'RC-1612', 'Revenue Generated Not Tracked Back to the Specific Campaign', '2026-08-04 15:26:22.503885+00') on conflict do nothing;
