insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1649', '0.80', '2026-08-04 15:51:34.350724+00', '1536', 'text-embedding-3-small', NULL, 'Cash flow tracking (where it exists) does not account for money that is owed but not yet received, so the real picture stays incomplete.', '["all"]', 'external', 'Stage 0→1', '223', 'Operational', 'RC-1647', 'Overdue Amounts Not Reflected in Cash Flow Monitoring', '2026-08-04 15:52:29.714138+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1650', '0.70', '2026-08-04 15:51:34.350724+00', '1536', 'text-embedding-3-small', NULL, 'Customers are not always told clearly when payment is due, making it harder to define or enforce what counts as overdue.', '["all"]', 'external', 'Stage 0→1', '223', 'Operational', 'RC-1648', 'No Clear Payment Terms Communicated Upfront', '2026-08-04 15:52:29.779343+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1651', '0.75', '2026-08-04 15:51:34.350724+00', '1536', 'text-embedding-3-small', NULL, 'Asking a customer to pay an overdue invoice feels uncomfortable, so the follow-up gets avoided or delayed.', '["all"]', 'external', 'Stage 0→1', '223', 'Psychological', 'RC-1649', 'Founder Feels Awkward Chasing Customers for Money Owed', '2026-08-04 15:52:29.836343+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1652', '0.70', '2026-08-04 15:51:34.350724+00', '1536', 'text-embedding-3-small', NULL, 'When a payment is very late, there is no defined next step beyond a polite reminder — no plan for what to do if that does not work.', '["all"]', 'external', 'Stage 0→1', '223', 'Operational', 'RC-1650', 'No Escalation Path for Significantly Overdue Payments', '2026-08-04 15:52:29.894639+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1653', '0.70', '2026-08-04 15:51:34.350724+00', '1536', 'text-embedding-3-small', NULL, 'Patterns of repeated late payment from the same customers are never identified, so nothing changes about how those accounts are handled going forward.', '["all"]', 'external', 'Stage 0→1', '223', 'Strategic', 'RC-1651', 'No Visibility Into Which Customers Are Chronically Late Payers', '2026-08-04 15:52:29.94962+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1654', '0.85', '2026-08-04 16:10:43.458924+00', '1536', 'text-embedding-3-small', NULL, 'There is no single place tracking every vendor, subscription, or obligation the business currently owes money to.', '["all"]', 'external', 'Stage 0→1', '224', 'Operational', 'RC-1652', 'No List of What the Business Currently Owes and to Whom', '2026-08-04 16:14:02.834171+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1655', '0.85', '2026-08-04 16:10:43.458924+00', '1536', 'text-embedding-3-small', NULL, 'Even where amounts owed are known, due dates are not tracked, so nothing prompts timely payment.', '["all"]', 'external', 'Stage 0→1', '224', 'Operational', 'RC-1653', 'No Tracking of When Each Payable Is Actually Due', '2026-08-04 16:14:02.903864+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1656', '0.80', '2026-08-04 16:10:43.458924+00', '1536', 'text-embedding-3-small', NULL, 'Payment happens in response to a reminder or a service being cut off, rather than on a proactive schedule.', '["all"]', 'external', 'Stage 0→1', '224', 'Behavioural', 'RC-1654', 'Bills Paid Reactively Only When a Vendor Follows Up', '2026-08-04 16:14:02.956216+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1657', '0.75', '2026-08-04 16:10:43.458924+00', '1536', 'text-embedding-3-small', NULL, 'If cash gets tight, there is no plan for which obligations to pay first and which could reasonably wait.', '["all"]', 'external', 'Stage 0→1', '224', 'Strategic', 'RC-1655', 'No Prioritization of Which Payables Matter Most If Cash Is Tight', '2026-08-04 16:14:03.011143+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1658', '0.75', '2026-08-04 16:10:43.458924+00', '1536', 'text-embedding-3-small', NULL, 'Ongoing subscriptions and recurring commitments are not compiled anywhere, so their cumulative cost and timing stay invisible.', '["all"]', 'external', 'Stage 0→1', '224', 'Operational', 'RC-1656', 'Recurring Subscriptions and Commitments Not Tracked as a Running List', '2026-08-04 16:14:03.06197+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1659', '0.75', '2026-08-04 16:10:43.458924+00', '1536', 'text-embedding-3-small', NULL, 'Cash flow planning, where it happens, does not incorporate known upcoming bills and obligations.', '["all"]', 'external', 'Stage 0→1', '224', 'Operational', 'RC-1657', 'No Advance Visibility Into Upcoming Payment Obligations When Planning Cash Flow', '2026-08-04 16:14:03.113962+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1660', '0.70', '2026-08-04 16:10:43.458924+00', '1536', 'text-embedding-3-small', NULL, 'Missing payment deadlines because they were not tracked leads to late fees or strained relationships with vendors.', '["all"]', 'external', 'Stage 0→1', '224', 'Operational', 'RC-1658', 'Late Payment Penalties or Damaged Vendor Relationships From Missed Due Dates', '2026-08-04 16:14:03.165302+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1661', '0.85', '2026-08-04 16:17:05.554196+00', '1536', 'text-embedding-3-small', NULL, 'Money owed to the business and money the business owes are tracked separately, if at all, but never merged into a single projected cash position.', '["all"]', 'external', 'Stage 0→1', '225', 'Operational', 'RC-1659', 'Known Receivables and Payables Never Combined Into One Forward-Looking View', '2026-08-04 16:17:56.439501+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1662', '0.85', '2026-08-04 16:17:05.554196+00', '1536', 'text-embedding-3-small', NULL, 'There is no simple tool or template for projecting cash position over the next several weeks based on known inflows and outflows.', '["all"]', 'external', 'Stage 0→1', '225', 'Operational', 'RC-1660', 'No Short-Term Forecasting Method or Template Used', '2026-08-04 16:17:56.520343+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1663', '0.75', '2026-08-04 16:17:05.554196+00', '1536', 'text-embedding-3-small', NULL, 'Planning stays vague about timeframe — there is no consistent window (e.g. next 4 or 8 weeks) used for looking ahead.', '["all"]', 'external', 'Stage 0→1', '225', 'Operational', 'RC-1661', 'No Standard Forecasting Horizon', '2026-08-04 16:17:56.584232+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1664', '0.75', '2026-08-04 16:17:05.554196+00', '1536', 'text-embedding-3-small', NULL, 'Even where a projection was made once, it is not refreshed as new information about payments and bills comes in.', '["all"]', 'external', 'Stage 0→1', '225', 'Behavioural', 'RC-1662', 'Forecast, If Attempted, Not Updated Regularly', '2026-08-04 16:17:56.63905+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1665', '0.75', '2026-08-04 16:17:05.554196+00', '1536', 'text-embedding-3-small', NULL, 'Predictable recurring items are not built into any forward view, even though they are the most foreseeable part of cash flow.', '["all"]', 'external', 'Stage 0→1', '225', 'Operational', 'RC-1663', 'Recurring Costs and Revenue Not Factored Into a Running Projection', '2026-08-04 16:17:56.692869+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1666', '0.80', '2026-08-04 16:17:05.554196+00', '1536', 'text-embedding-3-small', NULL, 'Without a forward projection, there is nothing that would flag a coming shortfall before it actually arrives.', '["all"]', 'external', 'Stage 0→1', '225', 'Strategic', 'RC-1664', 'No Early-Warning Signal From a Forecast to Flag an Approaching Cash Crunch', '2026-08-04 16:17:56.746931+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1667', '0.75', '2026-08-04 16:17:05.554196+00', '1536', 'text-embedding-3-small', NULL, 'Spending and commitment decisions are made looking at what is in the account right now, not at where cash is realistically headed.', '["all"]', 'external', 'Stage 0→1', '225', 'Behavioural', 'RC-1665', 'Financial Decisions Made Based on Today''s Bank Balance Rather Than Projected Position', '2026-08-04 16:17:56.801594+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1668', '0.85', '2026-08-04 16:28:22.934+00', '1536', 'text-embedding-3-small', NULL, 'There is no advance list of expenses that could be reduced or paused if cash got tight, so this has to be figured out from scratch under pressure.', '["all"]', 'external', 'Stage 0→1', '226', 'Operational', 'RC-1666', 'No Predefined List of Discretionary Costs That Could Be Cut', '2026-08-04 16:29:26.587042+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1669', '0.85', '2026-08-04 16:28:22.934+00', '1536', 'text-embedding-3-small', NULL, 'There is no defined number that, once crossed, signals it is time to take action — the response stays vague and delayed.', '["all"]', 'external', 'Stage 0→1', '226', 'Operational', 'RC-1667', 'No Specific Cash Threshold That Triggers a Decision to Act', '2026-08-04 16:29:26.75578+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1670', '0.80', '2026-08-04 16:28:22.934+00', '1536', 'text-embedding-3-small', NULL, 'There is no plan in place for a credit line, loan, or other funding source to draw on if cash runs short, so this would be researched only after the need is already urgent.', '["all"]', 'external', 'Stage 0→1', '226', 'Strategic', 'RC-1668', 'No Advance Plan for Accessing Additional Cash if Needed', '2026-08-04 16:29:26.8227+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1671', '0.75', '2026-08-04 16:28:22.934+00', '1536', 'text-embedding-3-small', NULL, 'Even with a list of possible actions, there is no ranking of what to do first versus what to hold in reserve.', '["all"]', 'external', 'Stage 0→1', '226', 'Strategic', 'RC-1669', 'No Prioritized Order for Which Actions to Take First', '2026-08-04 16:29:26.879925+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1672', '0.75', '2026-08-04 16:28:22.934+00', '1536', 'text-embedding-3-small', NULL, 'Without a plan, decisions about what to cut get made in the moment, under pressure, when judgment is least reliable.', '["all"]', 'external', 'Stage 0→1', '226', 'Psychological', 'RC-1670', 'Cost-Cutting Decisions Made Reactively Under Stress', '2026-08-04 16:29:26.933214+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1673', '0.70', '2026-08-04 16:28:22.934+00', '1536', 'text-embedding-3-small', NULL, 'Even if a plan exists in the founder''s head, nobody else knows it, so it cannot be executed by anyone else or sanity-checked in advance.', '["all"]', 'external', 'Stage 0→1', '226', 'Operational', 'RC-1671', 'No One Else Aware of the Plan', '2026-08-04 16:29:26.985877+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1674', '0.70', '2026-08-04 16:28:22.934+00', '1536', 'text-embedding-3-small', NULL, 'Even after living through a cash crunch, the experience is not captured into a plan that would make the next one easier to handle.', '["all"]', 'external', 'Stage 0→1', '226', 'Strategic', 'RC-1672', 'Past Cash-Tight Periods Never Used to Build or Refine a Plan', '2026-08-04 16:29:27.035344+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1675', '0.85', '2026-08-04 16:32:13.163911+00', '1536', 'text-embedding-3-small', NULL, 'Even where co-founders exist, the current runway figure is not communicated to them, so it stays known only to one person.', '["all"]', 'external', 'Stage 1→10+', '227', 'Operational', 'RC-1673', 'Runway Number Not Shared With Co-Founders', '2026-08-04 16:33:10.444853+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1676', '0.80', '2026-08-04 16:32:13.163911+00', '1536', 'text-embedding-3-small', NULL, 'People approving or making purchases do not know how tight runway actually is, so spending happens without that context.', '["all"]', 'external', 'Stage 1→10+', '227', 'Operational', 'RC-1674', 'Key Team Members Making Spending Decisions Unaware of the Constraint', '2026-08-04 16:33:10.520615+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1677', '0.80', '2026-08-04 16:32:13.163911+00', '1536', 'text-embedding-3-small', NULL, 'There is no recurring update — like a monthly check-in — where runway status gets shared with the team.', '["all"]', 'external', 'Stage 1→10+', '227', 'Operational', 'RC-1675', 'No Regular Ritual for Communicating Runway Status', '2026-08-04 16:33:10.594121+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1678', '0.75', '2026-08-04 16:32:13.163911+00', '1536', 'text-embedding-3-small', NULL, 'The number is withheld out of concern that sharing it would cause anxiety or hurt morale, even though the team is operating within that constraint regardless.', '["all"]', 'external', 'Stage 1→10+', '227', 'Psychological', 'RC-1676', 'Founder Keeps Runway Private to Avoid Alarming the Team', '2026-08-04 16:33:10.658996+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1679', '0.70', '2026-08-04 16:32:13.163911+00', '1536', 'text-embedding-3-small', NULL, 'When the number does come up, it is shared without explanation, leaving people uncertain what it actually means or what to do differently.', '["all"]', 'external', 'Stage 1→10+', '227', 'Operational', 'RC-1677', 'No Context Given When Runway Is Mentioned, Causing Confusion Instead of Clarity', '2026-08-04 16:33:10.715779+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1680', '0.75', '2026-08-04 16:32:13.163911+00', '1536', 'text-embedding-3-small', NULL, 'Without visibility into the trend, spending habits stay the same even as the runway situation changes.', '["all"]', 'external', 'Stage 1→10+', '227', 'Behavioural', 'RC-1678', 'Team Continues Normal Spending Patterns Unaware Runway Is Shrinking', '2026-08-04 16:33:10.771224+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1681', '0.75', '2026-08-04 16:32:13.163911+00', '1536', 'text-embedding-3-small', NULL, 'Different people make choices in their own areas without a shared picture of the actual financial runway everyone is operating within.', '["all"]', 'external', 'Stage 1→10+', '227', 'Strategic', 'RC-1679', 'Decisions Made Independently Without Shared Understanding of the Real Constraint', '2026-08-04 16:33:10.831134+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1682', '0.85', '2026-08-04 16:35:42.603285+00', '1536', 'text-embedding-3-small', NULL, 'Fundraising timing is not planned with any cushion before the runway actually runs out, leaving no margin for delays.', '["all"]', 'external', 'Stage 1→10+', '228', 'Strategic', 'RC-1680', 'No Buffer Built in Between Runway End and When Fundraising Needs to Start', '2026-08-05 04:52:34.258942+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1683', '0.80', '2026-08-04 16:35:42.603285+00', '1536', 'text-embedding-3-small', NULL, 'Without a realistic sense of how many months a raise usually takes, it is impossible to plan backward correctly from runway.', '["all"]', 'external', 'Stage 1→10+', '228', 'Knowledge', 'RC-1681', 'Founder Doesn''t Know How Long a Typical Fundraising Process Takes', '2026-08-05 04:52:34.725627+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1684', '0.85', '2026-08-04 16:35:42.603285+00', '1536', 'text-embedding-3-small', NULL, 'There is no specific runway number that signals it is time to start preparing to raise.', '["all"]', 'external', 'Stage 1→10+', '228', 'Operational', 'RC-1682', 'No Trigger Point Tied to Runway That Prompts Fundraising Prep to Begin', '2026-08-05 04:52:34.809503+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1685', '0.80', '2026-08-04 16:35:42.603285+00', '1536', 'text-embedding-3-small', NULL, 'The process only starts once things already feel tight, rather than beginning from a position of strength.', '["all"]', 'external', 'Stage 1→10+', '228', 'Behavioural', 'RC-1683', 'Fundraising Delayed Until the Situation Feels Urgent', '2026-08-05 04:52:34.890435+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1686', '0.75', '2026-08-04 16:35:42.603285+00', '1536', 'text-embedding-3-small', NULL, 'Materials like a pitch deck, data room, or investor list are not built ahead of time, so preparation itself eats into already-limited runway.', '["all"]', 'external', 'Stage 1→10+', '228', 'Operational', 'RC-1684', 'No Advance Preparation Started Well Before the Raise Is Needed', '2026-08-05 04:52:34.954653+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1687', '0.70', '2026-08-04 16:35:42.603285+00', '1536', 'text-embedding-3-small', NULL, 'Thinking about the runway situation feels stressful, so planning for fundraising gets avoided, making the eventual scramble worse.', '["all"]', 'external', 'Stage 1→10+', '228', 'Psychological', 'RC-1685', 'Runway Anxiety Leads to Avoiding Fundraising Planning Altogether', '2026-08-05 04:52:35.013026+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1688', '0.70', '2026-08-04 16:35:42.603285+00', '1536', 'text-embedding-3-small', NULL, 'A hope that growth or a big deal will solve the runway problem delays starting fundraising preparation that may still be needed.', '["all"]', 'external', 'Stage 1→10+', '228', 'Psychological', 'RC-1686', 'Founder Assumes Revenue Growth Will Make Fundraising Unnecessary', '2026-08-05 04:52:35.069652+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1689', '0.85', '2026-08-05 04:54:51.174818+00', '1536', 'text-embedding-3-small', NULL, 'A new hire gets decided on based on need alone, without pulling up the runway number to see what the added cost does to it.', '["all"]', 'external', 'Stage 1→10+', '229', 'Operational', 'RC-1687', 'Runway Number Not Checked Before Making a Hiring Decision', '2026-08-05 04:55:38.708535+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1690', '0.85', '2026-08-05 04:54:51.174818+00', '1536', 'text-embedding-3-small', NULL, 'A new tool, contract, or large purchase gets approved without checking its effect on how long the cash will last.', '["all"]', 'external', 'Stage 1→10+', '229', 'Operational', 'RC-1688', 'Runway Number Not Checked Before Committing to a New Significant Expense', '2026-08-05 04:55:38.775245+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1691', '0.80', '2026-08-05 04:54:51.174818+00', '1536', 'text-embedding-3-small', NULL, 'There is no standard step in the decision process that forces a runway check before a major commitment is made.', '["all"]', 'external', 'Stage 1→10+', '229', 'Operational', 'RC-1689', 'No Process Requiring a Runway-Impact Check Before Big Financial Commitments', '2026-08-05 04:55:38.841104+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1692', '0.75', '2026-08-05 04:54:51.174818+00', '1536', 'text-embedding-3-small', NULL, 'Decisions are driven purely by whether something feels necessary, without weighing that need against the runway tradeoff.', '["all"]', 'external', 'Stage 1→10+', '229', 'Behavioural', 'RC-1690', 'Hiring and Spending Decisions Made on Perceived Need Alone', '2026-08-05 04:55:38.895416+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1693', '0.75', '2026-08-05 04:54:51.174818+00', '1536', 'text-embedding-3-small', NULL, 'Runway impact is not a question that automatically gets asked when a new commitment comes up for consideration.', '["all"]', 'external', 'Stage 1→10+', '229', 'Strategic', 'RC-1691', 'No Standing Question of "What Does This Do to Our Runway" in Decision-Making', '2026-08-05 04:55:38.946339+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1694', '0.75', '2026-08-05 04:54:51.174818+00', '1536', 'text-embedding-3-small', NULL, 'Each small new cost seems insignificant on its own, but nobody tracks how they add up together to shorten runway.', '["all"]', 'external', 'Stage 1→10+', '229', 'Operational', 'RC-1692', 'Multiple Small Commitments Accumulate Without Tracking Their Combined Runway Effect', '2026-08-05 04:55:39.001416+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1695', '0.70', '2026-08-05 04:54:51.174818+00', '1536', 'text-embedding-3-small', NULL, 'The consequence of a hiring or spending decision on runway is only discovered after the fact, when it is too late to easily reverse.', '["all"]', 'external', 'Stage 1→10+', '229', 'Behavioural', 'RC-1693', 'Decisions Regretted After Realizing the Runway Impact Only Afterward', '2026-08-05 04:55:39.058585+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1696', '0.85', '2026-08-05 04:57:49.944517+00', '1536', 'text-embedding-3-small', NULL, 'Each new runway calculation is treated as a standalone fact rather than compared against what it was last time.', '["all"]', 'external', 'Stage 1→10+', '230', 'Operational', 'RC-1694', 'Runway Recalculated in Isolation Each Time Without Comparing to the Previous Number', '2026-08-05 05:00:46.809272+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1697', '0.85', '2026-08-05 04:57:49.944517+00', '1536', 'text-embedding-3-small', NULL, 'Previous runway calculations are not saved anywhere, so there is nothing to compare the current number against.', '["all"]', 'external', 'Stage 1→10+', '230', 'Operational', 'RC-1695', 'No Record Kept of Past Runway Numbers', '2026-08-05 05:00:46.881512+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1698', '0.80', '2026-08-05 04:57:49.944517+00', '1536', 'text-embedding-3-small', NULL, 'Only the current runway figure is known, with no sense of how quickly it is improving or worsening.', '["all"]', 'external', 'Stage 1→10+', '230', 'Operational', 'RC-1696', 'No Visibility Into the Rate at Which Runway Is Changing', '2026-08-05 05:00:46.935395+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1699', '0.75', '2026-08-05 04:57:49.944517+00', '1536', 'text-embedding-3-small', NULL, 'Whether runway is trending up or down carries no different weight because attention only goes to the single latest figure.', '["all"]', 'external', 'Stage 1→10+', '230', 'Strategic', 'RC-1697', 'Improving and Worsening Trends Treated the Same Since Only the Latest Number Matters', '2026-08-05 05:00:46.996627+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1700', '0.70', '2026-08-05 04:57:49.944517+00', '1536', 'text-embedding-3-small', NULL, 'Even a large jump or drop in runway does not prompt any digging into what caused the change.', '["all"]', 'external', 'Stage 1→10+', '230', 'Operational', 'RC-1698', 'No Trigger to Investigate Why Runway Shifted Significantly', '2026-08-05 05:00:47.053452+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1701', '0.75', '2026-08-05 04:57:49.944517+00', '1536', 'text-embedding-3-small', NULL, 'A slow, steady decline in runway stays invisible until the number itself feels alarmingly low.', '["all"]', 'external', 'Stage 1→10+', '230', 'Psychological', 'RC-1699', 'Founder Unaware Runway Has Been Steadily Shrinking Until It Becomes Urgent', '2026-08-05 05:00:47.107879+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1702', '0.70', '2026-08-05 04:57:49.944517+00', '1536', 'text-embedding-3-small', NULL, 'A runway figure that still looks comfortable in isolation can hide the fact that it is worsening every time it is checked.', '["all"]', 'external', 'Stage 1→10+', '230', 'Strategic', 'RC-1700', 'Positive Short-Term Runway Number Masks a Negative Underlying Trend', '2026-08-05 05:00:47.166557+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1703', '0.85', '2026-08-05 05:03:19.868565+00', '1536', 'text-embedding-3-small', NULL, 'Expenses are tracked as a total but never sorted into which stay constant and which move with revenue.', '["all"]', 'external', 'Stage 0→1', '231', 'Knowledge', 'RC-1701', 'Costs Never Categorized as Fixed or Variable', '2026-08-05 05:04:05.903069+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1704', '0.85', '2026-08-05 05:03:19.868565+00', '1536', 'text-embedding-3-small', NULL, 'There is no clear answer to how much revenue is needed to cover all costs, because the fixed/variable breakdown that would answer it does not exist.', '["all"]', 'external', 'Stage 0→1', '231', 'Knowledge', 'RC-1702', 'Founder Does Not Know Their Business''s Break-Even Point', '2026-08-05 05:04:06.012793+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1705', '0.80', '2026-08-05 05:03:19.868565+00', '1536', 'text-embedding-3-small', NULL, 'It is unclear whether profitability improves, stays flat, or worsens as sales volume goes up, because the cost structure behind that isn''t understood.', '["all"]', 'external', 'Stage 0→1', '231', 'Knowledge', 'RC-1703', 'No Understanding of How Profit Margin Changes as Revenue Scales', '2026-08-05 05:04:06.094298+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1706', '0.75', '2026-08-05 05:03:19.868565+00', '1536', 'text-embedding-3-small', NULL, 'When costs need to be cut, decisions do not distinguish between costs that are easy to reduce (variable) and those that are locked in regardless (fixed).', '["all"]', 'external', 'Stage 0→1', '231', 'Behavioural', 'RC-1704', 'Cost-Cutting Decisions Treat All Expenses the Same', '2026-08-05 05:04:06.171303+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1707', '0.75', '2026-08-05 05:03:19.868565+00', '1536', 'text-embedding-3-small', NULL, 'In a downturn, it is unclear which expenses would naturally decrease with lower sales versus which would keep draining cash regardless.', '["all"]', 'external', 'Stage 0→1', '231', 'Knowledge', 'RC-1705', 'No Awareness of Which Costs Would Shrink Automatically If Revenue Dropped', '2026-08-05 05:04:06.243521+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1708', '0.75', '2026-08-05 05:03:19.868565+00', '1536', 'text-embedding-3-small', NULL, 'Prices are set without connecting them back to what it actually costs, in fixed and variable terms, to deliver each unit of the product or service.', '["all"]', 'external', 'Stage 0→1', '231', 'Strategic', 'RC-1706', 'Pricing Decisions Made Without Reference to Fixed/Variable Cost Structure', '2026-08-05 05:04:06.318072+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1709', '0.70', '2026-08-05 05:03:19.868565+00', '1536', 'text-embedding-3-small', NULL, 'The basic distinction between fixed and variable costs was never taught or picked up, so there is no mental model to apply it with.', '["all"]', 'external', 'Stage 0→1', '231', 'Knowledge', 'RC-1707', 'Founder Never Learned the Fixed/Variable Cost Framework as a Concept', '2026-08-05 05:04:06.393767+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1710', '0.85', '2026-08-05 05:06:46.593202+00', '1536', 'text-embedding-3-small', NULL, 'The founder treats the profit figure as if it were the same as available cash, without understanding they can diverge significantly.', '["all"]', 'external', 'Stage 0→1', '232', 'Knowledge', 'RC-1708', 'Profit on the P&L Assumed to Directly Equal Cash in the Bank', '2026-08-05 05:07:42.074229+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1711', '0.85', '2026-08-05 05:06:46.593202+00', '1536', 'text-embedding-3-small', NULL, 'Revenue counted as earned on the P&L may not have actually been collected yet, but this distinction is not understood.', '["all"]', 'external', 'Stage 0→1', '232', 'Knowledge', 'RC-1709', 'No Understanding of How Invoiced-But-Unpaid Revenue Affects the Profit-Cash Gap', '2026-08-05 05:07:42.151657+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1712', '0.75', '2026-08-05 05:06:46.593202+00', '1536', 'text-embedding-3-small', NULL, 'Items like depreciation or accrued expenses show up in the P&L without any actual cash movement, and this is not understood.', '["all"]', 'external', 'Stage 0→1', '232', 'Knowledge', 'RC-1710', 'No Awareness of Non-Cash Items That Affect P&L but Not Cash', '2026-08-05 05:07:42.217894+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1713', '0.80', '2026-08-05 05:06:46.593202+00', '1536', 'text-embedding-3-small', NULL, 'A profitable-looking P&L alongside a tight bank balance creates confusion rather than being understood as a normal, explainable gap.', '["all"]', 'external', 'Stage 0→1', '232', 'Behavioural', 'RC-1711', 'Confusion When a Profitable Period Still Shows a Cash Shortage', '2026-08-05 05:07:42.285277+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1714', '0.75', '2026-08-05 05:06:46.593202+00', '1536', 'text-embedding-3-small', NULL, 'There is no framework for understanding how the two numbers relate to and differ from each other.', '["all"]', 'external', 'Stage 0→1', '232', 'Knowledge', 'RC-1712', 'No Mental Model for Reconciling P&L Profit With Actual Bank Balance', '2026-08-05 05:07:42.345515+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1715', '0.80', '2026-08-05 05:06:46.593202+00', '1536', 'text-embedding-3-small', NULL, 'Spending decisions get made based on the profit figure, without checking whether that profit has actually turned into spendable cash.', '["all"]', 'external', 'Stage 0→1', '232', 'Behavioural', 'RC-1713', 'Financial Decisions Made Assuming Profit Automatically Means Available Cash to Spend', '2026-08-05 05:07:42.403181+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1716', '0.70', '2026-08-05 05:06:46.593202+00', '1536', 'text-embedding-3-small', NULL, 'Nobody has walked through, in simple language, why accounting profit and cash position are two different things.', '["all"]', 'external', 'Stage 0→1', '232', 'Knowledge', 'RC-1714', 'Founder Never Had the Accrual-vs-Cash Distinction Explained in Plain Terms', '2026-08-05 05:07:42.46125+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1717', '0.85', '2026-08-05 05:10:44.31238+00', '1536', 'text-embedding-3-small', NULL, 'The latest P&L is looked at on its own merits, without placing it next to the previous month to see what changed.', '["all"]', 'external', 'Stage 0→1', '233', 'Operational', 'RC-1715', 'Each P&L Reviewed as a Standalone Snapshot Never Compared to the Prior Period', '2026-08-05 05:11:36.345181+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1718', '0.85', '2026-08-05 05:10:44.31238+00', '1536', 'text-embedding-3-small', NULL, 'There is no format or habit of laying several months out together where a trend would become visible.', '["all"]', 'external', 'Stage 0→1', '233', 'Operational', 'RC-1716', 'No Side-by-Side View of Multiple Months to Spot Trends', '2026-08-05 05:11:36.417798+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1719', '0.80', '2026-08-05 05:10:44.31238+00', '1536', 'text-embedding-3-small', NULL, 'Individual cost or revenue lines are not tracked period over period, so a slow creep in either direction goes unnoticed.', '["all"]', 'external', 'Stage 0→1', '233', 'Operational', 'RC-1717', 'No Tracking of Specific Line Items Over Time', '2026-08-05 05:11:36.475062+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1720', '0.75', '2026-08-05 05:10:44.31238+00', '1536', 'text-embedding-3-small', NULL, 'Actual results are never checked against what was planned or expected, so there is no sense of variance.', '["all"]', 'external', 'Stage 0→1', '233', 'Operational', 'RC-1718', 'No Comparison Against Budget or a Prior Forecast', '2026-08-05 05:11:36.542451+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1721', '0.75', '2026-08-05 05:10:44.31238+00', '1536', 'text-embedding-3-small', NULL, 'Attention goes to the current month''s figure alone, so a slow trend across several months stays invisible.', '["all"]', 'external', 'Stage 0→1', '233', 'Behavioural', 'RC-1719', 'Gradual Changes Go Unnoticed Because Only the Latest Number Is Looked At', '2026-08-05 05:11:36.607692+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1722', '0.70', '2026-08-05 05:10:44.31238+00', '1536', 'text-embedding-3-small', NULL, 'Even a sharp period-over-period change in a specific number does not prompt any digging into why.', '["all"]', 'external', 'Stage 0→1', '233', 'Operational', 'RC-1720', 'No Trigger to Investigate When a Line Item Changes Significantly', '2026-08-05 05:11:36.664787+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1723', '0.75', '2026-08-05 05:10:44.31238+00', '1536', 'text-embedding-3-small', NULL, 'By the time a trend is noticed, it has often already become a significant problem rather than an early, manageable signal.', '["all"]', 'external', 'Stage 0→1', '233', 'Strategic', 'RC-1721', 'Trends Discovered Late, Only Once They Have Become Impossible to Ignore', '2026-08-05 05:11:36.728294+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1724', '0.85', '2026-08-05 05:14:03.603139+00', '1536', 'text-embedding-3-small', NULL, 'Financial data is never split out by individual offering, so nothing reveals how each one performs on its own.', '["all"]', 'external', 'Stage 0→1', '234', 'Operational', 'RC-1722', 'No Segmentation of Revenue or Costs by Product, Service, or Stream', '2026-08-05 05:14:58.938709+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1725', '0.85', '2026-08-05 05:14:03.603139+00', '1536', 'text-embedding-3-small', NULL, 'There is no format that presents profitability at anything more granular than the entire business as a single unit.', '["all"]', 'external', 'Stage 0→1', '234', 'Operational', 'RC-1723', 'P&L Only Exists as One Combined Statement for the Whole Business', '2026-08-05 05:14:59.02559+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1726', '0.80', '2026-08-05 05:14:03.603139+00', '1536', 'text-embedding-3-small', NULL, 'Without segmentation, it is impossible to say with confidence whether any single product or service makes or loses money.', '["all"]', 'external', 'Stage 0→1', '234', 'Knowledge', 'RC-1724', 'No Way to Tell Which Specific Offering Is Actually Profitable', '2026-08-05 05:14:59.096398+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1727', '0.75', '2026-08-05 05:14:03.603139+00', '1536', 'text-embedding-3-small', NULL, 'Expenses are tracked in aggregate rather than tied back to which offering actually caused them.', '["all"]', 'external', 'Stage 0→1', '234', 'Operational', 'RC-1725', 'Costs Not Allocated to the Specific Product or Service That Generated Them', '2026-08-05 05:14:59.150792+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1728', '0.75', '2026-08-05 05:14:03.603139+00', '1536', 'text-embedding-3-small', NULL, 'Without a breakdown, a weak product''s losses get absorbed into the overall total, masked by a stronger performer.', '["all"]', 'external', 'Stage 0→1', '234', 'Strategic', 'RC-1726', 'A Losing Offering Can Be Invisibly Subsidized by a Profitable One', '2026-08-05 05:14:59.203945+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1729', '0.75', '2026-08-05 05:14:03.603139+00', '1536', 'text-embedding-3-small', NULL, 'Decisions about which offerings to invest in or discontinue get made on instinct rather than on which ones are actually profitable.', '["all"]', 'external', 'Stage 0→1', '234', 'Behavioural', 'RC-1727', 'Grow-or-Cut Decisions Made Without Profitability Data', '2026-08-05 05:14:59.263796+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1730', '0.70', '2026-08-05 05:14:03.603139+00', '1536', 'text-embedding-3-small', NULL, 'Even if a breakdown were done once, there is no recurring habit of revisiting it as the business changes.', '["all"]', 'external', 'Stage 0→1', '234', 'Operational', 'RC-1728', 'No Process for Periodically Reviewing Profitability by Revenue Stream', '2026-08-05 05:14:59.322248+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1731', '0.85', '2026-08-05 05:23:50.953659+00', '1536', 'text-embedding-3-small', NULL, 'Numbers get carried over from the last budget with minor tweaks rather than being rebuilt around current priorities.', '["all"]', 'external', 'Stage 0→1', '235', 'Operational', 'RC-1729', 'Budget Allocations Copied From the Prior Period Without Reconsidering Priorities', '2026-08-05 05:24:50.398208+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1732', '0.85', '2026-08-05 05:23:50.953659+00', '1536', 'text-embedding-3-small', NULL, 'Goals are talked about separately from the budget, with nothing tying specific spending decisions back to those goals.', '["all"]', 'external', 'Stage 0→1', '235', 'Strategic', 'RC-1730', 'No Explicit Link Between Stated Business Goals and Where Budget Is Allocated', '2026-08-05 05:24:50.476898+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1733', '0.80', '2026-08-05 05:23:50.953659+00', '1536', 'text-embedding-3-small', NULL, 'Even after deciding what matters most, the budget itself is not updated to put more resources behind that priority.', '["all"]', 'external', 'Stage 0→1', '235', 'Operational', 'RC-1731', 'Strategic Priorities Identified but Budget Never Adjusted to Reflect Them', '2026-08-05 05:24:50.540488+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1734', '0.75', '2026-08-05 05:23:50.953659+00', '1536', 'text-embedding-3-small', NULL, 'Building the budget is treated as filling in a spreadsheet rather than as a deliberate choice about what matters most.', '["all"]', 'external', 'Stage 0→1', '235', 'Operational', 'RC-1732', 'Budget Built as One Flat Exercise Rather Than a Prioritization Decision', '2026-08-05 05:24:50.601463+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1735', '0.75', '2026-08-05 05:23:50.953659+00', '1536', 'text-embedding-3-small', NULL, 'An area that is no longer a strategic focus keeps getting the same resources it always has, out of habit rather than decision.', '["all"]', 'external', 'Stage 0→1', '235', 'Operational', 'RC-1733', 'Deprioritized Areas Continue Receiving the Same Budget as Before', '2026-08-05 05:24:50.659372+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1736', '0.75', '2026-08-05 05:23:50.953659+00', '1536', 'text-embedding-3-small', NULL, 'When a new priority emerges during the year, there is no mechanism to shift budget toward it rather than just adding cost on top.', '["all"]', 'external', 'Stage 0→1', '235', 'Operational', 'RC-1734', 'No Process for Reallocating Budget Toward a New Priority Mid-Period', '2026-08-05 05:24:50.71651+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1737', '0.70', '2026-08-05 05:23:50.953659+00', '1536', 'text-embedding-3-small', NULL, 'Discussions about where the business is headed and discussions about spending happen in different rooms, never connected to each other.', '["all"]', 'external', 'Stage 0→1', '235', 'Strategic', 'RC-1735', 'Budget Conversations Happen Separately From Strategy Conversations', '2026-08-05 05:24:50.773297+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1738', '0.85', '2026-08-05 05:27:30.83058+00', '1536', 'text-embedding-3-small', NULL, 'Spending gets planned around what feels needed, without checking it against what revenue is actually expected to come in.', '["all"]', 'external', 'Stage 0→1', '236', 'Operational', 'RC-1736', 'Budget Built From Desired Spending Without Reference to Expected Revenue', '2026-08-05 05:28:22.772217+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1739', '0.85', '2026-08-05 05:27:30.83058+00', '1536', 'text-embedding-3-small', NULL, 'The budget does not come with an explicit revenue number it is assuming, so its own affordability can never really be checked.', '["all"]', 'external', 'Stage 0→1', '236', 'Operational', 'RC-1737', 'No Specific Revenue Assumption Stated Alongside the Budget', '2026-08-05 05:28:22.936788+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1740', '0.80', '2026-08-05 05:27:30.83058+00', '1536', 'text-embedding-3-small', NULL, 'Nobody stress-tests the budget against a scenario where revenue comes in lower than hoped.', '["all"]', 'external', 'Stage 0→1', '236', 'Strategic', 'RC-1738', 'No Check of Whether the Budget Is Affordable Below Expected Revenue', '2026-08-05 05:28:22.996351+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1741', '0.75', '2026-08-05 05:27:30.83058+00', '1536', 'text-embedding-3-small', NULL, 'The budget leans on a best-case revenue number without any acknowledgment that reality could come in lower.', '["all"]', 'external', 'Stage 0→1', '236', 'Psychological', 'RC-1739', 'Optimistic Revenue Assumptions Used Without Acknowledging the Risk', '2026-08-05 05:28:23.048422+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1742', '0.75', '2026-08-05 05:27:30.83058+00', '1536', 'text-embedding-3-small', NULL, 'There is no backup version of the budget ready in case revenue underperforms the assumption it was built on.', '["all"]', 'external', 'Stage 0→1', '236', 'Operational', 'RC-1740', 'No Revised Budget Prepared for a Lower-Revenue Scenario', '2026-08-05 05:28:23.102129+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1743', '0.70', '2026-08-05 05:27:30.83058+00', '1536', 'text-embedding-3-small', NULL, 'Commitments get made the same way whether the revenue forecast behind them is solid or shaky.', '["all"]', 'external', 'Stage 0→1', '236', 'Behavioural', 'RC-1741', 'Spending Commitments Made Independent of Revenue Forecast Confidence', '2026-08-05 05:28:23.152022+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1744', '0.75', '2026-08-05 05:27:30.83058+00', '1536', 'text-embedding-3-small', NULL, 'Even if revenue starts coming in under the number the budget assumed, nothing prompts a re-look at spending plans.', '["all"]', 'external', 'Stage 0→1', '236', 'Operational', 'RC-1742', 'No Trigger to Revisit the Budget if Revenue Tracks Below Assumption', '2026-08-05 05:28:23.202909+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1745', '0.85', '2026-08-05 05:30:57.487563+00', '1536', 'text-embedding-3-small', NULL, 'Budget numbers come purely from the founder''s own view, with no other perspective factored in.', '["all"]', 'external', 'Stage 0→1', '237', 'Operational', 'RC-1743', 'Budget Built Entirely by the Founder Without Consulting Anyone Else', '2026-08-05 05:33:28.884424+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1746', '0.85', '2026-08-05 05:30:57.487563+00', '1536', 'text-embedding-3-small', NULL, 'The people closest to a given area are never asked directly what resources they need to do their work.', '["all"]', 'external', 'Stage 0→1', '237', 'Operational', 'RC-1744', 'Team or Department Heads Never Asked What They Actually Need', '2026-08-05 05:33:28.970563+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1747', '0.80', '2026-08-05 05:30:57.487563+00', '1536', 'text-embedding-3-small', NULL, 'There is no defined step where input gets collected from others before the budget is locked in.', '["all"]', 'external', 'Stage 0→1', '237', 'Operational', 'RC-1745', 'No Process for Gathering Input Before Finalizing the Budget', '2026-08-05 05:33:29.025388+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1748', '0.75', '2026-08-05 05:30:57.487563+00', '1536', 'text-embedding-3-small', NULL, 'People learn what they can and cannot spend only once the budget is already set, rather than being part of setting it.', '["all"]', 'external', 'Stage 0→1', '237', 'Behavioural', 'RC-1746', 'Team Members Find Out About Budget Constraints Only After the Fact', '2026-08-05 05:33:29.084555+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1749', '0.75', '2026-08-05 05:30:57.487563+00', '1536', 'text-embedding-3-small', NULL, 'Because the budget was imposed rather than built with them, people feel little personal responsibility for staying within it.', '["all"]', 'external', 'Stage 0→1', '237', 'Psychological', 'RC-1747', 'No Ownership or Buy-In From Those Responsible for Spending Within an Area', '2026-08-05 05:33:29.135519+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1750', '0.70', '2026-08-05 05:30:57.487563+00', '1536', 'text-embedding-3-small', NULL, 'There is a confidence that the founder already understands each area''s needs well enough, so nobody else is asked.', '["all"]', 'external', 'Stage 0→1', '237', 'Psychological', 'RC-1748', 'Founder Assumes They Know What Each Area Needs Without Checking', '2026-08-05 05:33:29.185389+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1751', '0.70', '2026-08-05 05:30:57.487563+00', '1536', 'text-embedding-3-small', NULL, 'Because nobody else reviews the budget before it is finalized, gaps or unrealistic numbers only surface once problems appear.', '["all"]', 'external', 'Stage 0→1', '237', 'Operational', 'RC-1749', 'Budget Inaccuracies From Missing Context Never Caught Early', '2026-08-05 05:33:29.235428+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1752', '0.85', '2026-08-05 05:36:01.340517+00', '1536', 'text-embedding-3-small', NULL, 'There is no checkpoint someone has to pass through before making a purchase that exceeds what was allocated.', '["all"]', 'external', 'Stage 0→1', '238', 'Operational', 'RC-1750', 'No Approval Step Required Before Spending Beyond a Budgeted Category', '2026-08-05 05:36:52.807956+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1753', '0.85', '2026-08-05 05:36:01.340517+00', '1536', 'text-embedding-3-small', NULL, 'Spending decisions happen without anyone pausing to compare the purchase against what is actually left in the relevant budget line.', '["all"]', 'external', 'Stage 0→1', '238', 'Behavioural', 'RC-1751', 'Unbudgeted Purchases Made Without Checking Against the Budget First', '2026-08-05 05:36:52.884538+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1754', '0.75', '2026-08-05 05:36:01.340517+00', '1536', 'text-embedding-3-small', NULL, 'Even if someone wanted to push back on a spend, there is no clear authority or process for actually declining it.', '["all"]', 'external', 'Stage 0→1', '238', 'Operational', 'RC-1752', 'No One Authorized to Say No to an Out-of-Budget Request', '2026-08-05 05:36:52.943096+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1755', '0.80', '2026-08-05 05:36:01.340517+00', '1536', 'text-embedding-3-small', NULL, 'Exceeding the budget is noticed by looking back at what was spent, rather than being caught and prevented in the moment.', '["all"]', 'external', 'Stage 0→1', '238', 'Operational', 'RC-1753', 'Budget Overruns Discovered Only After the Fact', '2026-08-05 05:36:53.007213+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1756', '0.75', '2026-08-05 05:36:01.340517+00', '1536', 'text-embedding-3-small', NULL, 'There is no defined dollar amount above which spending needs a sign-off, so it is unclear when a check should even happen.', '["all"]', 'external', 'Stage 0→1', '238', 'Operational', 'RC-1754', 'No Threshold Set for When a Purchase Requires Approval', '2026-08-05 05:36:53.06731+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1757', '0.70', '2026-08-05 05:36:01.340517+00', '1536', 'text-embedding-3-small', NULL, 'Some out-of-budget requests get approved and others don''t, with no consistent logic, so the budget stops feeling like a real constraint.', '["all"]', 'external', 'Stage 0→1', '238', 'Behavioural', 'RC-1755', 'Founder Makes Exceptions Inconsistently, Undermining the Budget''s Credibility', '2026-08-05 05:36:53.123594+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1758', '0.70', '2026-08-05 05:36:01.340517+00', '1536', 'text-embedding-3-small', NULL, 'There is no record of overrun frequency or size, so the scale of the problem stays invisible.', '["all"]', 'external', 'Stage 0→1', '238', 'Operational', 'RC-1756', 'No Tracking of How Often or By How Much the Budget Gets Exceeded', '2026-08-05 05:36:53.183549+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1759', '0.85', '2026-08-05 05:39:46.522935+00', '1536', 'text-embedding-3-small', NULL, 'Once an expense is identified as wasteful, there is no defined next step that actually leads to it being cut.', '["all"]', 'external', 'Stage 0→1', '239', 'Operational', 'RC-1757', 'No Process for Acting on Expenses Flagged as Unnecessary', '2026-08-05 05:40:43.310472+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1760', '0.80', '2026-08-05 05:39:46.522935+00', '1536', 'text-embedding-3-small', NULL, 'The friction of actually canceling something — emails, calls, forms — makes it easy to postpone indefinitely.', '["all"]', 'external', 'Stage 0→1', '239', 'Behavioural', 'RC-1758', 'Canceling a Subscription or Vendor Feels Like a Hassle', '2026-08-05 05:40:43.403446+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1761', '0.80', '2026-08-05 05:39:46.522935+00', '1536', 'text-embedding-3-small', NULL, 'After something is identified in a review, no specific person is responsible for actually completing the cut.', '["all"]', 'external', 'Stage 0→1', '239', 'Operational', 'RC-1759', 'No One Assigned to Follow Through on a Flagged Expense', '2026-08-05 05:40:43.470623+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1762', '0.80', '2026-08-05 05:39:46.522935+00', '1536', 'text-embedding-3-small', NULL, 'The same wasteful spend gets noticed again and again, but the pattern of re-identifying it without acting continues.', '["all"]', 'external', 'Stage 0→1', '239', 'Operational', 'RC-1760', 'Same Unnecessary Expense Identified in Multiple Reviews Without Being Cut', '2026-08-05 05:40:43.53672+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1763', '0.70', '2026-08-05 05:39:46.522935+00', '1536', 'text-embedding-3-small', NULL, 'Hesitation to cut a cost stems from worry that it will turn out to matter after all, so it stays out of caution.', '["all"]', 'external', 'Stage 0→1', '239', 'Psychological', 'RC-1761', 'Fear of Canceling Something That Might Be Needed Later', '2026-08-05 05:40:43.600312+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1764', '0.75', '2026-08-05 05:39:46.522935+00', '1536', 'text-embedding-3-small', NULL, 'A flagged expense goes onto a list with no target date for when it should actually be resolved.', '["all"]', 'external', 'Stage 0→1', '239', 'Operational', 'RC-1762', 'No Deadline Set for Acting on an Identified Cost-Cutting Opportunity', '2026-08-05 05:40:43.664723+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1765', '0.70', '2026-08-05 05:39:46.522935+00', '1536', 'text-embedding-3-small', NULL, 'Even where an expense is eventually cut, nobody confirms the expected savings actually showed up.', '["all"]', 'external', 'Stage 0→1', '239', 'Operational', 'RC-1763', 'No Tracking of Whether Identified Savings Actually Got Realized', '2026-08-05 05:40:43.728484+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1766', '0.85', '2026-08-05 06:25:19.962682+00', '1536', 'text-embedding-3-small', NULL, 'There is no recurring practice of checking what else is available at what price for a given recurring expense.', '["all"]', 'external', 'Stage 0→1', '240', 'Operational', 'RC-1764', 'No Habit of Comparing Vendor Pricing Against Alternatives', '2026-08-05 06:26:26.963008+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1767', '0.85', '2026-08-05 06:25:19.962682+00', '1536', 'text-embedding-3-small', NULL, 'Subscriptions and contracts roll over without anyone pausing to see if pricing in the market has shifted.', '["all"]', 'external', 'Stage 0→1', '240', 'Operational', 'RC-1765', 'Recurring Expenses Renewed Automatically Without Checking Current Market Rates', '2026-08-05 06:26:27.17532+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1768', '0.80', '2026-08-05 06:25:19.962682+00', '1536', 'text-embedding-3-small', NULL, 'The listed price is simply paid, without ever asking a vendor for a better rate or improved terms.', '["all"]', 'external', 'Stage 0→1', '240', 'Behavioural', 'RC-1766', 'No Attempt Made to Negotiate Pricing or Terms With Existing Vendors', '2026-08-05 06:26:27.233424+00') on conflict do nothing;
