insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1771', '0.70', '2026-08-05 06:25:19.962682+00', '1536', 'text-embedding-3-small', NULL, 'Comfort with an existing vendor relationship makes even evaluating alternatives feel unnecessary.', '["all"]', 'external', 'Stage 0→1', '240', 'Behavioural', 'RC-1769', 'Loyalty or Inertia With a Current Vendor Prevents Considering a Switch', '2026-08-05 06:26:27.411119+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1772', '0.70', '2026-08-05 06:25:19.962682+00', '1536', 'text-embedding-3-small', NULL, 'There is no visibility into the potential savings sitting on the table, so there is no urgency to pursue them.', '["all"]', 'external', 'Stage 0→1', '240', 'Operational', 'RC-1770', 'No Tracking of How Much Could Be Saved Through Better Pricing or Negotiation', '2026-08-05 06:26:27.475389+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1773', '0.85', '2026-08-05 06:29:17.105382+00', '1536', 'text-embedding-3-small', NULL, 'Spending is not measured against any external reference point like revenue percentage or comparable businesses.', '["all"]', 'external', 'Stage 0→1', '241', 'Knowledge', 'RC-1771', 'No Benchmark Data Used to Compare Expense Levels Against Revenue or Peers', '2026-08-05 06:30:17.770818+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1774', '0.80', '2026-08-05 06:29:17.105382+00', '1536', 'text-embedding-3-small', NULL, 'The only comparison ever made is this period versus last period, never against an outside standard of what is reasonable.', '["all"]', 'external', 'Stage 0→1', '241', 'Operational', 'RC-1772', 'Spending Judged Only Against Itself Over Time', '2026-08-05 06:30:17.845244+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1775', '0.80', '2026-08-05 06:29:17.105382+00', '1536', 'text-embedding-3-small', NULL, 'There is no working number for what proportion of revenue a category like software or marketing typically consumes.', '["all"]', 'external', 'Stage 0→1', '241', 'Knowledge', 'RC-1773', 'No Sense of What a Normal Percentage of Revenue a Category Should Be', '2026-08-05 06:30:17.909405+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1776', '0.75', '2026-08-05 06:29:17.105382+00', '1536', 'text-embedding-3-small', NULL, 'Without a number to compare against, scrutiny only kicks in based on gut feeling rather than an actual benchmark.', '["all"]', 'external', 'Stage 0→1', '241', 'Behavioural', 'RC-1774', 'Expense Levels Only Questioned When They Feel Intuitively Too High', '2026-08-05 06:30:17.975209+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1777', '0.75', '2026-08-05 06:29:17.105382+00', '1536', 'text-embedding-3-small', NULL, 'There has been no effort to find out what comparable businesses in the same space or size spend on a given category.', '["all"]', 'external', 'Stage 0→1', '241', 'Operational', 'RC-1775', 'No Research Done Into What Similar Businesses Typically Spend', '2026-08-05 06:30:18.03121+00') on conflict do nothing;
