insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1813', '0.75', '2026-08-05 07:21:31.321515+00', '1536', 'text-embedding-3-small', NULL, 'When the need does arise, everything gets thrown together at the last minute rather than calmly assembled in advance.', '["all"]', 'external', 'Stage 0→1', '246', 'Behavioural', 'RC-1811', 'Scrambling to Prepare Presentable Materials Happens Reactively Under Time Pressure', '2026-08-05 07:22:27.880525+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1814', '0.75', '2026-08-05 07:21:31.321515+00', '1536', 'text-embedding-3-small', NULL, 'A loan, investment, or partnership conversation can stall or lose momentum simply because nothing was ready to share when asked.', '["all"]', 'external', 'Stage 0→1', '246', 'Strategic', 'RC-1812', 'Opportunities Potentially Missed or Delayed Due to Lack of Ready Materials', '2026-08-05 07:22:27.945498+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1815', '0.85', '2026-08-05 07:25:00.540643+00', '1536', 'text-embedding-3-small', NULL, 'The P&L, balance sheet, and cash flow statement each get looked at on their own, never side by side.', '["all"]', 'external', 'Stage 0→1', '247', 'Operational', 'RC-1813', 'Each Report Type Reviewed in Isolation, Never Together', '2026-08-05 07:26:08.082427+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1816', '0.85', '2026-08-05 07:25:00.540643+00', '1536', 'text-embedding-3-small', NULL, 'What shows up in one report is never checked against what the others say to see if the story holds together.', '["all"]', 'external', 'Stage 0→1', '247', 'Operational', 'RC-1814', 'No Habit of Cross-Referencing Findings Across Report Types', '2026-08-05 07:26:08.165773+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1817', '0.75', '2026-08-05 07:25:00.540643+00', '1536', 'text-embedding-3-small', NULL, 'There is no skill or confidence in pulling several financial statements together into a single coherent understanding.', '["all"]', 'external', 'Stage 0→1', '247', 'Knowledge', 'RC-1815', 'No One Trained or Comfortable Synthesizing Multiple Statements Into One Narrative', '2026-08-05 07:26:08.222684+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1818', '0.80', '2026-08-05 07:25:00.540643+00', '1536', 'text-embedding-3-small', NULL, 'When one report seems to conflict with another — profit but no cash, for example — nobody digs into why.', '["all"]', 'external', 'Stage 0→1', '247', 'Operational', 'RC-1816', 'Contradictions Between Reports Never Investigated', '2026-08-05 07:26:08.285267+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1819', '0.75', '2026-08-05 07:25:00.540643+00', '1536', 'text-embedding-3-small', NULL, 'There is nothing that condenses all the reports into one overview of where the business actually stands.', '["all"]', 'external', 'Stage 0→1', '247', 'Operational', 'RC-1817', 'No Single Summary Pulling Together the Full Financial Picture', '2026-08-05 07:26:08.342243+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1820', '0.70', '2026-08-05 07:25:00.540643+00', '1536', 'text-embedding-3-small', NULL, 'Even when multiple reports exist, the people or moments reviewing them are disconnected from each other.', '["all"]', 'external', 'Stage 0→1', '247', 'Operational', 'RC-1818', 'Reports Reviewed by Different People or at Different Times, Never Together', '2026-08-05 07:26:08.396085+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1821', '0.70', '2026-08-05 07:25:00.540643+00', '1536', 'text-embedding-3-small', NULL, 'Comfort and attention concentrate on a single familiar statement, leaving the others effectively unread.', '["all"]', 'external', 'Stage 0→1', '247', 'Knowledge', 'RC-1819', 'Founder Only Understands One Report Type Well, Ignoring the Others', '2026-08-05 07:26:08.449091+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1822', '0.85', '2026-08-06 03:54:55.788109+00', '1536', 'text-embedding-3-small', NULL, 'There is no defined list of what needs to be ready — email, software logins, systems access — before someone''s first day.', '["all"]', 'external', 'Stage 0→1', '248', 'Operational', 'RC-1822', 'No Checklist of Accounts and Tools to Set Up Before a New Hire Starts', '2026-08-06 03:55:42.031086+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1823', '0.85', '2026-08-06 03:54:55.788109+00', '1536', 'text-embedding-3-small', NULL, 'Setting up logins and permissions starts only after the person shows up, rather than being handled in advance.', '["all"]', 'external', 'Stage 0→1', '248', 'Operational', 'RC-1823', 'Access Requests Only Submitted Once the New Hire Has Already Arrived', '2026-08-06 03:55:42.100204+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1824', '0.80', '2026-08-06 03:54:55.788109+00', '1536', 'text-embedding-3-small', NULL, 'There is no specific person responsible for making sure everything is ready before the start date.', '["all"]', 'external', 'Stage 0→1', '248', 'Operational', 'RC-1824', 'No One Owns Preparing a New Hire''s Setup in Advance', '2026-08-06 03:55:42.15722+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1825', '0.75', '2026-08-06 03:54:55.788109+00', '1536', 'text-embedding-3-small', NULL, 'A laptop or other necessary hardware is not sourced or configured until after the new hire has already begun.', '["all"]', 'external', 'Stage 0→1', '248', 'Operational', 'RC-1825', 'Equipment Not Ordered or Ready Ahead of the Start Date', '2026-08-06 03:55:42.202931+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1826', '0.70', '2026-08-06 03:54:55.788109+00', '1536', 'text-embedding-3-small', NULL, 'There is an assumption that figuring out access and tools in real time on day one is fine, rather than a real cost.', '["all"]', 'external', 'Stage 0→1', '248', 'Psychological', 'RC-1826', 'Founder Assumes Setup Can Happen On the Fly During the First Day', '2026-08-06 03:55:42.25574+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1827', '0.70', '2026-08-06 03:54:55.788109+00', '1536', 'text-embedding-3-small', NULL, 'There is no reference for what access a specific role requires, so it gets reinvented — or forgotten — every time.', '["all"]', 'external', 'Stage 0→1', '248', 'Knowledge', 'RC-1827', 'No Standard List of What Tools or Accounts a Given Role Actually Needs', '2026-08-06 03:55:42.302046+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1828', '0.75', '2026-08-06 03:54:55.788109+00', '1536', 'text-embedding-3-small', NULL, 'Productive ramp-up time gets consumed by logistics that could have been handled before the new hire ever arrived.', '["all"]', 'external', 'Stage 0→1', '248', 'Strategic', 'RC-1828', 'First Day or Two Lost to Administrative Setup Instead of Real Work', '2026-08-06 03:55:42.351738+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1829', '0.85', '2026-08-06 03:58:08.363638+00', '1536', 'text-embedding-3-small', NULL, 'There is no named person a new hire is told to approach when something comes up.', '["all"]', 'external', 'Stage 0→1', '249', 'Operational', 'RC-1829', 'No One Specifically Designated as the Go-To Person for a New Hire''s Questions', '2026-08-06 03:58:57.93891+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1830', '0.80', '2026-08-06 03:58:08.363638+00', '1536', 'text-embedding-3-small', NULL, 'Without another option, the founder becomes the default contact for even minor questions, pulling focus away from everything else.', '["all"]', 'external', 'Stage 0→1', '249', 'Behavioural', 'RC-1830', 'New Hire Defaults to Interrupting the Founder for Every Small Question', '2026-08-06 03:58:58.020818+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1831', '0.80', '2026-08-06 03:58:08.363638+00', '1536', 'text-embedding-3-small', NULL, 'Uncertainty about who to go to leads to questions going unasked, which slows down understanding and progress.', '["all"]', 'external', 'Stage 0→1', '249', 'Behavioural', 'RC-1831', 'New Hire Sits on Questions Rather Than Ask, Unsure Who to Approach', '2026-08-06 03:58:58.085581+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1832', '0.75', '2026-08-06 03:58:08.363638+00', '1536', 'text-embedding-3-small', NULL, 'Even if a suitable person exists, no deliberate introduction happens to establish that relationship.', '["all"]', 'external', 'Stage 0→1', '249', 'Operational', 'RC-1832', 'No Introduction Made Connecting the New Hire to Someone They Can Rely On', '2026-08-06 03:58:58.160691+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1833', '0.70', '2026-08-06 03:58:08.363638+00', '1536', 'text-embedding-3-small', NULL, 'There is a belief that things will sort themselves out informally, so no one is deliberately assigned.', '["all"]', 'external', 'Stage 0→1', '249', 'Psychological', 'RC-1833', 'Founder Assumes Questions Will Naturally Get Answered Without a Formal Point Person', '2026-08-06 03:58:58.210933+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1834', '0.70', '2026-08-06 03:58:08.363638+00', '1536', 'text-embedding-3-small', NULL, 'Even with more than one team member, there is no clarity on who handles what kind of question.', '["all"]', 'external', 'Stage 0→1', '249', 'Operational', 'RC-1834', 'No Guidance on Which Types of Questions Go to Which Person', '2026-08-06 03:58:58.259894+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1835', '0.70', '2026-08-06 03:58:08.363638+00', '1536', 'text-embedding-3-small', NULL, 'Without someone clearly in their corner, the new hire experiences the early weeks as more isolating than they need to be.', '["all"]', 'external', 'Stage 0→1', '249', 'Psychological', 'RC-1835', 'New Hire Feels Isolated or Unsupported Without a Designated Contact', '2026-08-06 03:58:58.311445+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1836', '0.85', '2026-08-06 04:05:21.225935+00', '1536', 'text-embedding-3-small', NULL, 'There is no dedicated time set aside to actually teach a new hire how to perform the tasks central to their role.', '["all"]', 'external', 'Stage 0→1', '250', 'Operational', 'RC-1836', 'No Structured Training Session or Walkthrough for Core Job Tasks', '2026-08-06 04:06:18.043538+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1837', '0.85', '2026-08-06 04:05:21.225935+00', '1536', 'text-embedding-3-small', NULL, 'Rather than being shown how to use the tools and systems needed for the job, the new hire has to figure them out on their own.', '["all"]', 'external', 'Stage 0→1', '250', 'Operational', 'RC-1837', 'New Hire Expected to Learn Tools and Systems by Trial and Error', '2026-08-06 04:06:18.113872+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1838', '0.80', '2026-08-06 04:05:21.225935+00', '1536', 'text-embedding-3-small', NULL, 'There is no specific person responsible for training, so instruction happens only if someone happens to have time.', '["all"]', 'external', 'Stage 0→1', '250', 'Operational', 'RC-1838', 'No One Designated to Actually Teach the Skills Needed for the Role', '2026-08-06 04:06:18.168166+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1839', '0.75', '2026-08-06 04:05:21.225935+00', '1536', 'text-embedding-3-small', NULL, 'What little training does occur varies significantly depending on who is doing the onboarding and when.', '["all"]', 'external', 'Stage 0→1', '250', 'Operational', 'RC-1839', 'Training, if It Happens, Is Informal and Inconsistent Between Hires', '2026-08-06 04:06:18.225276+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1840', '0.75', '2026-08-06 04:05:21.225935+00', '1536', 'text-embedding-3-small', NULL, 'A new hire is expected to perform tasks solo right away, without first watching or practicing alongside someone experienced.', '["all"]', 'external', 'Stage 0→1', '250', 'Operational', 'RC-1840', 'No Practice or Shadowing Period Before Independent Work', '2026-08-06 04:06:18.284757+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1841', '0.75', '2026-08-06 04:05:21.225935+00', '1536', 'text-embedding-3-small', NULL, 'Gaps in training surface reactively, once an avoidable mistake has already happened and caused real cost.', '["all"]', 'external', 'Stage 0→1', '250', 'Operational', 'RC-1841', 'Mistakes From Lack of Training Discovered Only After Causing a Problem', '2026-08-06 04:06:18.338812+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1842', '0.70', '2026-08-06 04:05:21.225935+00', '1536', 'text-embedding-3-small', NULL, 'Because the new hire was hired for their skill, there is an assumption they should not need to be shown how things work here specifically.', '["all"]', 'external', 'Stage 0→1', '250', 'Psychological', 'RC-1842', 'Founder Assumes Competence Means No Training Is Needed', '2026-08-06 04:06:18.391113+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1843', '0.80', '2026-08-06 04:08:39.064655+00', '1536', 'text-embedding-3-small', NULL, 'There is no dedicated moment where a new hire is told why the business exists and what it is trying to achieve.', '["all"]', 'external', 'Stage 0→1', '251', 'Operational', 'RC-1843', 'No Session or Conversation Introducing the Company''s Mission', '2026-08-06 04:09:28.056166+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1844', '0.80', '2026-08-06 04:08:39.064655+00', '1536', 'text-embedding-3-small', NULL, 'Nobody walks the new hire through who the business serves, what they need, or what their experience is like.', '["all"]', 'external', 'Stage 0→1', '251', 'Operational', 'RC-1844', 'New Hire Never Introduced to Who the Actual Customers Are', '2026-08-06 04:09:28.120602+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1845', '0.75', '2026-08-06 04:08:39.064655+00', '1536', 'text-embedding-3-small', NULL, 'The new hire understands their tasks but not how those tasks contribute to the company''s larger goals.', '["all"]', 'external', 'Stage 0→1', '251', 'Operational', 'RC-1845', 'No Explanation of How the New Hire''s Role Connects to the Bigger Picture', '2026-08-06 04:09:28.184014+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1846', '0.75', '2026-08-06 04:08:39.064655+00', '1536', 'text-embedding-3-small', NULL, 'Everything covered during onboarding is procedural — nothing addresses the purpose or context behind the work.', '["all"]', 'external', 'Stage 0→1', '251', 'Operational', 'RC-1846', 'Onboarding Stays Entirely Task- and Logistics-Focused', '2026-08-06 04:09:28.244818+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1847', '0.70', '2026-08-06 04:08:39.064655+00', '1536', 'text-embedding-3-small', NULL, 'There is a belief that understanding of the mission and customers will simply emerge through exposure, without needing to be taught directly.', '["all"]', 'external', 'Stage 0→1', '251', 'Psychological', 'RC-1847', 'Founder Assumes Context Will Be Picked Up Naturally Over Time', '2026-08-06 04:09:28.304712+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1848', '0.75', '2026-08-06 04:08:39.064655+00', '1536', 'text-embedding-3-small', NULL, 'Lacking context, the new hire''s judgment calls do not always align with what actually matters to the business.', '["all"]', 'external', 'Stage 0→1', '251', 'Strategic', 'RC-1848', 'New Hire Makes Decisions Without Understanding Business Priorities or Values', '2026-08-06 04:09:28.363781+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1849', '0.70', '2026-08-06 04:08:39.064655+00', '1536', 'text-embedding-3-small', NULL, 'Without understanding the bigger picture, a new hire can feel like they are just executing tasks rather than being part of something.', '["all"]', 'external', 'Stage 0→1', '251', 'Psychological', 'RC-1849', 'Lack of Context Contributes to Disengagement or Slower Sense of Belonging', '2026-08-06 04:09:28.427086+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1850', '0.85', '2026-08-06 04:16:13.663903+00', '1536', 'text-embedding-3-small', NULL, 'Good work goes by without any specific acknowledgment, so it passes unmarked.', '["all"]', 'external', 'Stage 0→1', '252', 'Behavioural', 'RC-1850', 'No Habit of Acknowledging Good Work When It Happens', '2026-08-06 04:17:04.842944+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1851', '0.80', '2026-08-06 04:16:13.663903+00', '1536', 'text-embedding-3-small', NULL, 'Not being told something is wrong is treated as the only signal of doing well, rather than actual positive feedback being given.', '["all"]', 'external', 'Stage 0→1', '252', 'Behavioural', 'RC-1851', 'Positive Feedback Only Implied by the Absence of Criticism', '2026-08-06 04:17:04.913988+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1852', '0.75', '2026-08-06 04:16:13.663903+00', '1536', 'text-embedding-3-small', NULL, 'Appreciation exists in the founder''s head but never actually gets communicated to the person who earned it.', '["all"]', 'external', 'Stage 0→1', '252', 'Psychological', 'RC-1852', 'Founder Notices Good Work Internally but Doesn''t Say It Out Loud', '2026-08-06 04:17:04.963486+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1853', '0.75', '2026-08-06 04:16:13.663903+00', '1536', 'text-embedding-3-small', NULL, 'There is no built-in point in any routine where good work gets called out deliberately.', '["all"]', 'external', 'Stage 0→1', '252', 'Operational', 'RC-1853', 'No Specific Moment or Process for Recognizing Achievements', '2026-08-06 04:17:05.015308+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1854', '0.75', '2026-08-06 04:16:13.663903+00', '1536', 'text-embedding-3-small', NULL, 'Whether someone gets acknowledged depends on chance rather than a reliable practice.', '["all"]', 'external', 'Stage 0→1', '252', 'Behavioural', 'RC-1854', 'Recognition Is Inconsistent and Depends on Founder''s Mood or Memory', '2026-08-06 04:17:05.064399+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1855', '0.75', '2026-08-06 04:16:13.663903+00', '1536', 'text-embedding-3-small', NULL, 'Without clear signals, people are left guessing whether their contributions actually matter.', '["all"]', 'external', 'Stage 0→1', '252', 'Psychological', 'RC-1855', 'Team Members Left Wondering Whether Their Work Is Actually Valued', '2026-08-06 04:17:05.116758+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1856', '0.75', '2026-08-06 04:16:13.663903+00', '1536', 'text-embedding-3-small', NULL, 'Over time, lack of acknowledgment can quietly erode motivation and make a good performer consider leaving.', '["all"]', 'external', 'Stage 0→1', '252', 'Strategic', 'RC-1856', 'Absence of Positive Reinforcement Contributes to Disengagement', '2026-08-06 04:17:05.173552+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1857', '0.85', '2026-08-06 04:19:23.662075+00', '1536', 'text-embedding-3-small', NULL, 'The conversation ends without any concrete plan for what should change going forward.', '["all"]', 'external', 'Stage 0→1', '253', 'Operational', 'RC-1857', 'No Improvement Plan Created After a Performance Conversation', '2026-08-06 04:20:12.044285+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1858', '0.85', '2026-08-06 04:19:23.662075+00', '1536', 'text-embedding-3-small', NULL, 'There is no date set to come back and check whether the discussed issue actually improved.', '["all"]', 'external', 'Stage 0→1', '253', 'Operational', 'RC-1858', 'No Follow-Up Check-In Scheduled to See If Things Changed', '2026-08-06 04:20:12.11608+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1859', '0.80', '2026-08-06 04:19:23.662075+00', '1536', 'text-embedding-3-small', NULL, 'Once the difficult conversation happens, it is treated as resolved rather than as the start of something to track.', '["all"]', 'external', 'Stage 0→1', '253', 'Behavioural', 'RC-1859', 'Conversation Treated as a One-Time Event Rather Than an Ongoing Process', '2026-08-06 04:20:12.186875+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1860', '0.75', '2026-08-06 04:19:23.662075+00', '1536', 'text-embedding-3-small', NULL, 'There is no clarity on what happens next if the issue discussed does not actually get better.', '["all"]', 'external', 'Stage 0→1', '253', 'Operational', 'RC-1860', 'No Consequence Defined if Performance Doesn''t Improve', '2026-08-06 04:20:12.251882+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1861', '0.75', '2026-08-06 04:19:23.662075+00', '1536', 'text-embedding-3-small', NULL, 'Without a real plan or follow-up, the underlying issue behind the conversation often comes back unchanged.', '["all"]', 'external', 'Stage 0→1', '253', 'Strategic', 'RC-1861', 'Same Performance Issue Resurfaces Because Nothing Structural Changed', '2026-08-06 04:20:12.309501+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1862', '0.70', '2026-08-06 04:19:23.662075+00', '1536', 'text-embedding-3-small', NULL, 'There is no written record of the conversation, so details and commitments are easy to forget or dispute later.', '["all"]', 'external', 'Stage 0→1', '253', 'Operational', 'RC-1862', 'No Documentation of What Was Discussed or Agreed To', '2026-08-06 04:20:12.371403+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1863', '0.70', '2026-08-06 04:19:23.662075+00', '1536', 'text-embedding-3-small', NULL, 'Having gotten through an uncomfortable conversation, there is a sense of relief that makes returning to the topic feel unnecessary.', '["all"]', 'external', 'Stage 0→1', '253', 'Psychological', 'RC-1863', 'Founder Relieved the Conversation Happened and Doesn''t Revisit It', '2026-08-06 04:20:12.436334+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1864', '0.85', '2026-08-06 04:25:21.940935+00', '1536', 'text-embedding-3-small', NULL, 'The format of any performance discussion is the founder delivering an assessment, with no space built in for the other side.', '["all"]', 'external', 'Stage 0→1', '254', 'Operational', 'RC-1864', 'Performance Conversations Structured as Founder Assessment Only', '2026-08-06 04:26:15.544459+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1865', '0.85', '2026-08-06 04:25:21.940935+00', '1536', 'text-embedding-3-small', NULL, 'The employee is never directly asked how they think they are performing before or during the conversation.', '["all"]', 'external', 'Stage 0→1', '254', 'Operational', 'RC-1865', 'Team Member Never Asked for Self-Assessment or Perspective', '2026-08-06 04:26:15.620569+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1866', '0.80', '2026-08-06 04:25:21.940935+00', '1536', 'text-embedding-3-small', NULL, 'There is no moment where the employee is invited to share what is getting in their way or what they need.', '["all"]', 'external', 'Stage 0→1', '254', 'Operational', 'RC-1866', 'No Opportunity for Employee to Raise Concerns or Support Needs', '2026-08-06 04:26:15.678744+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1867', '0.70', '2026-08-06 04:25:21.940935+00', '1536', 'text-embedding-3-small', NULL, 'There is a belief that the founder already has an accurate read on the employee''s own view of their performance, so it is never checked.', '["all"]', 'external', 'Stage 0→1', '254', 'Psychological', 'RC-1867', 'Founder Assumes They Already Know How the Employee Feels', '2026-08-06 04:26:15.73253+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1868', '0.75', '2026-08-06 04:25:21.940935+00', '1536', 'text-embedding-3-small', NULL, 'Even with good intentions, the structure of the conversation naturally centers the founder''s voice over the employee''s.', '["all"]', 'external', 'Stage 0→1', '254', 'Behavioural', 'RC-1868', 'Conversations Feel One-Directional Even When Well-Intentioned', '2026-08-06 04:26:15.795524+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1869', '0.75', '2026-08-06 04:25:21.940935+00', '1536', 'text-embedding-3-small', NULL, 'Without asking, the founder never learns what is actually getting in the way of the employee doing their best work.', '["all"]', 'external', 'Stage 0→1', '254', 'Strategic', 'RC-1869', 'Employee Perspective on Obstacles or Blockers Never Surfaces', '2026-08-06 04:26:15.851353+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1870', '0.70', '2026-08-06 04:25:21.940935+00', '1536', 'text-embedding-3-small', NULL, 'The overall pattern across the team reinforces that feedback flows one way, discouraging employees from speaking up even outside formal conversations.', '["all"]', 'external', 'Stage 0→1', '254', 'Strategic', 'RC-1870', 'Feedback Culture Stays Top-Down Rather Than a Genuine Dialogue', '2026-08-06 04:26:15.909815+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1871', '0.85', '2026-08-06 04:28:38.406604+00', '1536', 'text-embedding-3-small', NULL, 'What someone is evaluated on has no explicit link to what the business is actually trying to achieve right now.', '["all"]', 'external', 'Stage 0→1', '255', 'Strategic', 'RC-1871', 'Performance Criteria Not Tied to Current Business Priorities', '2026-08-06 04:29:31.40832+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1872', '0.80', '2026-08-06 04:28:38.406604+00', '1536', 'text-embedding-3-small', NULL, 'Performance discussion centers on broad, generic qualities rather than the specific outcomes the business needs.', '["all"]', 'external', 'Stage 0→1', '255', 'Operational', 'RC-1872', 'What Gets Tracked Stays Generic Rather Than Reflecting What Matters Most', '2026-08-06 04:29:31.47658+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1873', '0.75', '2026-08-06 04:28:38.406604+00', '1536', 'text-embedding-3-small', NULL, 'Even when what the business needs changes, what gets tracked or discussed in performance conversations stays the same.', '["all"]', 'external', 'Stage 0→1', '255', 'Operational', 'RC-1873', 'No Update to Performance Focus as Business Priorities Shift', '2026-08-06 04:29:31.532004+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1874', '0.80', '2026-08-06 04:28:38.406604+00', '1536', 'text-embedding-3-small', NULL, 'There is no clear line drawn between what a specific person is working toward and what the company is trying to achieve overall.', '["all"]', 'external', 'Stage 0→1', '255', 'Strategic', 'RC-1874', 'Individual Goals Never Explicitly Connected to Company-Level Goals', '2026-08-06 04:29:31.584508+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1875', '0.75', '2026-08-06 04:28:38.406604+00', '1536', 'text-embedding-3-small', NULL, 'Assessment relies on an overall sense of how someone is doing rather than specific results tied to what matters most.', '["all"]', 'external', 'Stage 0→1', '255', 'Behavioural', 'RC-1875', 'Founder Evaluates Based on General Impression Rather Than Priority Outcomes', '2026-08-06 04:29:31.642863+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1876', '0.70', '2026-08-06 04:28:38.406604+00', '1536', 'text-embedding-3-small', NULL, 'The actual tasks someone spends their time on do not clearly map to whatever criteria performance is being judged against.', '["all"]', 'external', 'Stage 0→1', '255', 'Operational', 'RC-1876', 'Team Member''s Day-to-Day Work May Not Obviously Connect to What''s Being Assessed', '2026-08-06 04:29:31.695368+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1877', '0.70', '2026-08-06 04:28:38.406604+00', '1536', 'text-embedding-3-small', NULL, 'Discussions about how someone is doing can feel like a separate exercise from the actual direction and priorities of the business.', '["all"]', 'external', 'Stage 0→1', '255', 'Strategic', 'RC-1877', 'Performance Conversations Feel Disconnected From What''s Strategically Important', '2026-08-06 04:29:31.750492+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1878', '0.85', '2026-08-06 04:36:21.534244+00', '1536', 'text-embedding-3-small', NULL, 'Each person''s performance is looked at entirely on its own, with no side-by-side view against the rest of the team.', '["all"]', 'external', 'Stage 0→1', '256', 'Operational', 'RC-1878', 'Performance Never Compared Across Team Members, Only Assessed Individually', '2026-08-06 04:37:27.853629+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1879', '0.85', '2026-08-06 04:36:21.534244+00', '1536', 'text-embedding-3-small', NULL, 'Without comparison, there is no clear signal about who stands out as ready to grow or who is quietly falling behind.', '["all"]', 'external', 'Stage 0→1', '256', 'Operational', 'RC-1879', 'No Way to Identify Who''s Ready for More Responsibility vs Who Needs Support', '2026-08-06 04:37:27.91726+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1880', '0.75', '2026-08-06 04:36:21.534244+00', '1536', 'text-embedding-3-small', NULL, 'There is no aggregate view of whether the team as a whole is improving, staying flat, or declining.', '["all"]', 'external', 'Stage 0→1', '256', 'Strategic', 'RC-1880', 'No Overall Sense of How the Team''s Performance Is Trending', '2026-08-06 04:37:27.969738+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1881', '0.75', '2026-08-06 04:36:21.534244+00', '1536', 'text-embedding-3-small', NULL, 'Without a comparative view, effort and attention are not directed toward the people who most need it or who show the most promise.', '["all"]', 'external', 'Stage 0→1', '256', 'Behavioural', 'RC-1881', 'Struggling and Excelling Team Members Get the Same Level of Attention', '2026-08-06 04:37:28.023334+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1882', '0.75', '2026-08-06 04:36:21.534244+00', '1536', 'text-embedding-3-small', NULL, 'Decisions like promotions or role changes are not informed by any structured comparison across the team.', '["all"]', 'external', 'Stage 0→1', '256', 'Operational', 'RC-1882', 'No Process for Using Relative Performance to Inform Decisions', '2026-08-06 04:37:28.075881+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1883', '0.70', '2026-08-06 04:36:21.534244+00', '1536', 'text-embedding-3-small', NULL, 'Performance discussions happen one person at a time, with nothing bringing them together into a single picture.', '["all"]', 'external', 'Stage 0→1', '256', 'Operational', 'RC-1883', 'Founder Lacks a Comparative View Because Conversations Stay Separate', '2026-08-06 04:37:28.250338+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1884', '0.70', '2026-08-06 04:36:21.534244+00', '1536', 'text-embedding-3-small', NULL, 'Without a comparison prompting the question, a standout performer''s readiness for more responsibility can be missed entirely.', '["all"]', 'external', 'Stage 0→1', '256', 'Strategic', 'RC-1884', 'High Performers'' Readiness for Growth Goes Unnoticed', '2026-08-06 04:37:28.301989+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1885', '0.85', '2026-08-06 04:40:15.252658+00', '1536', 'text-embedding-3-small', NULL, 'There is no designated place, digital or otherwise, where every written procedure is meant to live.', '["all"]', 'external', 'Stage 0→1', '257', 'Operational', 'RC-1885', 'No Single Repository or System Where SOPs Are Stored', '2026-08-06 04:41:07.708144+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1886', '0.85', '2026-08-06 04:40:15.252658+00', '1536', 'text-embedding-3-small', NULL, 'Whatever procedures do exist are spread across different tools and formats with no consistency.', '["all"]', 'external', 'Stage 0→1', '257', 'Operational', 'RC-1886', 'SOPs Scattered Across Emails, Chat Messages, and Random Documents', '2026-08-06 04:41:07.779739+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1887', '0.80', '2026-08-06 04:40:15.252658+00', '1536', 'text-embedding-3-small', NULL, 'A procedure can be documented somewhere and still go completely unused because nobody knows to look for it.', '["all"]', 'external', 'Stage 0→1', '257', 'Operational', 'RC-1887', 'Team Members Don''t Know SOPs Exist Even When Written', '2026-08-06 04:41:07.838494+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1888', '0.75', '2026-08-06 04:40:15.252658+00', '1536', 'text-embedding-3-small', NULL, 'Even within a single tool, there is no consistent system for organizing or naming procedures so they can be found.', '["all"]', 'external', 'Stage 0→1', '257', 'Operational', 'RC-1888', 'No Organized Folder Structure or Naming Convention', '2026-08-06 04:41:07.895543+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1889', '0.75', '2026-08-06 04:40:15.252658+00', '1536', 'text-embedding-3-small', NULL, 'Even if someone knows an SOP exists, locating it requires searching through disorganized places rather than a quick lookup.', '["all"]', 'external', 'Stage 0→1', '257', 'Operational', 'RC-1889', 'Finding a Specific SOP Takes Significant Effort', '2026-08-06 04:41:07.946756+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1890', '0.70', '2026-08-06 04:40:15.252658+00', '1536', 'text-embedding-3-small', NULL, 'Each new procedure gets created and saved wherever is convenient in the moment, adding to the disorganization over time.', '["all"]', 'external', 'Stage 0→1', '257', 'Operational', 'RC-1890', 'New SOPs Added Inconsistently Without Any Organizing System', '2026-08-06 04:41:08.004544+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1891', '0.75', '2026-08-06 04:40:15.252658+00', '1536', 'text-embedding-3-small', NULL, 'Even with a written procedure somewhere, it is often faster to just ask the founder directly, so the SOP never gets used.', '["all"]', 'external', 'Stage 0→1', '257', 'Behavioural', 'RC-1891', 'Team Defaults to Asking the Founder Because That''s Easier Than Finding the SOP', '2026-08-06 04:41:08.059584+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1892', '0.85', '2026-08-06 04:47:07.862006+00', '1536', 'text-embedding-3-small', NULL, 'There is no defined step that ever confirms whether work is happening according to the documented procedure.', '["all"]', 'external', 'Stage 0→1', '258', 'Operational', 'RC-1892', 'No Process for Checking Whether an SOP Is Actually Being Followed', '2026-08-06 04:48:03.336708+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1893', '0.85', '2026-08-06 04:47:07.862006+00', '1536', 'text-embedding-3-small', NULL, 'Someone can do a task their own way instead of following the SOP, and nothing catches that difference.', '["all"]', 'external', 'Stage 0→1', '258', 'Operational', 'RC-1893', 'Team Members Can Deviate From a Documented Procedure Without Anyone Noticing', '2026-08-06 04:48:03.43362+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1894', '0.80', '2026-08-06 04:47:07.862006+00', '1536', 'text-embedding-3-small', NULL, 'There is no periodic habit of comparing actual work against what the SOP says should happen.', '["all"]', 'external', 'Stage 0→1', '258', 'Operational', 'RC-1894', 'No Spot-Checks or Audits of Whether Work Matches the Written Process', '2026-08-06 04:48:03.491312+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1895', '0.75', '2026-08-06 04:47:07.862006+00', '1536', 'text-embedding-3-small', NULL, 'Writing the procedure down is treated as sufficient on its own, without checking that it translates into actual practice.', '["all"]', 'external', 'Stage 0→1', '258', 'Psychological', 'RC-1895', 'SOPs Assumed to Be Followed Simply Because They Exist', '2026-08-06 04:48:03.549657+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1896', '0.70', '2026-08-06 04:47:07.862006+00', '1536', 'text-embedding-3-small', NULL, 'What actually happens in practice never informs whether the written procedure needs to be reconsidered or updated.', '["all"]', 'external', 'Stage 0→1', '258', 'Operational', 'RC-1896', 'No Feedback Loop From Actual Practice Back Into Whether the SOP Still Makes Sense', '2026-08-06 04:48:03.605484+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1897', '0.70', '2026-08-06 04:47:07.862006+00', '1536', 'text-embedding-3-small', NULL, 'Even when a deviation is noticed, nobody digs into whether it happened because the SOP was wrong or the person made a mistake.', '["all"]', 'external', 'Stage 0→1', '258', 'Operational', 'RC-1897', 'Deviations From an SOP Never Investigated to Understand Why', '2026-08-06 04:48:03.658186+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1898', '0.75', '2026-08-06 04:47:07.862006+00', '1536', 'text-embedding-3-small', NULL, 'Without any verification loop, the gap between the documented process and real behavior widens the longer the SOP goes unchecked.', '["all"]', 'external', 'Stage 0→1', '258', 'Strategic', 'RC-1898', 'SOP Becomes Disconnected From What''s Actually Happening in Practice Over Time', '2026-08-06 04:48:03.716174+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1899', '0.85', '2026-08-06 04:50:43.55729+00', '1536', 'text-embedding-3-small', NULL, 'There is no framework or standard for choosing what gets written up before anything else.', '["all"]', 'external', 'Stage 0→1', '259', 'Operational', 'RC-1899', 'No Criteria Used to Decide Which Processes Should Be Documented First', '2026-08-06 04:51:36.541167+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1900', '0.80', '2026-08-06 04:50:43.55729+00', '1536', 'text-embedding-3-small', NULL, 'Documentation happens based on what happens to be top of mind at the time, not a deliberate assessment of value.', '["all"]', 'external', 'Stage 0→1', '259', 'Behavioural', 'RC-1900', 'SOPs Written for Whatever Comes to Mind Rather Than What Matters Most', '2026-08-06 04:51:36.602625+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1901', '0.80', '2026-08-06 04:50:43.55729+00', '1536', 'text-embedding-3-small', NULL, 'Tasks that happen constantly, which would benefit most from documentation, are not specifically flagged as priorities.', '["all"]', 'external', 'Stage 0→1', '259', 'Operational', 'RC-1901', 'No Identification of the Most Frequently Repeated Tasks as Priorities', '2026-08-06 04:51:36.650968+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1902', '0.80', '2026-08-06 04:50:43.55729+00', '1536', 'text-embedding-3-small', NULL, 'Tasks where a mistake would be costly are not specifically prioritized for documentation ahead of lower-stakes ones.', '["all"]', 'external', 'Stage 0→1', '259', 'Strategic', 'RC-1902', 'No Identification of the Highest-Risk Tasks as Priorities', '2026-08-06 04:51:36.709745+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1903', '0.75', '2026-08-06 04:50:43.55729+00', '1536', 'text-embedding-3-small', NULL, 'Effort gets spent writing up processes that matter less, while the ones that would actually help most remain unwritten.', '["all"]', 'external', 'Stage 0→1', '259', 'Operational', 'RC-1903', 'Time Spent Documenting Low-Value Processes While Critical Ones Stay Undocumented', '2026-08-06 04:51:36.756645+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1904', '0.70', '2026-08-06 04:50:43.55729+00', '1536', 'text-embedding-3-small', NULL, 'Even if priorities were once considered, they are not revisited as the business''s needs shift over time.', '["all"]', 'external', 'Stage 0→1', '259', 'Operational', 'RC-1904', 'No Process for Reassessing Documentation Priorities as the Business Changes', '2026-08-06 04:51:36.803575+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1905', '0.75', '2026-08-06 04:50:43.55729+00', '1536', 'text-embedding-3-small', NULL, 'There is no running list of undocumented processes, so it is unclear what gap actually exists.', '["all"]', 'external', 'Stage 0→1', '259', 'Operational', 'RC-1905', 'Founder Doesn''t Have a Clear List of What Still Needs to Be Documented', '2026-08-06 04:51:36.855541+00') on conflict do nothing;
