insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1907', '0.80', '2026-08-06 04:56:18.765203+00', '1536', 'text-embedding-3-small', NULL, 'A written procedure is treated as final, rather than something expected to evolve as understanding improves.', '["all"]', 'external', 'Stage 0→1', '260', 'Psychological', 'RC-1907', 'SOPs Treated as Fixed Once Written Rather Than Living Documents', '2026-08-06 04:57:49.548483+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1908', '0.80', '2026-08-06 04:56:18.765203+00', '1536', 'text-embedding-3-small', NULL, 'Even someone with a genuinely useful improvement has nowhere obvious to bring it.', '["all"]', 'external', 'Stage 0→1', '260', 'Operational', 'RC-1908', 'Team Members Who Spot a Better Way Have No Channel to Raise It', '2026-08-06 04:57:49.598627+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1909', '0.75', '2026-08-06 04:56:18.765203+00', '1536', 'text-embedding-3-small', NULL, 'Feedback on documented processes is never proactively solicited from the people actually using them.', '["all"]', 'external', 'Stage 0→1', '260', 'Behavioural', 'RC-1909', 'Founder Doesn''t Actively Ask for Input on Whether SOPs Work Well', '2026-08-06 04:57:49.653038+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1910', '0.70', '2026-08-06 04:56:18.765203+00', '1536', 'text-embedding-3-small', NULL, 'Even when a suggestion is made in passing, it does not translate into an actual update to the SOP.', '["all"]', 'external', 'Stage 0→1', '260', 'Operational', 'RC-1910', 'Informal Suggestions Don''t Get Incorporated Into the Actual Document', '2026-08-06 04:57:49.701011+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1911', '0.70', '2026-08-06 04:56:18.765203+00', '1536', 'text-embedding-3-small', NULL, 'Nothing encourages or normalizes the practice of raising concerns about a documented process.', '["all"]', 'external', 'Stage 0→1', '260', 'Behavioural', 'RC-1911', 'No Incentive or Habit for Team Members to Flag SOP Issues', '2026-08-06 04:57:49.751655+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1912', '0.75', '2026-08-06 04:56:18.765203+00', '1536', 'text-embedding-3-small', NULL, 'Knowledge about what actually works best never travels from the person doing the work into the shared documentation.', '["all"]', 'external', 'Stage 0→1', '260', 'Strategic', 'RC-1912', 'Valuable Frontline Insight Stays With the Person Doing the Task', '2026-08-06 04:57:49.798573+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1913', '0.85', '2026-08-06 05:01:01.206114+00', '1536', 'text-embedding-3-small', NULL, 'The same rule gets enforced strictly for one person and loosely for another, without any consistent basis.', '["all"]', 'external', 'Stage 0→1', '261', 'Behavioural', 'RC-1913', 'Policies Applied Differently Depending on Who''s Involved', '2026-08-06 05:01:53.677214+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1914', '0.80', '2026-08-06 05:01:01.206114+00', '1536', 'text-embedding-3-small', NULL, 'There is no defined criteria for when it is okay to deviate from a policy, so exceptions happen ad hoc.', '["all"]', 'external', 'Stage 0→1', '261', 'Operational', 'RC-1914', 'No Clear Process for Deciding When an Exception Is Acceptable', '2026-08-06 05:01:53.746454+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1915', '0.80', '2026-08-06 05:01:01.206114+00', '1536', 'text-embedding-3-small', NULL, 'Whether an exception gets made depends on how the founder feels about the person or situation in the moment, not a consistent standard.', '["all"]', 'external', 'Stage 0→1', '261', 'Psychological', 'RC-1915', 'Founder Makes Exceptions Based on Relationship or Mood', '2026-08-06 05:01:53.802372+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1916', '0.75', '2026-08-06 05:01:01.206114+00', '1536', 'text-embedding-3-small', NULL, 'Visible unevenness in how policies are applied erodes the team''s confidence that the rules mean anything.', '["all"]', 'external', 'Stage 0→1', '261', 'Strategic', 'RC-1916', 'Team Notices Inconsistent Enforcement, Undermining Trust', '2026-08-06 05:01:53.859751+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1917', '0.70', '2026-08-06 05:01:01.206114+00', '1536', 'text-embedding-3-small', NULL, 'Exceptions are not recorded anywhere, so patterns of unfair treatment can build up unnoticed over time.', '["all"]', 'external', 'Stage 0→1', '261', 'Operational', 'RC-1917', 'No Documentation of Exceptions Made', '2026-08-06 05:01:53.915201+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1918', '0.75', '2026-08-06 05:01:01.206114+00', '1536', 'text-embedding-3-small', NULL, 'Uneven application of policy can create real legal exposure or fairness issues that stay invisible until they surface as a problem.', '["all"]', 'external', 'Stage 0→1', '261', 'Strategic', 'RC-1918', 'Inconsistent Enforcement Creates Legal or Fairness Risk Unnoticed', '2026-08-06 05:01:53.968565+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1919', '0.70', '2026-08-06 05:01:01.206114+00', '1536', 'text-embedding-3-small', NULL, 'Rules get suddenly enforced tightly in reaction to one bad situation, rather than being applied consistently all along.', '["all"]', 'external', 'Stage 0→1', '261', 'Behavioural', 'RC-1919', 'Policies Enforced Strictly Only After a Specific Incident', '2026-08-06 05:01:54.021856+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1920', '0.85', '2026-08-06 05:05:20.708777+00', '1536', 'text-embedding-3-small', NULL, 'A policy gets shared without any accompanying step that confirms it was received and understood.', '["all"]', 'external', 'Stage 0→1', '262', 'Operational', 'RC-1920', 'No Signature or Acknowledgment Step When a Policy Is Introduced', '2026-08-06 05:07:25.180875+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1921', '0.85', '2026-08-06 05:05:20.708777+00', '1536', 'text-embedding-3-small', NULL, 'Onboarding does not include a moment where the new hire explicitly confirms they have reviewed company policies.', '["all"]', 'external', 'Stage 0→1', '262', 'Operational', 'RC-1921', 'New Hires Never Asked to Confirm They''ve Read the Handbook or Policies', '2026-08-06 05:07:25.24417+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1922', '0.80', '2026-08-06 05:05:20.708777+00', '1536', 'text-embedding-3-small', NULL, 'There is no tracking system showing which team members have actually confirmed reading a specific policy.', '["all"]', 'external', 'Stage 0→1', '262', 'Operational', 'RC-1922', 'No Record Showing Who Has and Hasn''t Acknowledged a Given Policy', '2026-08-06 05:07:25.302708+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1923', '0.75', '2026-08-06 05:05:20.708777+00', '1536', 'text-embedding-3-small', NULL, 'When a policy is revised, there is no process for making sure the team knows about the change and confirms they''ve seen it.', '["all"]', 'external', 'Stage 0→1', '262', 'Operational', 'RC-1923', 'Policy Updates Not Re-Communicated or Re-Acknowledged When They Change', '2026-08-06 05:07:25.358203+00') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "confidence_weight", "created_at", "embedding_dimension", "embedding_model", "embedding_version", "explanation", "industry_relevance", "layer", "primary_stage_group", "problem_id", "root_cause_category", "root_cause_code", "root_cause_name", "updated_at") values ('1924', '0.75', '2026-08-06 05:05:20.708777+00', '1536', 'text-embedding-3-small', NULL, 'Sending a document is treated as equivalent to it being read and understood, without any verification.', '["all"]', 'external', 'Stage 0→1', '262', 'Psychological', 'RC-1924', 'Founder Assumes People Have Read Policies Simply Because They Were Shared', '2026-08-06 05:07:25.413706+00') on conflict do nothing;
